final_template:
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

variable "framework_name" {
  type        = string
  description = "The name and description of the AWS Backup framework."
  default     = "benchmark"
}

variable "tag_key" {
  type        = string
  description = "The tag key applied to the AWS Backup framework."
  default     = "BenchmarkTag"
}

resource "null_resource" "benchmark_tracker" {}

resource "aws_backup_framework" "benchmark" {
  name        = var.framework_name
  description = var.framework_name

  control {
    name = "BACKUP_RESOURCES_PROTECTED_BY_BACKUP_PLAN"

    scope {
      compliance_resource_types = [
        "EBS"
      ]
    }
  }

  tags = {
    (var.tag_key) = null_resource.benchmark_tracker.id
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  role_name = "lambda_vpc_efs_execution_role"
  tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_vpc_efs_execution_role" {
  name               = local.role_name
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
  tags               = local.tags
}

resource "aws_iam_role_policy_attachment" "lambda_vpc_access" {
  role       = aws_iam_role.lambda_vpc_efs_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole"
}

resource "aws_iam_role_policy_attachment" "efs_client_full_access" {
  role       = aws_iam_role.lambda_vpc_efs_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonElasticFileSystemClientFullAccess"
}

output "lambda_execution_role_arn" {
  description = "The ARN of the IAM execution role for the Lambda function"
  value       = aws_iam_role.lambda_vpc_efs_execution_role.arn
}

output "lambda_execution_role_name" {
  description = "The name of the IAM execution role for the Lambda function"
  value       = aws_iam_role.lambda_vpc_efs_execution_role.name
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "instance_id" {
  description = "Optional EC2 instance ID to associate with the Elastic IP."
  type        = string
  default     = ""
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-1"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "main" {
  domain   = "vpc"
  instance = var.instance_id != "" ? var.instance_id : null

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "main-eip"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block                       = "10.0.0.0/16"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = "test-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "test-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id                          = aws_vpc.main.id
  cidr_block                      = "10.0.1.0/24"
  availability_zone               = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch         = true
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, 1)
  assign_ipv6_address_on_creation = true

  tags = {
    Name = "test-public-subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "test-private-subnet"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = {
    Name = "test-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "test-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

locals {
  account_id   = data.aws_caller_identity.current.account_id
  list_buckets = ["bucket101", "bucket102"]
  map_buckets = {
    "bucket103" = "bucket103"
    "bucket104" = "bucket104"
  }
}

# KMS Key for S3 Encryption
resource "aws_kms_key" "s3_key" {
  description             = "Customer managed KMS key for S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "s3_key_alias" {
  name          = "alias/s3-bucket-shared-key"
  target_key_id = aws_kms_key.s3_key.key_id
}

# 1. Standalone Bucket: bucket2
resource "aws_s3_bucket" "standalone" {
  bucket = "${local.account_id}-bucket2"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "standalone" {
  bucket = aws_s3_bucket.standalone.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "standalone" {
  bucket = aws_s3_bucket.standalone.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "standalone" {
  bucket = aws_s3_bucket.standalone.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# 2. Count-based Buckets: bucket3, bucket4
resource "aws_s3_bucket" "count_buckets" {
  count  = 2
  bucket = "${local.account_id}-bucket${count.index + 3}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "count_buckets" {
  count  = 2
  bucket = aws_s3_bucket.count_buckets[count.index].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "count_buckets" {
  count  = 2
  bucket = aws_s3_bucket.count_buckets[count.index].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "count_buckets" {
  count  = 2
  bucket = aws_s3_bucket.count_buckets[count.index].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# 3. For-each List Buckets: bucket101, bucket102
resource "aws_s3_bucket" "list_buckets" {
  for_each = toset(local.list_buckets)
  bucket   = "${local.account_id}-${each.value}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "list_buckets" {
  for_each = aws_s3_bucket.list_buckets
  bucket   = each.value.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "list_buckets" {
  for_each = aws_s3_bucket.list_buckets
  bucket   = each.value.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "list_buckets" {
  for_each = aws_s3_bucket.list_buckets
  bucket   = each.value.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# 4. For-each Map Buckets: bucket103, bucket104
resource "aws_s3_bucket" "map_buckets" {
  for_each = local.map_buckets
  bucket   = "${local.account_id}-${each.value}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "map_buckets" {
  for_each = aws_s3_bucket.map_buckets
  bucket   = each.value.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "map_buckets" {
  for_each = aws_s3_bucket.map_buckets
  bucket   = each.value.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "map_buckets" {
  for_each = aws_s3_bucket.map_buckets
  bucket   = each.value.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

locals {
  account_id   = data.aws_caller_identity.current.account_id
  budget_name  = "budget"
  email_target = "hello@chriswilding.co.uk"
  sms_target   = "+447828835419"
}

data "aws_iam_policy_document" "kms_policy" {
  statement {
    sid       = "EnableRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowBudgetsToUseKmsKey"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["budgets.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "budget_key" {
  description             = "KMS key for AWS Budgets SNS notification topic"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_policy.json
}

resource "aws_kms_alias" "budget_key_alias" {
  name          = "alias/budget-key"
  target_key_id = aws_kms_key.budget_key.key_id
}

resource "aws_sns_topic" "budget" {
  name              = local.budget_name
  kms_master_key_id = aws_kms_key.budget_key.arn
}

data "aws_iam_policy_document" "sns_topic_policy" {
  statement {
    sid    = "AllowBudgetsToPublish"
    effect = "Allow"
    actions = [
      "sns:Publish"
    ]
    resources = [
      aws_sns_topic.budget.arn
    ]

    principals {
      type        = "Service"
      identifiers = ["budgets.amazonaws.com"]
    }
  }
}

resource "aws_sns_topic_policy" "budget" {
  arn    = aws_sns_topic.budget.arn
  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

resource "aws_sns_topic_subscription" "sms" {
  topic_arn = aws_sns_topic.budget.arn
  protocol  = "sms"
  endpoint  = local.sms_target
}

resource "aws_budgets_budget" "budget" {
  name              = local.budget_name
  budget_type       = "COST"
  limit_amount      = "25.0"
  limit_unit        = "USD"
  time_unit         = "MONTHLY"
  time_period_start = "2021-07-01_00:00"

  notification {
    comparison_operator        = "GREATER_THAN"
    threshold                  = 100
    threshold_type             = "PERCENTAGE"
    notification_type          = "ACTUAL"
    subscriber_email_addresses = [local.email_target]
    subscriber_sns_topic_arns  = [aws_sns_topic.budget.arn]
  }

  depends_on = [
    aws_sns_topic_policy.budget
  ]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  ecr_repo_name = "reactjs-app-repo"
  role_name     = "ecsTaskExecutionRole"
}

resource "aws_ecr_repository" "reactjs_app_repo" {
  name                 = local.ecr_repo_name
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "AES256"
  }

  tags = {
    Name        = local.ecr_repo_name
    Environment = "production"
  }
}

data "aws_iam_policy_document" "ecs_task_execution_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_task_execution_role" {
  name               = local.role_name
  assume_role_policy = data.aws_iam_policy_document.ecs_task_execution_assume_role.json

  tags = {
    Name        = local.role_name
    Environment = "production"
  }
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution_role_policy" {
  role       = aws_iam_role.ecs_task_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

output "ecr_repository_url" {
  description = "The URL of the Amazon ECR repository"
  value       = aws_ecr_repository.reactjs_app_repo.repository_url
}

output "ecr_repository_arn" {
  description = "The ARN of the Amazon ECR repository"
  value       = aws_ecr_repository.reactjs_app_repo.arn
}

output "ecs_task_execution_role_arn" {
  description = "The ARN of the ECS task execution IAM role"
  value       = aws_iam_role.ecs_task_execution_role.arn
}

output "ecs_task_execution_role_name" {
  description = "The name of the ECS task execution IAM role"
  value       = aws_iam_role.ecs_task_execution_role.name
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "role" {
  name               = "role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

data "aws_iam_policy_document" "allow_policy_1" {
  statement {
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "allow_policy_1" {
  name   = "allow-policy-1"
  role   = aws_iam_role.role.name
  policy = data.aws_iam_policy_document.allow_policy_1.json
}

data "aws_iam_policy_document" "allow_policy_2" {
  statement {
    effect = "Allow"
    actions = [
      "lambda:CreateFunction",
      "lambda:invokefunc*"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "allow_policy_2" {
  name   = "allow-policy-2"
  role   = aws_iam_role.role.name
  policy = data.aws_iam_policy_document.allow_policy_2.json
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

resource "aws_efs_file_system" "efs" {
  creation_token = "efs-not-secure"
  encrypted      = true

  tags = {
    Name = "NotSecure"
  }

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "efs_policy" {
  policy_id = "ExamplePolicy01"

  statement {
    sid    = "ExampleStatement01"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = [
      "elasticfilesystem:*"
    ]

    resources = [
      aws_efs_file_system.efs.arn
    ]
  }
}

resource "aws_efs_file_system_policy" "efs_policy" {
  file_system_id = aws_efs_file_system.efs.id
  policy         = data.aws_iam_policy_document.efs_policy.json
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

resource "aws_kms_key" "terraform_state" {
  description             = "Dedicated KMS key for Terraform remote state S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name    = "terraform-remote-state-key"
    Purpose = "Terraform State Storage Encryption"
  }
}

resource "aws_kms_alias" "terraform_state" {
  name          = "alias/terraform-remote-state-key"
  target_key_id = aws_kms_key.terraform_state.key_id
}

resource "aws_s3_bucket" "terraform_state" {
  bucket = "terraform-remote-state-storage-s3-kjg"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name    = "terraform-remote-state-storage-s3-kjg"
    Purpose = "Terraform Remote State Storage"
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.terraform_state.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_dynamodb_table" "terraform_state_lock" {
  name           = "terraform-state-lock-dynamo"
  billing_mode   = "PROVISIONED"
  read_capacity  = 20
  write_capacity = 20
  hash_key       = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name    = "terraform-state-lock-dynamo"
    Purpose = "Terraform State Locking"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

resource "random_pet" "log_group_suffix" {
  length    = 2
  separator = "-"
}

resource "aws_cloudwatch_log_group" "dynamic_log_group" {
  name              = "log-group-${random_pet.log_group_suffix.id}"
  retention_in_days = 30

  tags = {
    Environment = "production"
    Project     = "logging"
    ManagedBy   = "terraform"
  }
}

output "cloudwatch_log_group_name" {
  description = "The name of the created CloudWatch log group."
  value       = aws_cloudwatch_log_group.dynamic_log_group.name
}

output "cloudwatch_log_group_arn" {
  description = "The ARN of the created CloudWatch log group."
