terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "bucket_name" {
  type        = string
  description = "The name of the S3 bucket for benchmarking"
  default     = "benchmark-bucket-tf5x"
}

variable "name_tag" {
  type        = string
  description = "The Name tag value for resources"
  default     = "benchmark"
}

variable "force_destroy" {
  type        = bool
  description = "Whether to enable force destroy on the S3 bucket"
  default     = true
}

resource "aws_kms_key" "benchmark_key" {
  description             = "Customer-managed KMS key for S3 benchmark bucket SSE-KMS encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name = var.name_tag
  }
}

resource "aws_kms_alias" "benchmark_key_alias" {
  name          = "alias/benchmark-s3-key"
  target_key_id = aws_kms_key.benchmark_key.key_id
}

resource "aws_s3_bucket" "benchmark_bucket" {
  bucket        = var.bucket_name
  force_destroy = var.force_destroy

  tags = {
    Name = var.name_tag
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "benchmark_bucket_encryption" {
  bucket = aws_s3_bucket.benchmark_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.benchmark_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "benchmark_bucket_pab" {
  bucket = aws_s3_bucket.benchmark_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_account_public_access_block" "account_pab" {
  block_public_acls       = false
  ignore_public_acls      = false
  block_public_policy     = false
  restrict_public_buckets = false
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "base_name" {
  type        = string
  description = "Base name prefix for the CloudTrail S3 bucket"
  default     = "benchmark"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowCloudTrailToEncryptLogs"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = ["arn:${data.aws_partition.current.partition}:cloudtrail:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:trail/*"]
    }

    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values   = ["arn:${data.aws_partition.current.partition}:cloudtrail:*:${data.aws_caller_identity.current.account_id}:trail/*"]
    }
  }
}

resource "aws_kms_key" "cloudtrail_key" {
  description             = "KMS key for CloudTrail S3 bucket server-side encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
}

resource "aws_kms_alias" "cloudtrail_key_alias" {
  name          = "alias/${var.base_name}-cloudtrail-key"
  target_key_id = aws_kms_key.cloudtrail_key.key_id
}

resource "aws_s3_bucket" "cloudtrail_bucket" {
  bucket        = "${var.base_name}-cloudtrail-${data.aws_region.current.name}"
  force_destroy = true
}

resource "aws_s3_bucket_versioning" "cloudtrail_bucket_versioning" {
  bucket = aws_s3_bucket.cloudtrail_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_bucket_encryption" {
  bucket = aws_s3_bucket.cloudtrail_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cloudtrail_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_bucket_pab" {
  bucket = aws_s3_bucket.cloudtrail_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "cloudtrail_bucket_policy" {
  statement {
    sid       = "AWSCloudTrailAclCheck"
    effect    = "Allow"
    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail_bucket.arn]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
  }

  statement {
    sid       = "AWSCloudTrailWrite"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail_bucket.arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_bucket_policy" {
  bucket     = aws_s3_bucket.cloudtrail_bucket.id
  policy     = data.aws_iam_policy_document.cloudtrail_bucket_policy.json
  depends_on = [aws_s3_bucket_public_access_block.cloudtrail_bucket_pab]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "app_name" {
  type        = string
  description = "The display name of the application."
  default     = "Trilium Notes"
}

variable "app" {
  type        = string
  description = "The short name identifier for the application."
  default     = "trilium"
}

variable "module" {
  type        = string
  description = "The module name identifier."
  default     = "log"
}

variable "stage" {
  type        = string
  description = "The deployment stage/environment."
  default     = "production"
}

variable "log_retention" {
  type        = number
  description = "Specifies the number of days you want to retain log events in the log groups."
  default     = 120
}

locals {
  app_log_group_name   = "cwlg-${var.app}-${var.module}-${var.stage}-app"
  proxy_log_group_name = "cwlg-${var.app}-${var.module}-${var.stage}-proxy"
  common_tags = {
    App    = var.app
    Module = var.module
    Stage  = var.stage
  }
}

resource "aws_cloudwatch_log_group" "app_logs" {
  name              = local.app_log_group_name
  retention_in_days = var.log_retention

  tags = merge(
    local.common_tags,
    {
      Name = local.app_log_group_name
    }
  )
}

resource "aws_cloudwatch_log_group" "proxy_logs" {
  name              = local.proxy_log_group_name
  retention_in_days = var.log_retention

  tags = merge(
    local.common_tags,
    {
      Name = local.proxy_log_group_name
    }
  )
}

