terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
  }
}

variable "key_prefix" {
  description = "Prefix for the AWS key pair name"
  type        = string
  default     = "key"
}

resource "random_pet" "key_suffix" {
  length    = 2
  separator = "-"
}

locals {
  key_name = "${var.key_prefix}-${random_pet.key_suffix.id}"
}

resource "tls_private_key" "ssh_key" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "generated_key" {
  key_name   = local.key_name
  public_key = tls_private_key.ssh_key.public_key_openssh

  provisioner "local-exec" {
    command = <<-EOT
      echo "${tls_private_key.ssh_key.private_key_pem}" > ../${local.key_name}.pem
      chmod 600 ../${local.key_name}.pem
    EOT
  }
}

resource "local_sensitive_file" "private_key" {
  content         = tls_private_key.ssh_key.private_key_pem
  filename        = "../${local.key_name}.pem"
  file_permission = "0600"
}

output "key_name" {
  description = "The name of the created EC2 key pair"
  value       = aws_key_pair.generated_key.key_name
}

output "key_pair_id" {
  description = "The ID of the created EC2 key pair"
  value       = aws_key_pair.generated_key.key_pair_id
}

output "public_key_fingerprint" {
  description = "The fingerprint of the generated public key"
  value       = aws_key_pair.generated_key.fingerprint
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_security_group" "web_sg" {
  name        = "Example security group"
  description = "Security group allowing HTTP and HTTPS ingress traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    description      = "Allow HTTP inbound traffic"
    from_port        = 80
    to_port          = 80
    protocol         = "tcp"
    cidr_blocks      = ["0.0.0.0/0"]
    ipv6_cidr_blocks = []
  }

  ingress {
    description      = "Allow HTTPS inbound traffic"
    from_port        = 443
    to_port          = 443
    protocol         = "tcp"
    cidr_blocks      = ["0.0.0.0/0"]
    ipv6_cidr_blocks = []
  }

  egress {
    description      = "Allow all outbound traffic"
    from_port        = 0
    to_port          = 0
    protocol         = "-1"
    cidr_blocks      = ["0.0.0.0/0"]
    ipv6_cidr_blocks = []
  }

  tags = {
    Name = "example-security-group"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "example" {
  name        = "example"
  description = "Example security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "example"
  }
}

resource "aws_vpc_security_group_ingress_rule" "ssh" {
  security_group_id = aws_security_group.example.id
  description       = "Allow SSH from within VPC"
  cidr_ipv4         = aws_vpc.main.cidr_block
  from_port         = 22
  ip_protocol       = "tcp"
  to_port           = 22
}

resource "aws_vpc_security_group_egress_rule" "all_vpc" {
  security_group_id = aws_security_group.example.id
  description       = "Allow outbound traffic only within VPC"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "-1"
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "repository_name" {
  description = "The name of the ECR repository"
  type        = string
  default     = "illumidesk"
}

variable "tags" {
  description = "A map of tags to assign to the repository"
  type        = map(string)
  default = {
    Name        = "illumidesk-eks"
    Environment = "dev"
  }
}

resource "aws_ecr_repository" "illumidesk" {
  name                 = var.repository_name
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = var.tags
}

resource "aws_ecr_lifecycle_policy" "illumidesk" {
  repository = aws_ecr_repository.illumidesk.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images older than 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      },
      {
        rulePriority = 2
        description  = "Expire images when total image count exceeds 30"
        selection = {
          tagStatus   = "any"
          countType   = "imageCountMoreThan"
          countNumber = 30
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

output "repository_url" {
  description = "The URL of the repository"
  value       = aws_ecr_repository.illumidesk.repository_url
}

output "arn" {
  description = "The ARN of the repository"
  value       = aws_ecr_repository.illumidesk.arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region for the resources"
  default     = "us-east-1"
}

variable "secret_name" {
  type        = string
  description = "Name of the AWS Secrets Manager secret storing authentication credentials"
  default     = "lambda-auth-credentials"
}

variable "default_username" {
  type        = string
  description = "Default username stored in the secret"
  default     = "techlanches"
}

variable "default_email" {
  type        = string
  description = "Default email stored in the secret"
  default     = "g12.4soat.fiap@outlook.com"
}

variable "default_password" {
  type        = string
  description = "Default password stored in the secret"
  default     = "Test1234@"
  sensitive   = true
}

resource "aws_cognito_user_pool" "tech_lanches_clientes_pool" {
  name                     = "tech-lanches-clientes-pool"
  mfa_configuration        = "OFF"
  auto_verified_attributes = ["email"]
  alias_attributes         = ["email", "preferred_username"]

  username_configuration {
    case_sensitive = false
  }

  tags = {
    Name = "tech_lanches_clientes_pool"
  }
}

resource "aws_cognito_user_pool_client" "pool_client" {
  name         = "pool-client"
  user_pool_id = aws_cognito_user_pool.tech_lanches_clientes_pool.id

  explicit_auth_flows = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH"
  ]
}

resource "aws_secretsmanager_secret" "lambda_auth_credentials" {
  name                    = var.secret_name
  recovery_window_in_days = 0

  tags = {
    Name = var.secret_name
  }
}

resource "aws_secretsmanager_secret_version" "lambda_auth_credentials" {
  secret_id = aws_secretsmanager_secret.lambda_auth_credentials.id
  secret_string = jsonencode({
    region        = var.aws_region
    user_pool_id  = aws_cognito_user_pool.tech_lanches_clientes_pool.id
    client_id     = aws_cognito_user_pool_client.pool_client.id
    username      = var.default_username
    email         = var.default_email
    password      = var.default_password
  })
}

output "cognito_user_pool_id" {
  description = "ID of the Cognito User Pool"
  value       = aws_cognito_user_pool.tech_lanches_clientes_pool.id
}

output "cognito_user_pool_client_id" {
  description = "ID of the Cognito User Pool Client"
  value       = aws_cognito_user_pool_client.pool_client.id
}

output "secrets_manager_secret_arn" {
  description = "ARN of the Secrets Manager secret"
  value       = aws_secretsmanager_secret.lambda_auth_credentials.arn
}

