terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  environment              = "production"
  delay_seconds            = 90
  max_message_size         = 2048
  message_retention_seconds = 86400
  receive_wait_time_seconds = 10
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowSQSServiceUsage"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "sqs_key" {
  description             = "KMS customer managed key for SQS server-side encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = {
    Environment = local.environment
  }
}

resource "aws_kms_alias" "sqs_key_alias" {
  name          = "alias/sqs-test-key"
  target_key_id = aws_kms_key.sqs_key.id
}

resource "aws_sqs_queue" "test_sqs" {
  name                       = "test-sqs"
  delay_seconds              = local.delay_seconds
  max_message_size           = local.max_message_size
  message_retention_seconds  = local.message_retention_seconds
  receive_wait_time_seconds  = local.receive_wait_time_seconds
  kms_master_key_id          = aws_kms_key.sqs_key.arn
  kms_data_key_reuse_period_seconds = 300

  tags = {
    Environment = local.environment
  }
}

resource "aws_sqs_queue" "test_sqs1" {
  name                       = "test-sqs1"
  delay_seconds              = local.delay_seconds
  max_message_size           = local.max_message_size
  message_retention_seconds  = local.message_retention_seconds
  receive_wait_time_seconds  = local.receive_wait_time_seconds
  kms_master_key_id          = aws_kms_key.sqs_key.arn
  kms_data_key_reuse_period_seconds = 300

  tags = {
    Environment = local.environment
  }
}

output "kms_key_arn" {
  description = "The ARN of the KMS key used for SQS encryption"
  value       = aws_kms_key.sqs_key.arn
}

output "test_sqs_url" {
  description = "The URL of the test-sqs queue"
