terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region for the resources"
  default     = "us-east-1"
}

variable "base_bucket_name" {
  type        = string
  description = "Base name for the S3 bucket"
  default     = "doc-io-files"
}

variable "force_destroy" {
  type        = bool
  description = "Controls whether to force destroy the bucket even if it contains objects"
  default     = true
}

variable "trusted_account_id" {
  type        = string
  description = "AWS account ID granted full access to the S3 bucket"
  default     = "566373416292"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

resource "random_integer" "bucket_prefix" {
  min = 1
  max = 50000
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowTrustedAccountKeyUse"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${var.trusted_account_id}:root"]
    }
  }
}

resource "aws_kms_key" "doc_io_key" {
  description             = "Customer-managed KMS key for document I/O S3 bucket SSE encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = {
    Name = "doc-io-kms-key"
  }
}

resource "aws_kms_alias" "doc_io_key_alias" {
  name          = "alias/doc-io-files-key"
  target_key_id = aws_kms_key.doc_io_key.key_id
}

resource "aws_s3_bucket" "doc_io" {
  bucket        = "${random_integer.bucket_prefix.result}-${var.base_bucket_name}"
  force_destroy = var.force_destroy

  tags = {
    Name = "${random_integer.bucket_prefix.result}-${var.base_bucket_name}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "doc_io" {
  bucket = aws_s3_bucket.doc_io.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "doc_io" {
  bucket = aws_s3_bucket.doc_io.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.doc_io_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

data "aws_iam_policy_document" "bucket_policy" {
  statement {
    sid    = "AllowTrustedAccountFullAccess"
    effect = "Allow"
    actions = [
      "s3:*"
    ]
    resources = [
      aws_s3_bucket.doc_io.arn,
      "${aws_s3_bucket.doc_io.arn}/*"
    ]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${var.trusted_account_id}:root"]
    }
  }
}

resource "aws_s3_bucket_policy" "doc_io" {
  bucket     = aws_s3_bucket.doc_io.id
  policy     = data.aws_iam_policy_document.bucket_policy.json
  depends_on = [aws_s3_bucket_public_access_block.doc_io]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_security_group" "allow_tcp" {
  name        = "allow_tcp"
  description = "Allow TCP traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow outbound TCP on port 10000"
    from_port   = 10000
    to_port     = 10000
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow_tcp"
  }
}

resource "aws_security_group" "allow_udp" {
  name        = "allow_udp"
  description = "Allow UDP traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow outbound UDP on port 10000"
    from_port   = 10000
    to_port     = 10000
    protocol    = "udp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow_udp"
  }
}

resource "aws_security_group" "allow_icmp" {
  name        = "allow_icmp"
  description = "Allow ICMP traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow outbound ICMP traffic"
    from_port   = 10000
    to_port     = 10000
    protocol    = "icmp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow_icmp"
  }
}

resource "aws_security_group" "allow_all" {
  name        = "allow_all"
  description = "Allow ALL traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow_all"
  }
}

