data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowSNSServiceEncryption"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "sns" {
  description             = "Customer managed KMS key for SNS topic encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
}

resource "aws_kms_alias" "sns" {
  name          = "alias/sns-integration-key"
  target_key_id = aws_kms_key.sns.key_id
}

resource "aws_sns_topic" "my_topic_with_policy" {
  name              = "my-topic-with-policy"
  kms_master_key_id = aws_kms_key.sns.arn
}

resource "aws_sns_topic" "my_topic_with_policy2" {
  name              = "my-topic-with-policy2"
  kms_master_key_id = aws_kms_key.sns.arn
}

data "aws_iam_policy_document" "sns_shared_policy" {
  statement {
    sid       = "AllowAllPrincipalsFullSNSOnFirstTopic"
    effect    = "Allow"
    actions   = ["SNS:*"]
    resources = [aws_sns_topic.my_topic_with_policy.arn]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
  }
}

resource "aws_sns_topic_policy" "my_topic_with_policy" {
  arn    = aws_sns_topic.my_topic_with_policy.arn
  policy = data.aws_iam_policy_document.sns_shared_policy.json
}

resource "aws_sns_topic_policy" "my_topic_with_policy2" {
  arn    = aws_sns_topic.my_topic_with_policy2.arn
  policy = data.aws_iam_policy_document.sns_shared_policy.json
}

resource "aws_sns_topic" "user_updates_topic" {
  name              = "user-updates-topic"
  kms_master_key_id = aws_kms_key.sns.arn
  delivery_policy = jsonencode({
    http = {
      defaultHealthyRetryPolicy = {
        minDelayTarget     = 20
        maxDelayTarget     = 20
        numRetries         = 3
        numMaxDelayRetries = 0
        numNoDelayRetries  = 0
        numMinDelayRetries = 0
        backoffFunction    = "linear"
      }
      disableSubscriptionOverrides = false
      defaultThrottlePolicy = {
        maxReceivesPerSecond = 10
      }
    }
  })
}

