locals {
  name_prefix = "benchmark-backup"
  account_id  = data.aws_caller_identity.current.account_id
  partition   = data.aws_partition.current.partition
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowAWSBackupKeyAccess"
    effect = "Allow"
    actions = [
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:CreateGrant",
      "kms:ListGrants",
      "kms:RevokeGrant"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "backup_key" {
  description             = "KMS CMK for AWS Backup vault encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = {
    Name = "${local.name_prefix}-kms-key"
  }
}

resource "aws_kms_alias" "backup_key_alias" {
  name          = "alias/backup-vault-key"
  target_key_id = aws_kms_key.backup_key.key_id
}

resource "aws_backup_vault" "backup_vault" {
  name        = "${local.name_prefix}-vault"
  kms_key_arn = aws_kms_key.backup_key.arn

  tags = {
    Name = "${local.name_prefix}-vault"
  }
}

resource "aws_backup_vault_lock_configuration" "vault_lock" {
  backup_vault_name   = aws_backup_vault.backup_vault.name
  min_retention_days  = 7
  max_retention_days  = 90
  changeable_for_days = 3
}

data "aws_iam_policy_document" "backup_role_assume" {
  statement {
    sid     = "AssumeRoleForAWSBackup"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup_role" {
  name               = "${local.name_prefix}-role"
  assume_role_policy = data.aws_iam_policy_document.backup_role_assume.json

  tags = {
    Name = "${local.name_prefix}-role"
  }
}

resource "aws_iam_role_policy_attachment" "backup_service_role_policy" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restore_service_role_policy" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

resource "aws_backup_plan" "backup_plan" {
  name = "${local.name_prefix}-plan"

  rule {
    rule_name         = "daily-backup-rule"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = "cron(0 5 ? * * *)"
    start_window      = 60
    completion_window = 180

    lifecycle {
      delete_after = 30
    }
  }

  tags = {
    Name = "${local.name_prefix}-plan"
  }
}

resource "aws_backup_selection" "backup_selection" {
  name         = "${local.name_prefix}-selection"
  iam_role_arn = aws_iam_role.backup_role.arn
  plan_id      = aws_backup_plan.backup_plan.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "benchmark-backup"
    value = "true"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

locals {
  name_prefix = "app-auth"
}

# 1. Cognito User Pool
resource "aws_cognito_user_pool" "pool" {
  name = "${locals.name_prefix}-user-pool"

  password_policy {
    minimum_length                   = 12
    require_lowercase                = true
    require_numbers                  = true
    require_symbols                  = true
    require_uppercase                = true
    temporary_password_validity_days = 7
  }

  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  auto_verified_attributes = ["email"]

  mfa_configuration = "OPTIONAL"

  software_token_mfa_configuration {
    enabled = true
  }
}

# 2. Cognito User Pool Client
resource "aws_cognito_user_pool_client" "client" {
  name         = "${locals.name_prefix}-client"
  user_pool_id = aws_cognito_user_pool.pool.id

  generate_secret                      = false
  prevent_user_existence_errors        = "ENABLED"
  explicit_auth_flows                  = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH"
  ]
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid", "profile"]
  callback_urls                        = ["https://localhost/callback"]
  logout_urls                          = ["https://localhost/logout"]
  supported_identity_providers         = ["COGNITO"]
}

# 3. Cognito Identity Pool
resource "aws_cognito_identity_pool" "identity_pool" {
  identity_pool_name               = "${locals.name_prefix}-identity-pool"
  allow_unauthenticated_identities = false

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.client.id
    provider_name           = aws_cognito_user_pool.pool.endpoint
    server_side_token_check = false
  }
}

# 4. IAM Assume Role Policy Document for Authenticated Identities
data "aws_iam_policy_document" "authenticated_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.identity_pool.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

# 5. IAM Role for Authenticated Identities
resource "aws_iam_role" "authenticated" {
  name               = "${locals.name_prefix}-cognito-authenticated-role"
  assume_role_policy = data.aws_iam_policy_document.authenticated_assume_role.json
}

# 6. IAM Policy Document for Cognito Sync and Mobile Analytics
data "aws_iam_policy_document" "authenticated_permissions" {
  statement {
    effect = "Allow"
    actions = [
      "cognito-sync:*"
    ]
    resources = [
      "arn:aws:cognito-sync:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:identitypool/${aws_cognito_identity_pool.identity_pool.id}/identity/*"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "mobileanalytics:PutEvents"
    ]
    resources = [
      "*"
    ]
  }
}

# 7. IAM Policy Resource
resource "aws_iam_policy" "authenticated_permissions" {
  name        = "${locals.name_prefix}-cognito-authenticated-policy"
  description = "Permissions for authenticated Cognito users to access Cognito Sync and Mobile Analytics"
  policy      = data.aws_iam_policy_document.authenticated_permissions.json
}

# 8. IAM Role Policy Attachment
resource "aws_iam_role_policy_attachment" "authenticated_attach" {
  role       = aws_iam_role.authenticated.name
  policy_arn = aws_iam_policy.authenticated_permissions.arn
}

# 9. Attach Authenticated Role to Identity Pool
resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.identity_pool.id

  roles = {
    "authenticated" = aws_iam_role.authenticated.arn
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr = "10.0.0.0/16"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "test-vpc"
  }
}

resource "aws_subnet" "primary" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "test-subnet-10.0.1.0"
  }
}

resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "test-igw"
  }
}

resource "aws_eip" "standalone" {
  domain = "vpc"

  tags = {
    Name = "test-eip"
  }
}

resource "aws_vpc_dhcp_options" "custom" {
  domain_name_servers = ["8.8.8.8", "8.8.4.4"]

  tags = {
    Name = "test-dhcp-options"
  }
}

resource "aws_vpc_dhcp_options_association" "custom" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.custom.id
}

resource "aws_default_security_group" "default" {
  default_security_group_id = aws_vpc.main.default_security_group_id

  ingress {
    description = "Allow SSH from within VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  ingress {
    description = "Allow HTTP from within VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  ingress {
    description = "Allow HTTPS from within VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Restrict egress to within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "test-default-sg"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  topic_name = "event-topic"
  api_name   = "event-api"
}

# -----------------------------------------------------------------------------
# KMS Customer Managed Key for SNS
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowSNSAndAPIGatewayServiceAccess"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]

    principals {
      type = "Service"
      identifiers = [
        "sns.amazonaws.com",
        "apigateway.amazonaws.com"
      ]
    }
  }
}

resource "aws_kms_key" "sns_key" {
  description             = "Dedicated KMS key for SNS topic encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = {
    Name = "event-topic-kms-key"
  }
}

resource "aws_kms_alias" "sns_key_alias" {
  name          = "alias/event-topic-key"
  target_key_id = aws_kms_key.sns_key.key_id
}

# -----------------------------------------------------------------------------
# SNS Topic
# -----------------------------------------------------------------------------
resource "aws_sns_topic" "event_topic" {
  name              = local.topic_name
  kms_master_key_id = aws_kms_key.sns_key.arn

  tags = {
    Name = local.topic_name
  }
}

# -----------------------------------------------------------------------------
# IAM Role and Policy for API Gateway
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "apigateway_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "apigateway_sns_role" {
  name               = "apigateway-sns-publish-role"
  assume_role_policy = data.aws_iam_policy_document.apigateway_assume_role.json
}

data "aws_iam_policy_document" "apigateway_sns_publish" {
  statement {
    sid       = "AllowPublishToSNSTopic"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.event_topic.arn]
  }

  statement {
    sid    = "AllowKMSKeyUsage"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt"
    ]
    resources = [aws_kms_key.sns_key.arn]
  }
}

resource "aws_iam_policy" "apigateway_sns_policy" {
  name        = "apigateway-sns-publish-policy"
  description = "Allows API Gateway to publish events to SNS and encrypt them using the KMS key"
  policy      = data.aws_iam_policy_document.apigateway_sns_publish.json
}

resource "aws_iam_role_policy_attachment" "apigateway_sns_attachment" {
  role       = aws_iam_role.apigateway_sns_role.name
  policy_arn = aws_iam_policy.apigateway_sns_policy.arn
}

# -----------------------------------------------------------------------------
# API Gateway REST API
# -----------------------------------------------------------------------------
resource "aws_api_gateway_rest_api" "event_api" {
  name        = local.api_name
  description = "REST API to ingest events and publish directly to SNS"

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

resource "aws_api_gateway_resource" "events_resource" {
  rest_api_id = aws_api_gateway_rest_api.event_api.id
  parent_id   = aws_api_gateway_rest_api.event_api.root_resource_id
  path_part   = "events"
}

resource "aws_api_gateway_method" "post_event" {
  rest_api_id      = aws_api_gateway_rest_api.event_api.id
  resource_id      = aws_api_gateway_resource.events_resource.id
  http_method      = "POST"
  authorization    = "NONE"
  api_key_required = false
}

resource "aws_api_gateway_integration" "sns_integration" {
  rest_api_id             = aws_api_gateway_rest_api.event_api.id
  resource_id             = aws_api_gateway_resource.events_resource.id
  http_method             = aws_api_gateway_method.post_event.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:aws:apigateway:${data.aws_region.current.name}:sns:action/Publish"
  credentials             = aws_iam_role.apigateway_sns_role.arn

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }

  request_templates = {
    "application/json" = "Action=Publish&TopicArn=$util.urlEncode('${aws_sns_topic.event_topic.arn}')&Message=$util.urlEncode($input.body)"
  }

  passthrough_behavior = "NEVER"
}

resource "aws_api_gateway_method_response" "response_200" {
  rest_api_id = aws_api_gateway_rest_api.event_api.id
  resource_id = aws_api_gateway_resource.events_resource.id
  http_method = aws_api_gateway_method.post_event.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "integration_response_200" {
  rest_api_id = aws_api_gateway_rest_api.event_api.id
  resource_id = aws_api_gateway_resource.events_resource.id
  http_method = aws_api_gateway_method.post_event.http_method
  status_code = aws_api_gateway_method_response.response_200.status_code

  response_templates = {
    "application/json" = "{\"message\": \"Event published successfully\"}"
  }

  depends_on = [
    aws_api_gateway_integration.sns_integration
  ]
}

resource "aws_api_gateway_deployment" "event_deployment" {
  rest_api_id = aws_api_gateway_rest_api.event_api.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.events_resource.id,
      aws_api_gateway_method.post_event.id,
      aws_api_gateway_integration.sns_integration.id,
      aws_api_gateway_method_response.response_200.id,
      aws_api_gateway_integration_response.integration_response_200.id,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_integration_response.integration_response_200
  ]
}

resource "aws_api_gateway_stage" "prod" {
  deployment_id = aws_api_gateway_deployment.event_deployment.id
  rest_api_id   = aws_api_gateway_rest_api.event_api.id
  stage_name    = "prod"
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "The AWS region where resources will be provisioned."
  default     = "us-east-1"
}

variable "vpc_cidr_block" {
  type        = string
  description = "CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr_blocks" {
  type        = list(string)
  description = "CIDR blocks for the public subnets."
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidr_blocks" {
  type        = list(string)
  description = "CIDR blocks for the private subnets."
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "terraform-aws-vpc"
  }
}

resource "aws_subnet" "public_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr_blocks[0]
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "public-subnet-1"
  }
}

resource "aws_subnet" "public_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr_blocks[1]
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "public-subnet-2"
  }
}

resource "aws_subnet" "private_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr_blocks[0]
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "private-subnet-1"
  }
}

resource "aws_subnet" "private_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr_blocks[1]
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "private-subnet-2"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_name = "ntier primary"
}

resource "aws_vpc" "ntier_primary" {
  cidr_block           = "10.10.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = local.vpc_name
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.ntier_primary.id

  tags = {
    Name = "${local.vpc_name}-igw"
  }
}

# Web Tier
resource "aws_subnet" "web_1" {
  vpc_id                  = aws_vpc.ntier_primary.id
  cidr_block              = "10.10.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "${local.vpc_name}-web-1"
    Tier = "web"
  }
}

resource "aws_subnet" "web_2" {
  vpc_id                  = aws_vpc.ntier_primary.id
  cidr_block              = "10.10.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name = "${local.vpc_name}-web-2"
    Tier = "web"
  }
}

# Management Tier
resource "aws_subnet" "mgmt" {
  vpc_id                  = aws_vpc.ntier_primary.id
  cidr_block              = "10.10.10.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "${local.vpc_name}-mgmt"
    Tier = "management"
  }
}

# Application Tier
resource "aws_subnet" "app_1" {
  vpc_id            = aws_vpc.ntier_primary.id
  cidr_block        = "10.10.11.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "${local.vpc_name}-app-1"
    Tier = "app"
  }
}

resource "aws_subnet" "app_2" {
  vpc_id            = aws_vpc.ntier_primary.id
  cidr_block        = "10.10.12.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "${local.vpc_name}-app-2"
    Tier = "app"
  }
}

# Database Tier
resource "aws_subnet" "db_1" {
  vpc_id            = aws_vpc.ntier_primary.id
  cidr_block        = "10.10.21.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "${local.vpc_name}-db-1"
    Tier = "database"
  }
}

resource "aws_subnet" "db_2" {
  vpc_id            = aws_vpc.ntier_primary.id
  cidr_block        = "10.10.22.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "${local.vpc_name}-db-2"
    Tier = "database"
  }
}

# Route Tables
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.ntier_primary.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${local.vpc_name}-public-rt"
  }
