resource "aws_route_table" "private" {
  vpc_id = aws_vpc.ntier_primary.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${local.vpc_name}-private-rt"
  }
}

# Public Route Table Associations
resource "aws_route_table_association" "web_1" {
  subnet_id      = aws_subnet.web_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "web_2" {
  subnet_id      = aws_subnet.web_2.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "mgmt" {
  subnet_id      = aws_subnet.mgmt.id
  route_table_id = aws_route_table.public.id
}

# Private Route Table Associations
resource "aws_route_table_association" "app_1" {
  subnet_id      = aws_subnet.app_1.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "app_2" {
  subnet_id      = aws_subnet.app_2.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "db_1" {
  subnet_id      = aws_subnet.db_1.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "db_2" {
  subnet_id      = aws_subnet.db_2.id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "create_key" {
  description = "Controls if KMS resources should be created"
  type        = bool
  default     = true
}

variable "key_mode" {
  description = "Mode of KMS key creation: 'standard', 'external', 'replica', 'replica_external'"
  type        = string
  default     = "standard"
  validation {
    condition     = contains(["standard", "external", "replica", "replica_external"], var.key_mode)
    error_message = "key_mode must be one of: standard, external, replica, replica_external."
  }
}

variable "description" {
  description = "The description of the key as viewed in AWS console"
  type        = string
  default     = "Managed KMS Key"
}

variable "key_usage" {
  description = "Specifies the intended use of the key: ENCRYPT_DECRYPT, SIGN_VERIFY, or GENERATE_VERIFY_MAC"
  type        = string
  default     = "ENCRYPT_DECRYPT"
}

variable "customer_master_key_spec" {
  description = "Specifies whether the key contains a symmetric key or an asymmetric key pair and encryption algorithms supported"
  type        = string
  default     = "SYMMETRIC_DEFAULT"
}

variable "deletion_window_in_days" {
  description = "The waiting period, specified in number of days. After the waiting period ends, AWS KMS deletes the KMS key."
  type        = number
  default     = 30
}

variable "enable_key_rotation" {
  description = "Specifies whether key rotation is enabled. Defaults to true."
  type        = bool
  default     = true
}

variable "multi_region" {
  description = "Indicates whether the KMS key is a multi-Region (true) or regional (false) key."
  type        = bool
  default     = false
}

variable "key_material_base64" {
  description = "The base64-encoded 256-bit symmetric key material to import. Required if key_mode is external or replica_external."
  type        = string
  default     = null
  sensitive   = true
}

variable "valid_to" {
  description = "Time at which the imported key material expires in RFC3339 format (e.g. 2025-01-01T00:00:00Z)"
  type        = string
  default     = null
}

variable "primary_key_arn" {
  description = "The ARN of the primary key when key_mode is replica or replica_external"
  type        = string
  default     = null
}

variable "enable_default_policy" {
  description = "Specifies whether to enable the default root account full access policy statement"
  type        = bool
  default     = true
}

variable "key_owners" {
  description = "A list of IAM ARNs for key administration and ownership"
  type        = list(string)
  default     = []
}

variable "key_administrators" {
  description = "A list of IAM ARNs for key administrators"
  type        = list(string)
  default     = []
}

variable "key_users" {
  description = "A list of IAM ARNs for standard cryptographic key users"
  type        = list(string)
  default     = []
}

variable "key_service_users" {
  description = "A list of IAM ARNs for service principals/users requiring key usage"
  type        = list(string)
  default     = []
}

variable "key_asg_roles" {
  description = "A list of IAM service-linked role ARNs for EC2 Auto Scaling (AWSServiceRoleForAutoScaling)"
  type        = list(string)
  default     = []
}

variable "enable_route53_dnssec" {
  description = "Whether to allow Route 53 DNSSEC signing service permissions"
  type        = bool
  default     = false
}

variable "key_symmetric_encryption_users" {
  description = "A list of IAM ARNs for symmetric encryption operations (Encrypt, Decrypt, ReEncrypt*, GenerateDataKey*)"
  type        = list(string)
  default     = []
}

variable "key_hmac_users" {
  description = "A list of IAM ARNs for HMAC operations (GenerateMac, VerifyMac)"
  type        = list(string)
  default     = []
}

variable "key_asymmetric_public_encryption_users" {
  description = "A list of IAM ARNs for asymmetric public encryption operations (Encrypt, Decrypt, ReEncrypt*)"
  type        = list(string)
  default     = []
}

variable "key_asymmetric_sign_verify_users" {
  description = "A list of IAM ARNs for asymmetric sign/verify operations (Sign, Verify, GetPublicKey)"
  type        = list(string)
  default     = []
}

variable "custom_policy_statements" {
  description = "A list of custom IAM policy statements to append to the KMS key policy"
  type        = any
  default     = []
}

variable "override_policy_documents" {
  description = "List of IAM policy documents that merge into and override the generated key policy"
  type        = list(string)
  default     = []
}

variable "aliases" {
  description = "Map of KMS aliases to create. Key is alias suffix or identifier, value contains name or name_prefix."
  type = map(object({
    name        = optional(string)
    name_prefix = optional(string)
  }))
  default = {}
}

variable "grants" {
  description = "Map of KMS grants to create"
  type = map(object({
    grantee_principal = string
    operations        = list(string)
    retiring_principal = optional(string)
    name              = optional(string)
    constraints = optional(object({
      encryption_context_equals = optional(map(string))
      encryption_context_subset = optional(map(string))
    }))
  }))
  default = {}
}

variable "tags" {
  description = "A map of tags to assign to the key"
  type        = map(string)
  default     = {}
}

# -----------------------------------------------------------------------------
# Dynamic Policy Construction
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "this" {
  count = var.create_key ? 1 : 0

  override_policy_documents = var.override_policy_documents

  dynamic "statement" {
    for_each = var.enable_default_policy ? [1] : []
    content {
      sid       = "DefaultRootAccountAccess"
      effect    = "Allow"
      actions   = ["kms:*"]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_owners) > 0 ? [1] : []
    content {
      sid       = "KeyOwners"
      effect    = "Allow"
      actions   = ["kms:*"]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.key_owners
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_administrators) > 0 ? [1] : []
    content {
      sid    = "KeyAdministration"
      effect = "Allow"
      actions = [
        "kms:Create*",
        "kms:Describe*",
        "kms:Enable*",
        "kms:List*",
        "kms:Put*",
        "kms:Update*",
        "kms:Revoke*",
        "kms:Disable*",
        "kms:Get*",
        "kms:Delete*",
        "kms:TagResource",
        "kms:UntagResource",
        "kms:ScheduleKeyDeletion",
        "kms:CancelKeyDeletion",
        "kms:RotateKeyOnDemand"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.key_administrators
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_users) > 0 ? [1] : []
    content {
      sid    = "KeyUsage"
      effect = "Allow"
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*",
        "kms:DescribeKey"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.key_users
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_service_users) > 0 ? [1] : []
    content {
      sid    = "KeyServiceUsage"
      effect = "Allow"
      actions = [
        "kms:CreateGrant",
        "kms:ListGrants",
        "kms:RevokeGrant",
        "kms:DescribeKey",
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.key_service_users
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_asg_roles) > 0 ? [1] : []
    content {
      sid    = "AutoScalingRoleUsage"
      effect = "Allow"
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*",
        "kms:DescribeKey"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.key_asg_roles
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_asg_roles) > 0 ? [1] : []
    content {
      sid    = "AutoScalingGrantDelegation"
      effect = "Allow"
      actions = [
        "kms:CreateGrant"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.key_asg_roles
      }
      condition {
        test     = "Bool"
        variable = "kms:GrantIsForAWSResource"
        values   = ["true"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.enable_route53_dnssec ? [1] : []
    content {
      sid    = "Route53DNSSECAccess"
      effect = "Allow"
      actions = [
        "kms:DescribeKey",
        "kms:GetPublicKey",
        "kms:Sign"
      ]
      resources = ["*"]
      principals {
        type        = "Service"
        identifiers = ["dnssec-route53.amazonaws.com"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.enable_route53_dnssec ? [1] : []
    content {
      sid    = "Route53DNSSECCreateGrant"
      effect = "Allow"
      actions = [
        "kms:CreateGrant"
      ]
      resources = ["*"]
      principals {
        type        = "Service"
        identifiers = ["dnssec-route53.amazonaws.com"]
      }
      condition {
        test     = "Bool"
        variable = "kms:GrantIsForAWSResource"
        values   = ["true"]
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_symmetric_encryption_users) > 0 ? [1] : []
    content {
      sid    = "SymmetricEncryptionUsers"
      effect = "Allow"
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*",
        "kms:DescribeKey"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.key_symmetric_encryption_users
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_hmac_users) > 0 ? [1] : []
    content {
      sid    = "HMACUsers"
      effect = "Allow"
      actions = [
        "kms:GenerateMac",
        "kms:VerifyMac",
        "kms:DescribeKey"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.key_hmac_users
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_asymmetric_public_encryption_users) > 0 ? [1] : []
    content {
      sid    = "AsymmetricPublicEncryptionUsers"
      effect = "Allow"
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:DescribeKey",
        "kms:GetPublicKey"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.key_asymmetric_public_encryption_users
      }
    }
  }

  dynamic "statement" {
    for_each = length(var.key_asymmetric_sign_verify_users) > 0 ? [1] : []
    content {
      sid    = "AsymmetricSignVerifyUsers"
      effect = "Allow"
      actions = [
        "kms:Sign",
        "kms:Verify",
        "kms:DescribeKey",
        "kms:GetPublicKey"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.key_asymmetric_sign_verify_users
      }
    }
  }

  dynamic "statement" {
    for_each = var.custom_policy_statements
    content {
      sid           = try(statement.value.sid, null)
      effect        = try(statement.value.effect, "Allow")
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      resources     = try(statement.value.resources, ["*"])
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])
        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

# -----------------------------------------------------------------------------
# KMS Resources
# -----------------------------------------------------------------------------

# Mode: standard
resource "aws_kms_key" "this" {
  count                    = var.create_key && var.key_mode == "standard" ? 1 : 0
  description              = var.description
  key_usage                = var.key_usage
  customer_master_key_spec = var.customer_master_key_spec
  policy                   = data.aws_iam_policy_document.this[0].json
  deletion_window_in_days  = var.deletion_window_in_days
  enable_key_rotation      = var.customer_master_key_spec == "SYMMETRIC_DEFAULT" ? var.enable_key_rotation : false
  multi_region             = var.multi_region
  tags                     = var.tags
}

# Mode: external
resource "aws_kms_external_key" "this" {
  count                   = var.create_key && var.key_mode == "external" ? 1 : 0
  description             = var.description
  key_material_base64     = var.key_material_base64
  valid_to                = var.valid_to
  policy                  = data.aws_iam_policy_document.this[0].json
  deletion_window_in_days = var.deletion_window_in_days
  multi_region            = var.multi_region
  tags                    = var.tags
}

# Mode: replica
resource "aws_kms_replica_key" "this" {
  count                   = var.create_key && var.key_mode == "replica" ? 1 : 0
  description             = var.description
  primary_key_arn         = var.primary_key_arn
  policy                  = data.aws_iam_policy_document.this[0].json
  deletion_window_in_days = var.deletion_window_in_days
  tags                    = var.tags
}

# Mode: replica_external
resource "aws_kms_replica_external_key" "this" {
  count                   = var.create_key && var.key_mode == "replica_external" ? 1 : 0
  description             = var.description
  primary_key_arn         = var.primary_key_arn
  key_material_base64     = var.key_material_base64
  valid_to                = var.valid_to
  policy                  = data.aws_iam_policy_document.this[0].json
  deletion_window_in_days = var.deletion_window_in_days
  tags                    = var.tags
}

# -----------------------------------------------------------------------------
# Locals: Target Resolution
# -----------------------------------------------------------------------------

locals {
  key_id = try(
    aws_kms_key.this[0].id,
    aws_kms_external_key.this[0].id,
    aws_kms_replica_key.this[0].id,
    aws_kms_replica_external_key.this[0].id,
    null
  )

  key_arn = try(
    aws_kms_key.this[0].arn,
    aws_kms_external_key.this[0].arn,
    aws_kms_replica_key.this[0].arn,
    aws_kms_replica_external_key.this[0].arn,
    null
  )
}

# -----------------------------------------------------------------------------
# Aliases
# -----------------------------------------------------------------------------

resource "aws_kms_alias" "this" {
  for_each = var.create_key ? var.aliases : {}

  name          = each.value.name != null ? (startswith(each.value.name, "alias/") ? each.value.name : "alias/${each.value.name}") : null
  name_prefix   = each.value.name_prefix != null ? (startswith(each.value.name_prefix, "alias/") ? each.value.name_prefix : "alias/${each.value.name_prefix}") : null
  target_key_id = local.key_id
}

# -----------------------------------------------------------------------------
# Grants
# -----------------------------------------------------------------------------

resource "aws_kms_grant" "this" {
  for_each = var.create_key ? var.grants : {}

  name               = try(each.value.name, each.key)
  key_id             = local.key_id
  grantee_principal  = each.value.grantee_principal
  operations         = each.value.operations
  retiring_principal = try(each.value.retiring_principal, null)

  dynamic "constraints" {
    for_each = each.value.constraints != null ? [each.value.constraints] : []
    content {
      encryption_context_equals = try(constraints.value.encryption_context_equals, null)
      encryption_context_subset = try(constraints.value.encryption_context_subset, null)
    }
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "key_arn" {
  description = "The Amazon Resource Name (ARN) of the KMS key"
  value       = local.key_arn
}

output "key_id" {
  description = "The globally unique identifier for the KMS key"
  value       = local.key_id
}

output "key_policy" {
  description = "The IAM resource policy applied to the KMS key"
  value       = try(data.aws_iam_policy_document.this[0].json, null)
}

output "aliases" {
  description = "A map of all KMS aliases created and their attributes"
  value = {
    for k, v in aws_kms_alias.this : k => {
      arn           = v.arn
      name          = v.name
      target_key_id = v.target_key_id
    }
  }
}

output "grants" {
  description = "A map of all KMS grants created and their IDs"
  value = {
    for k, v in aws_kms_grant.this : k => {
      id        = v.grant_id
      grant_token = v.grant_token
    }
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "topic_name" {
  type        = string
  description = "The name of the SNS topic to create."
  default     = "app-notifications"
}

variable "fifo_topic" {
  type        = bool
  description = "Boolean indicating whether or not to create a FIFO (first-in-first-out) topic."
  default     = false
}

variable "content_based_deduplication" {
  type        = bool
  description = "Enables content-based deduplication for FIFO topics."
  default     = false
}

variable "create_kms_key" {
  type        = bool
  description = "Whether to create a dedicated customer managed KMS key for the SNS topic and CloudWatch logs."
  default     = true
}

variable "kms_master_key_id" {
  type        = string
  description = "The ID or ARN of an existing KMS key to encrypt the SNS topic with. Overridden if create_kms_key is true."
  default     = null
}

variable "custom_topic_policy_json" {
  type        = string
  description = "Custom JSON policy document to attach to the SNS topic. If null, no separate topic policy resource is created."
  default     = null
}

# Delivery Status Logging: Application
variable "application_success_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for Application delivery success feedback logging."
  default     = null
}

variable "application_success_feedback_sample_rate" {
  type        = number
  description = "Sample rate percentage (0-100) for Application delivery success feedback."
  default     = null
}

variable "application_failure_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for Application delivery failure feedback logging."
  default     = null
}

# Delivery Status Logging: HTTP/S
variable "http_success_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for HTTP/S delivery success feedback logging."
  default     = null
}

variable "http_success_feedback_sample_rate" {
  type        = number
  description = "Sample rate percentage (0-100) for HTTP/S delivery success feedback."
  default     = null
}

variable "http_failure_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for HTTP/S delivery failure feedback logging."
  default     = null
}

# Delivery Status Logging: Lambda
variable "lambda_success_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for Lambda delivery success feedback logging."
  default     = null
}

variable "lambda_success_feedback_sample_rate" {
  type        = number
  description = "Sample rate percentage (0-100) for Lambda delivery success feedback."
  default     = null
}

variable "lambda_failure_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for Lambda delivery failure feedback logging."
  default     = null
}

# Delivery Status Logging: SQS
variable "sqs_success_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for SQS delivery success feedback logging."
  default     = null
}

variable "sqs_success_feedback_sample_rate" {
  type        = number
  description = "Sample rate percentage (0-100) for SQS delivery success feedback."
  default     = null
}

variable "sqs_failure_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for SQS delivery failure feedback logging."
  default     = null
}

# Delivery Status Logging: Firehose
variable "firehose_success_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for Firehose delivery success feedback logging."
  default     = null
}

variable "firehose_success_feedback_sample_rate" {
  type        = number
  description = "Sample rate percentage (0-100) for Firehose delivery success feedback."
  default     = null
}

variable "firehose_failure_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for Firehose delivery failure feedback logging."
  default     = null
}

variable "subscriptions" {
  type = map(object({
    protocol               = string
    endpoint               = string
    endpoint_auto_confirms = optional(bool, false)
    raw_message_delivery   = optional(bool, false)
    filter_policy          = optional(string, null)
    filter_policy_scope    = optional(string, null)
    redrive_policy         = optional(string, null)
  }))
  description = "Map of subscription configurations to attach to the SNS topic."
  default     = {}
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  actual_topic_name = var.fifo_topic && !endswith(var.topic_name, ".fifo") ? "${var.topic_name}.fifo" : var.topic_name
  alias_name_suffix = replace(local.actual_topic_name, ".fifo", "")

  resolved_kms_key_id = var.create_kms_key ? aws_kms_key.sns[0].arn : (
    var.kms_master_key_id != null ? var.kms_master_key_id : "alias/aws/sns"
  )
}

# -----------------------------------------------------------------------------
# KMS Resources
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "kms_sns_policy" {
  count = var.create_kms_key ? 1 : 0

  statement {
    sid    = "EnableRootPermissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsEncryption"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*"
    ]
    resources = ["*"]
    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:*"]
    }
  }

  statement {
    sid    = "AllowSNSServiceEncryption"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt*"
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "sns" {
  count                   = var.create_kms_key ? 1 : 0
  description             = "KMS key for SNS topic ${local.actual_topic_name} and CloudWatch delivery feedback"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_sns_policy[0].json
}

resource "aws_kms_alias" "sns" {
  count         = var.create_kms_key ? 1 : 0
  name          = "alias/sns/${local.alias_name_suffix}"
  target_key_id = aws_kms_key.sns[0].key_id
}

# -----------------------------------------------------------------------------
# SNS Topic
# -----------------------------------------------------------------------------

resource "aws_sns_topic" "main" {
  name                        = local.actual_topic_name
  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.fifo_topic ? var.content_based_deduplication : false
  kms_master_key_id           = local.resolved_kms_key_id

  # Application Delivery Feedback
  application_success_feedback_role_arn    = var.application_success_feedback_role_arn
  application_success_feedback_sample_rate = var.application_success_feedback_sample_rate
  application_failure_feedback_role_arn    = var.application_failure_feedback_role_arn

  # HTTP/S Delivery Feedback
  http_success_feedback_role_arn    = var.http_success_feedback_role_arn
  http_success_feedback_sample_rate = var.http_success_feedback_sample_rate
  http_failure_feedback_role_arn    = var.http_failure_feedback_role_arn

  # Lambda Delivery Feedback
  lambda_success_feedback_role_arn    = var.lambda_success_feedback_role_arn
  lambda_success_feedback_sample_rate = var.lambda_success_feedback_sample_rate
  lambda_failure_feedback_role_arn    = var.lambda_failure_feedback_role_arn

  # SQS Delivery Feedback
  sqs_success_feedback_role_arn    = var.sqs_success_feedback_role_arn
  sqs_success_feedback_sample_rate = var.sqs_success_feedback_sample_rate
  sqs_failure_feedback_role_arn    = var.sqs_failure_feedback_role_arn

  # Firehose Delivery Feedback
  firehose_success_feedback_role_arn    = var.firehose_success_feedback_role_arn
  firehose_success_feedback_sample_rate = var.firehose_success_feedback_sample_rate
  firehose_failure_feedback_role_arn    = var.firehose_failure_feedback_role_arn
}

# -----------------------------------------------------------------------------
# SNS Topic Policy (Optional)
# -----------------------------------------------------------------------------

resource "aws_sns_topic_policy" "custom" {
  count  = var.custom_topic_policy_json != null ? 1 : 0
  arn    = aws_sns_topic.main.arn
  policy = var.custom_topic_policy_json
}

# -----------------------------------------------------------------------------
# SNS Subscriptions
# -----------------------------------------------------------------------------

resource "aws_sns_topic_subscription" "subscriptions" {
  for_each               = var.subscriptions
  topic_arn              = aws_sns_topic.main.arn
  protocol               = each.value.protocol
  endpoint               = each.value.endpoint
  endpoint_auto_confirms = each.value.endpoint_auto_confirms
  raw_message_delivery   = each.value.raw_message_delivery
  filter_policy          = each.value.filter_policy
  filter_policy_scope    = each.value.filter_policy_scope
  redrive_policy         = each.value.redrive_policy
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "topic_arn" {
  description = "ARN of the provisioned SNS topic."
  value       = aws_sns_topic.main.arn
}

output "topic_id" {
  description = "ID of the provisioned SNS topic."
  value       = aws_sns_topic.main.id
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for encrypting the SNS topic."
  value       = local.resolved_kms_key_id
}

output "subscription_arns" {
  description = "Map of keys to subscription ARNs created for the SNS topic."
  value       = { for k, v in aws_sns_topic_subscription.subscriptions : k => v.arn }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------

variable "create_developer_group" {
  type        = bool
  description = "Controls whether the developer IAM group should be created."
  default     = true
}

variable "create_iam_s3_policy" {
  type        = bool
  description = "Controls whether the IAM read-only and S3 read/write policy should be created."
  default     = true
}

variable "attach_iam_s3_policy_to_group" {
  type        = bool
  description = "Controls whether the IAM read-only and S3 read/write policy is attached to the developer group."
  default     = true
}

variable "create_iam_users" {
  type        = bool
  description = "Controls whether IAM users are created."
  default     = true
}

variable "create_ec2_screenshot_policy" {
  type        = bool
  description = "Controls whether the EC2 console screenshot policy should be created."
  default     = true
}

variable "attach_screenshot_policy_to_users" {
  type        = bool
  description = "Controls whether the EC2 console screenshot policy is attached to created IAM users."
  default     = true
}

variable "add_users_to_group" {
  type        = bool
  description = "Controls whether created IAM users are assigned to the developer group."
  default     = true
}

variable "create_instance_role" {
  type        = bool
  description = "Controls whether the EC2 instance role is created."
  default     = true
}

variable "developer_group_name" {
  type        = string
  description = "Name of the developer IAM group."
  default     = "developers"
}

variable "iam_user_names" {
  type        = list(string)
  description = "List of IAM usernames to create."
  default     = ["jack", "jones"]
}

variable "custom_tags" {
  type        = map(string)
  description = "Custom tags to apply to resources."
  default     = {}
}

# -----------------------------------------------------------------------------
# Local Values
# -----------------------------------------------------------------------------

locals {
  common_tags = merge(
    {
      Environment = "development"
      ManagedBy   = "terraform"
    },
    var.custom_tags
  )
  user_tags = merge(
    local.common_tags,
    {
      user_created_by = "terraform"
    }
  )
  users_to_create = var.create_iam_users ? toset(var.iam_user_names) : toset([])
}

# -----------------------------------------------------------------------------
# IAM Group
# -----------------------------------------------------------------------------

resource "aws_iam_group" "developers" {
  count = var.create_developer_group ? 1 : 0
  name  = var.developer_group_name
  path  = "/"
}

# -----------------------------------------------------------------------------
# IAM Users
# -----------------------------------------------------------------------------

resource "aws_iam_user" "developers" {
  for_each      = local.users_to_create
  name          = each.value
  path          = "/"
  force_destroy = true
  tags          = local.user_tags
}

# -----------------------------------------------------------------------------
# IAM Policies
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "iam_read_only_and_s3_rw" {
  statement {
    sid    = "IAMReadOnlyActions"
    effect = "Allow"
    actions = [
      "iam:GenerateCredentialReport",
      "iam:GenerateServiceLastAccessedDetails",
      "iam:Get*",
      "iam:List*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "S3BucketListing"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation"
    ]
    resources = ["arn:aws:s3:::*"]
  }

  statement {
    sid    = "S3ObjectReadWrite"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectAcl",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:PutObjectAcl"
    ]
    resources = ["arn:aws:s3:::*/*"]
  }
}

resource "aws_iam_policy" "iam_read_only_and_s3_full_access" {
  count       = var.create_iam_s3_policy ? 1 : 0
  name        = "iam_read_only_and_s3_full_access"
  path        = "/"
  description = "Grants IAM read-only access and S3 read/write permissions"
  policy      = data.aws_iam_policy_document.iam_read_only_and_s3_rw.json
  tags        = local.common_tags
}

data "aws_iam_policy_document" "ec2_get_console_screenshot" {
  statement {
    sid    = "EC2ConsoleScreenshot"
    effect = "Allow"
    actions = [
      "ec2:GetConsoleScreenshot"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "ec2_get_console_screenshot" {
  count       = var.create_ec2_screenshot_policy ? 1 : 0
  name        = "ec2_get_console_screenshot"
  path        = "/"
  description = "Allows capturing EC2 console screenshots"
  policy      = data.aws_iam_policy_document.ec2_get_console_screenshot.json
  tags        = local.common_tags
}

# -----------------------------------------------------------------------------
# Policy Attachments & Group Memberships
# -----------------------------------------------------------------------------

resource "aws_iam_group_policy_attachment" "iam_s3_to_group" {
  count      = (var.create_developer_group && var.create_iam_s3_policy && var.attach_iam_s3_policy_to_group) ? 1 : 0
  group      = aws_iam_group.developers[0].name
  policy_arn = aws_iam_policy.iam_read_only_and_s3_full_access[0].arn
}

resource "aws_iam_user_policy_attachment" "screenshot_to_users" {
  for_each   = (var.create_iam_users && var.create_ec2_screenshot_policy && var.attach_screenshot_policy_to_users) ? aws_iam_user.developers : {}
  user       = each.value.name
  policy_arn = aws_iam_policy.ec2_get_console_screenshot[0].arn
}

resource "aws_iam_group_membership" "developers" {
  count = (var.create_developer_group && var.create_iam_users && var.add_users_to_group && length(local.users_to_create) > 0) ? 1 : 0
  name  = "${var.developer_group_name}-membership"
  group = aws_iam_group.developers[0].name
  users = [for u in aws_iam_user.developers : u.name]
}

# -----------------------------------------------------------------------------
# EC2 Instance Role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRoleTrust"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "instance_role" {
  count              = var.create_instance_role ? 1 : 0
  name               = "instance_role"
  path               = "/"
  description        = "EC2 instance role with read-only IAM access"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "instance_role_iam_read_only" {
  count      = var.create_instance_role ? 1 : 0
  role       = aws_iam_role.instance_role[0].name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "developer_group_arn" {
  description = "ARN of the developer IAM group"
  value       = try(aws_iam_group.developers[0].arn, null)
}

output "developer_group_name" {
  description = "Name of the developer IAM group"
  value       = try(aws_iam_group.developers[0].name, null)
}

output "iam_user_arns" {
  description = "ARNs of the created IAM users"
  value       = { for u in aws_iam_user.developers : u.name => u.arn }
}

output "iam_s3_policy_arn" {
  description = "ARN of the IAM read-only and S3 read/write policy"
  value       = try(aws_iam_policy.iam_read_only_and_s3_full_access[0].arn, null)
}

output "ec2_screenshot_policy_arn" {
  description = "ARN of the EC2 console screenshot policy"
  value       = try(aws_iam_policy.ec2_get_console_screenshot[0].arn, null)
}

output "instance_role_arn" {
  description = "ARN of the EC2 instance role"
  value       = try(aws_iam_role.instance_role[0].arn, null)
}

output "instance_role_name" {
  description = "Name of the EC2 instance role"
  value       = try(aws_iam_role.instance_role[0].name, null)
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name     = "eks-multi-cluster-vpc"
  vpc_cidr = "10.0.0.0/16"
  azs      = slice(data.aws_availability_zones.available.names, 0, 3)

  private_subnets = [
    cidrsubnet(local.vpc_cidr, 4, 0),
    cidrsubnet(local.vpc_cidr, 4, 1),
    cidrsubnet(local.vpc_cidr, 4, 2)
  ]

  public_subnets = [
    cidrsubnet(local.vpc_cidr, 8, 48),
    cidrsubnet(local.vpc_cidr, 8, 49),
    cidrsubnet(local.vpc_cidr, 8, 50)
  ]

  tags = {
    Blueprint  = local.name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = local.name
  cidr = local.vpc_cidr

  azs             = local.azs
  private_subnets = local.private_subnets
  public_subnets  = local.public_subnets

  enable_nat_gateway = true
  single_nat_gateway = true

  enable_dns_hostnames = true
  enable_dns_support   = true

  public_subnet_tags = {
    "kubernetes.io/role/elb" = "1"
  }

  private_subnet_tags = {
    "kubernetes.io/role/internal-elb" = "1"
  }

  tags = local.tags
}

resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "Cross-cluster communication security group for cluster1"
  vpc_id      = module.vpc.vpc_id

  tags = merge(
    local.tags,
    {
      Name = "cluster1_additional_sg"
    }
  )
}

resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "Cross-cluster communication security group for cluster2"
  vpc_id      = module.vpc.vpc_id

  tags = merge(
    local.tags,
    {
      Name = "cluster2_additional_sg"
    }
  )
}

resource "aws_security_group_rule" "cluster1_ingress_from_cluster2" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  security_group_id        = aws_security_group.cluster1_additional_sg.id
  source_security_group_id = aws_security_group.cluster2_additional_sg.id
  description              = "Allow all ingress traffic from cluster2 additional security group"
}

resource "aws_security_group_rule" "cluster1_egress_to_cluster2" {
  type                     = "egress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  security_group_id        = aws_security_group.cluster1_additional_sg.id
  source_security_group_id = aws_security_group.cluster2_additional_sg.id
  description              = "Allow all egress traffic to cluster2 additional security group"
}

resource "aws_security_group_rule" "cluster2_ingress_from_cluster1" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  security_group_id        = aws_security_group.cluster2_additional_sg.id
  source_security_group_id = aws_security_group.cluster1_additional_sg.id
  description              = "Allow all ingress traffic from cluster1 additional security group"
}

resource "aws_security_group_rule" "cluster2_egress_to_cluster1" {
  type                     = "egress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  security_group_id        = aws_security_group.cluster2_additional_sg.id
  source_security_group_id = aws_security_group.cluster1_additional_sg.id
  description              = "Allow all egress traffic to cluster1 additional security group"
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "pool_name" {
  description = "Name of the Cognito User Pool"
  type        = string
  default     = "Pool name"
}

variable "alias_attributes" {
  description = "Attributes supported as an alias for this user pool"
  type        = list(string)
  default     = ["email", "phone_number"]
}

variable "auto_verified_attributes" {
  description = "Attributes to be auto-verified"
  type        = list(string)
  default     = []
}

variable "email_verification_message" {
  description = "Email verification message template"
  type        = string
  default     = "Some message {####}"
}

variable "email_verification_subject" {
  description = "Email verification subject template"
  type        = string
  default     = "Some subject"
}

variable "mfa_configuration" {
  description = "Multi-Factor Authentication (MFA) configuration"
  type        = string
  default     = "OPTIONAL"
}

variable "sms_authentication_message" {
  description = "SMS authentication message template"
  type        = string
  default     = "SMS authentication message {####}"
}

variable "sms_verification_message" {
  description = "SMS verification message template"
  type        = string
  default     = "SMS verification message {####}"
}

variable "verification_message_template" {
  description = "Template for verification messages (e.g., link verification)"
  type = object({
    default_email_option  = optional(string)
    email_message_by_link = optional(string)
    email_subject_by_link = optional(string)
  })
  default = null
}

variable "sms_configuration" {
  description = "SMS configuration map containing external_id and sns_caller_arn"
  type = object({
    external_id    = string
    sns_caller_arn = string
  })
  default = {
    external_id    = ""
    sns_caller_arn = ""
  }
}

variable "recovery_mechanisms" {
  description = "List of recovery mechanisms for the user pool"
  type = list(object({
    name     = string
    priority = number
  }))
  default = [
    {
      name     = "verified_phone_number"
      priority = 1
    },
    {
      name     = "verified_email"
      priority = 2
    }
  ]
}

variable "admin_create_user_config" {
  description = "Configuration for admin user creation and invite message templates"
  type = object({
    allow_admin_create_user_only = optional(bool, false)
    email_message                = optional(string)
    email_subject                = optional(string)
    sms_message                  = optional(string)
    unused_account_validity_days = optional(number)
  })
  default = {
    allow_admin_create_user_only = false
  }
}

variable "enable_software_token_mfa" {
  description = "Flag to enable software token MFA"
  type        = bool
  default     = true
}

variable "case_sensitive" {
  description = "Specifies whether username is case sensitive"
  type        = bool
  default     = null
}

variable "device_configuration" {
  description = "Device tracking configuration"
  type = object({
    challenge_required_on_new_device      = optional(bool)
    device_only_remembered_on_user_prompt = optional(bool)
  })
  default = null
}

variable "lambda_triggers" {
  description = "Map of Lambda triggers to integrate with user pool events"
  type        = map(string)
  default     = {}
}

variable "custom_email_sender_lambda" {
  description = "Lambda trigger and KMS key ARN for custom email sender"
  type = object({
    lambda_arn     = string
    lambda_version = string
    kms_key_arn    = string
  })
  default = null
}

variable "schema_attributes" {
  description = "List of schema attributes for the user pool"
  type = list(object({
    name                     = string
    attribute_data_type      = string
    developer_only_attribute = optional(bool, false)
    mutable                  = optional(bool, true)
    required                 = optional(bool, true)
    min_value                = optional(string)
    max_value                = optional(string)
    min_length               = optional(string)
    max_length               = optional(string)
  }))
  default = [
    {
      name                = "email"
      attribute_data_type = "String"
      mutable             = true
      required            = true
    }
  ]
}

variable "client_app_names" {
  description = "List of user pool client application names to create"
  type        = list(string)
  default     = []
}

variable "client_generate_secret" {
  description = "Should secret be generated for user pool clients"
  type        = bool
  default     = false
}

variable "client_access_token_validity" {
  description = "Time duration for access token validity"
  type        = number
  default     = 120
}

variable "client_id_token_validity" {
  description = "Time duration for ID token validity"
  type        = number
  default     = 120
}

variable "client_refresh_token_validity" {
  description = "Time duration for refresh token validity"
  type        = number
  default     = 7
}

variable "client_allowed_oauth_flows_user_pool_client" {
  description = "Whether the client is allowed to use OAuth flows"
  type        = bool
  default     = false
}

variable "client_enable_token_revocation" {
  description = "Enables or disables token revocation"
  type        = bool
  default     = true
}

variable "client_explicit_auth_flows" {
  description = "List of authentication flows supported by user pool clients"
  type        = list(string)
  default = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_USER_SRP_AUTH"
  ]
}

variable "client_prevent_user_existence_errors" {
  description = "Errors returned when user does not exist"
  type        = string
  default     = "LEGACY"
}

variable "client_read_attributes" {
  description = "List of read attributes for user pool client"
  type        = list(string)
  default     = null
}

variable "client_write_attributes" {
  description = "List of write attributes for user pool client"
  type        = list(string)
  default     = null
}

variable "client_callback_urls" {
  description = "List of allowed callback URLs for the identity providers"
  type        = list(string)
  default     = []
}

variable "client_logout_urls" {
  description = "List of allowed logout URLs for the identity providers"
  type        = list(string)
  default     = []
}

variable "client_allowed_oauth_flows" {
  description = "List of allowed OAuth flows"
  type        = list(string)
  default     = []
}

variable "client_allowed_oauth_scopes" {
  description = "List of allowed OAuth scopes"
  type        = list(string)
  default     = []
}

variable "client_supported_identity_providers" {
  description = "List of provider names supported on the client"
  type        = list(string)
  default     = []
}

variable "user_group_name" {
  description = "Name of the Cognito user group to conditionally create"
  type        = string
  default     = ""
}

variable "user_group_precedence" {
  description = "Precedence of the Cognito user group"
  type        = number
  default     = 0
}

variable "user_group_role_arn" {
  description = "IAM role ARN associated with the user group"
  type        = string
  default     = null
}

variable "user_group_description" {
  description = "Description for the Cognito user group"
  type        = string
  default     = "Cognito user group"
}

variable "domain_name" {
  description = "Cognito User Pool domain string"
  type        = string
  default     = ""
}

variable "domain_certificate_arn" {
  description = "ACM certificate ARN for custom Cognito domain"
  type        = string
  default     = null
}

variable "create_route53_record" {
  description = "Whether to create a Route 53 alias record pointing to custom domain CloudFront distribution"
  type        = bool
  default     = false
}

variable "route53_zone_id" {
  description = "Route 53 hosted zone ID for the alias record"
  type        = string
  default     = ""
}

# ------------------------------------------------------------------------------
# Cognito User Pool
# ------------------------------------------------------------------------------

resource "aws_cognito_user_pool" "main" {
  name                     = var.pool_name
  alias_attributes         = var.alias_attributes
  auto_verified_attributes = var.auto_verified_attributes
  mfa_configuration        = var.mfa_configuration

  email_verification_message = var.email_verification_message
  email_verification_subject = var.email_verification_subject
  sms_authentication_message = var.sms_authentication_message
  sms_verification_message   = var.sms_verification_message

  dynamic "verification_message_template" {
    for_each = var.verification_message_template != null ? [var.verification_message_template] : []
    content {
      default_email_option  = lookup(verification_message_template.value, "default_email_option", "CONFIRM_WITH_CODE")
      email_message_by_link = lookup(verification_message_template.value, "email_message_by_link", null)
      email_subject_by_link = lookup(verification_message_template.value, "email_subject_by_link", null)
    }
  }

  account_recovery_setting {
    dynamic "recovery_mechanism" {
      for_each = var.recovery_mechanisms
      content {
        name     = recovery_mechanism.value.name
        priority = recovery_mechanism.value.priority
      }
    }
  }

  admin_create_user_config {
    allow_admin_create_user_only = var.admin_create_user_config.allow_admin_create_user_only

    dynamic "invite_message_template" {
      for_each = (
        var.admin_create_user_config.email_message != null ||
        var.admin_create_user_config.email_subject != null ||
        var.admin_create_user_config.sms_message != null
      ) ? [1] : []
      content {
        email_message = var.admin_create_user_config.email_message
        email_subject = var.admin_create_user_config.email_subject
        sms_message   = var.admin_create_user_config.sms_message
      }
    }

    unused_account_validity_days = var.admin_create_user_config.unused_account_validity_days
  }

  dynamic "software_token_mfa_configuration" {
    for_each = var.enable_software_token_mfa ? [1] : []
    content {
      enabled = true
    }
  }

  dynamic "sms_configuration" {
    for_each = (
      trimspace(var.sms_configuration.external_id) != "" &&
      trimspace(var.sms_configuration.sns_caller_arn) != ""
    ) ? [var.sms_configuration] : []
    content {
      external_id    = sms_configuration.value.external_id
      sns_caller_arn = sms_configuration.value.sns_caller_arn
    }
  }

  dynamic "user_pool_add_ons" {
    for_each = var.case_sensitive != null ? [1] : []
    content {
      advanced_security_mode = "OFF"
    }
  }

  dynamic "device_configuration" {
    for_each = var.device_configuration != null ? [var.device_configuration] : []
    content {
      challenge_required_on_new_device      = lookup(device_configuration.value, "challenge_required_on_new_device", false)
      device_only_remembered_on_user_prompt = lookup(device_configuration.value, "device_only_remembered_on_user_prompt", false)
    }
  }

  dynamic "lambda_config" {
    for_each = length(var.lambda_triggers) > 0 || var.custom_email_sender_lambda != null ? [1] : []
    content {
      create_auth_challenge          = lookup(var.lambda_triggers, "create_auth_challenge", null)
      custom_message                 = lookup(var.lambda_triggers, "custom_message", null)
      define_auth_challenge          = lookup(var.lambda_triggers, "define_auth_challenge", null)
      post_authentication            = lookup(var.lambda_triggers, "post_authentication", null)
      post_confirmation              = lookup(var.lambda_triggers, "post_confirmation", null)
      pre_authentication             = lookup(var.lambda_triggers, "pre_authentication", null)
      pre_sign_up                    = lookup(var.lambda_triggers, "pre_sign_up", null)
      pre_token_generation           = lookup(var.lambda_triggers, "pre_token_generation", null)
      user_migration                 = lookup(var.lambda_triggers, "user_migration", null)
      verify_auth_challenge_response = lookup(var.lambda_triggers, "verify_auth_challenge_response", null)

      dynamic "custom_email_sender" {
        for_each = var.custom_email_sender_lambda != null ? [var.custom_email_sender_lambda] : []
        content {
          lambda_arn     = custom_email_sender.value.lambda_arn
          lambda_version = custom_email_sender.value.lambda_version
        }
      }

      kms_key_id = var.custom_email_sender_lambda != null ? var.custom_email_sender_lambda.kms_key_arn : null
    }
  }

  dynamic "schema" {
    for_each = var.schema_attributes
    content {
      name                     = schema.value.name
      attribute_data_type      = schema.value.attribute_data_type
      developer_only_attribute = lookup(schema.value, "developer_only_attribute", false)
      mutable                  = lookup(schema.value, "mutable", true)
      required                 = lookup(schema.value, "required", false)

      dynamic "string_attribute_constraints" {
        for_each = schema.value.attribute_data_type == "String" && (
          lookup(schema.value, "min_length", null) != null ||
          lookup(schema.value, "max_length", null) != null
        ) ? [1] : []
        content {
          min_length = lookup(schema.value, "min_length", null)
          max_length = lookup(schema.value, "max_length", null)
        }
      }

      dynamic "number_attribute_constraints" {
        for_each = schema.value.attribute_data_type == "Number" && (
          lookup(schema.value, "min_value", null) != null ||
          lookup(schema.value, "max_value", null) != null
        ) ? [1] : []
        content {
          min_value = lookup(schema.value, "min_value", null)
          max_value = lookup(schema.value, "max_value", null)
        }
      }
    }
  }

  dynamic "username_configuration" {
    for_each = var.case_sensitive != null ? [1] : []
    content {
      case_sensitive = var.case_sensitive
    }
  }

  lifecycle {
    ignore_changes = [
      estimated_number_of_users
    ]
  }
}

# ------------------------------------------------------------------------------
# Cognito User Pool Clients
# ------------------------------------------------------------------------------

resource "aws_cognito_user_pool_client" "clients" {
  for_each = toset(var.client_app_names)

  name         = each.value
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret                      = var.client_generate_secret
  access_token_validity                = var.client_access_token_validity
  id_token_validity                    = var.client_id_token_validity
  refresh_token_validity               = var.client_refresh_token_validity
  allowed_oauth_flows_user_pool_client = var.client_allowed_oauth_flows_user_pool_client
  enable_token_revocation              = var.client_enable_token_revocation
  explicit_auth_flows                  = var.client_explicit_auth_flows
  prevent_user_existence_errors        = var.client_prevent_user_existence_errors

  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }

  read_attributes  = var.client_read_attributes
  write_attributes = var.client_write_attributes

  callback_urls                = length(var.client_callback_urls) > 0 ? var.client_callback_urls : null
  logout_urls                  = length(var.client_logout_urls) > 0 ? var.client_logout_urls : null
  allowed_oauth_flows          = length(var.client_allowed_oauth_flows) > 0 ? var.client_allowed_oauth_flows : null
  allowed_oauth_scopes         = length(var.client_allowed_oauth_scopes) > 0 ? var.client_allowed_oauth_scopes : null
  supported_identity_providers = length(var.client_supported_identity_providers) > 0 ? var.client_supported_identity_providers : null
}

# ------------------------------------------------------------------------------
# Cognito User Group
# ------------------------------------------------------------------------------

resource "aws_cognito_user_group" "main" {
  count = trimspace(var.user_group_name) != "" ? 1 : 0

  name         = var.user_group_name
  user_pool_id = aws_cognito_user_pool.main.id
  description  = var.user_group_description
  precedence   = var.user_group_precedence
  role_arn     = var.user_group_role_arn
}

# ------------------------------------------------------------------------------
# Cognito User Pool Domain
# ------------------------------------------------------------------------------

resource "aws_cognito_user_pool_domain" "main" {
  count = trimspace(var.domain_name) != "" ? 1 : 0

  domain          = var.domain_name
  user_pool_id    = aws_cognito_user_pool.main.id
  certificate_arn = var.domain_certificate_arn
}

# ------------------------------------------------------------------------------
# Route 53 Alias Record
# ------------------------------------------------------------------------------

resource "aws_route53_record" "cognito_domain_alias" {
  count = var.create_route53_record && trimspace(var.route53_zone_id) != "" && length(aws_cognito_user_pool_domain.main) > 0 ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_cognito_user_pool_domain.main[0].cloudfront_distribution_arn
    zone_id                = "Z2FDTNDATAQYW2"
    evaluate_target_health = false
  }
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "user_pool_id" {
  description = "The ID of the Cognito User Pool"
  value       = aws_cognito_user_pool.main.id
}

output "user_pool_arn" {
  description = "The ARN of the Cognito User Pool"
  value       = aws_cognito_user_pool.main.arn
}

output "user_pool_endpoint" {
  description = "The endpoint of the Cognito User Pool"
  value       = aws_cognito_user_pool.main.endpoint
}

output "user_pool_client_ids" {
  description = "Map of client names to client IDs"
  value       = { for k, v in aws_cognito_user_pool_client.clients : k => v.id }
}

output "cognito_domain_cloudfront_distribution" {
  description = "CloudFront distribution address for custom Cognito domain"
  value       = length(aws_cognito_user_pool_domain.main) > 0 ? aws_cognito_user_pool_domain.main[0].cloudfront_distribution_arn : null
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  type        = string
  description = "Name tag for the VPC"
  default     = "DevOps-Project-VPC"
}

variable "igw_name" {
  type        = string
  description = "Name tag for the Internet Gateway"
  default     = "devops-project-igw"
}

variable "route_table_name" {
  type        = string
  description = "Name tag for the public route table"
  default     = "DevOps-project-RT"
}

variable "public_subnet_identifier" {
  type        = string
  description = "Identifier name for the public subnet"
  default     = "subnet_a"
}

variable "nat_gateway_name" {
  type        = string
  description = "Name tag for the NAT Gateway"
  default     = "DevOps-NAT-GW"
}

variable "public_ipv4_pool" {
  type        = string
  description = "Public IPv4 pool for Elastic IP allocation"
  default     = "amazon"
}

variable "subnet_a_cidr" {
  type        = string
  description = "CIDR block for Subnet A"
  default     = "10.0.1.0/24"
}

variable "subnet_a_name" {
  type        = string
  description = "Name tag for Subnet A"
  default     = "Subnet-A-Public"
}

variable "subnet_a_map_public_ip" {
  type        = bool
  description = "Specify true to enable public IP assignment for Subnet A"
  default     = false
}

variable "subnet_b_cidr" {
  type        = string
  description = "CIDR block for Subnet B"
  default     = "10.0.2.0/24"
}

variable "subnet_b_name" {
  type        = string
  description = "Name tag for Subnet B"
  default     = "Subnet-B-Private"
}

variable "subnet_b_map_public_ip" {
  type        = bool
  description = "Specify true to enable public IP assignment for Subnet B"
  default     = false
}

variable "subnet_c_cidr" {
  type        = string
  description = "CIDR block for Subnet C"
  default     = "10.0.3.0/24"
}

variable "subnet_c_name" {
  type        = string
  description = "Name tag for Subnet C"
  default     = "Subnet-C-Private"
}

variable "subnet_c_map_public_ip" {
  type        = bool
  description = "Specify true to enable public IP assignment for Subnet C"
  default     = false
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_name
  }
}

resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_a_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = var.subnet_a_map_public_ip

  tags = {
    Name = var.subnet_a_name
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_b_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = var.subnet_b_map_public_ip

  tags = {
    Name = var.subnet_b_name
  }
}

resource "aws_subnet" "subnet_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_c_cidr
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = var.subnet_c_map_public_ip

  tags = {
    Name = var.subnet_c_name
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = var.route_table_name
  }
}

resource "aws_route_table_association" "subnet_a" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain            = "vpc"
  public_ipv4_pool  = var.public_ipv4_pool
  depends_on        = [aws_internet_gateway.main]

  tags = {
    Name = "${var.nat_gateway_name}-eip"
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.subnet_b.id
  depends_on    = [aws_internet_gateway.main]

  tags = {
    Name = var.nat_gateway_name
  }
}

resource "aws_security_group" "default" {
  name        = "DefaultSecurityGroup"
  description = "Default security group allowing outbound traffic only within the VPC"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow outbound traffic only within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "DefaultSecurityGroup"
  }
}

output "nat_gateway_public_ip" {
  description = "Public IP address of the NAT Gateway"
  value       = aws_nat_gateway.nat.public_ip
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------

variable "vault_name" {
  description = "The name of the AWS Backup vault"
  type        = string
  default     = "my-backup-vault"
}

variable "backup_tag_key" {
  description = "The tag key used by backup selections to identify resources"
  type        = string
  default     = "backup"
}

variable "daily_continuous_backup" {
  description = "Whether to enable continuous backup (point-in-time recovery) for the daily backup rule"
  type        = bool
  default     = false
}

variable "daily_schedule" {
  description = "Cron schedule expression for the daily backup plan"
  type        = string
  default     = "cron(0 12 ? * * *)"
}

variable "weekly_schedule" {
  description = "Cron schedule expression for the weekly backup plan"
  type        = string
  default     = "cron(0 12 ? * 1 *)"
}

variable "monthly_schedule" {
  description = "Cron schedule expression for the monthly backup plan"
  type        = string
  default     = "cron(0 12 1 * ? *)"
}

variable "enable_notifications" {
  description = "Whether to configure backup vault notifications via SNS"
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "The ARN of the SNS topic to receive backup vault notifications"
  type        = string
  default     = ""
}

variable "notification_events" {
  description = "List of backup vault events for notifications"
  type        = list(string)
  default = [
    "BACKUP_JOB_FAILED",
    "RESTORE_JOB_FAILED",
    "COPY_JOB_FAILED",
    "S3_BACKUP_OBJECT_FAILED",
    "S3_RESTORE_OBJECT_FAILED"
  ]
}

variable "tags" {
  description = "A map of tags to assign to resources"
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# KMS Key for AWS Backup Vault
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "kms_backup_key_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowAWSBackupKeyAccess"
    effect = "Allow"
    actions = [
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:CreateGrant",
      "kms:ListGrants",
      "kms:RevokeGrant"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "backup" {
  description             = "KMS CMK for AWS Backup Vault encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_backup_key_policy.json
  tags                    = var.tags
}

resource "aws_kms_alias" "backup" {
  name          = "alias/${var.vault_name}-key"
  target_key_id = aws_kms_key.backup.key_id
}

# -----------------------------------------------------------------------------
# AWS Backup Vault
# -----------------------------------------------------------------------------

resource "aws_backup_vault" "main" {
  name        = var.vault_name
  kms_key_arn = aws_kms_key.backup.arn
  tags        = var.tags
}

# -----------------------------------------------------------------------------
# IAM Role for AWS Backup
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    sid     = "AWSBackupAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name               = "${var.vault_name}-service-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# -----------------------------------------------------------------------------
# Daily Backup Plan and Selection
# -----------------------------------------------------------------------------

resource "aws_backup_plan" "daily" {
  name = "${var.vault_name}-daily"

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  rule {
    rule_name                = "daily_backup_rule"
    target_vault_name        = aws_backup_vault.main.name
    schedule                 = var.daily_schedule
    enable_continuous_backup = var.daily_continuous_backup

    lifecycle {
      delete_after = 7
    }
  }

  tags = var.tags
}

resource "aws_backup_selection" "daily" {
  name         = "daily_backup_selection"
  plan_id      = aws_backup_plan.daily.id
  iam_role_arn = aws_iam_role.backup.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "daily"
  }
}

# -----------------------------------------------------------------------------
# Weekly Backup Plan and Selection
# -----------------------------------------------------------------------------

resource "aws_backup_plan" "weekly" {
  name = "${var.vault_name}-weekly"

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  rule {
    rule_name         = "weekly_backup_rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = var.weekly_schedule

    lifecycle {
      delete_after = 31
    }
  }

  tags = var.tags
}

resource "aws_backup_selection" "weekly" {
  name         = "weekly_backup_selection"
  plan_id      = aws_backup_plan.weekly.id
  iam_role_arn = aws_iam_role.backup.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "weekly"
  }
}

# -----------------------------------------------------------------------------
# Monthly Backup Plan and Selection
# -----------------------------------------------------------------------------

resource "aws_backup_plan" "monthly" {
  name = "${var.vault_name}-monthly"

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  rule {
    rule_name         = "monthly_backup_rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = var.monthly_schedule

    lifecycle {
      delete_after = 366
    }
  }

  tags = var.tags
}

resource "aws_backup_selection" "monthly" {
  name         = "monthly_backup_selection"
  plan_id      = aws_backup_plan.monthly.id
  iam_role_arn = aws_iam_role.backup.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "monthly"
  }
}

# -----------------------------------------------------------------------------
# Backup Vault Notifications (Optional)
# -----------------------------------------------------------------------------

resource "aws_backup_vault_notifications" "notifications" {
  count = var.enable_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.main.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.notification_events
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "backup_vault_id" {
  description = "The name of the AWS Backup vault"
  value       = aws_backup_vault.main.id
}

output "backup_vault_arn" {
  description = "The ARN of the AWS Backup vault"
  value       = aws_backup_vault.main.arn
}

output "kms_key_arn" {
  description = "The ARN of the KMS key used to encrypt the backup vault"
  value       = aws_kms_key.backup.arn
}

output "iam_role_arn" {
  description = "The ARN of the IAM role used by AWS Backup"
  value       = aws_iam_role.backup.arn
}

output "daily_backup_plan_id" {
  description = "The ID of the daily backup plan"
  value       = aws_backup_plan.daily.id
}

output "weekly_backup_plan_id" {
  description = "The ID of the weekly backup plan"
  value       = aws_backup_plan.weekly.id
}

output "monthly_backup_plan_id" {
  description = "The ID of the monthly backup plan"
  value       = aws_backup_plan.monthly.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-east-1"
}

variable "env" {
  type        = string
  description = "Environment identifier"
  default     = "test"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for public subnets"
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "private_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for private subnets"
  default     = ["10.0.20.0/24", "10.0.21.0/24"]
}

variable "common_tags" {
  type        = map(string)
  description = "Common tags applied to all resources"
  default = {
    Owner   = "Valerii Vasianovych"
    Project = "Terraform AWS"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(
    var.common_tags,
    {
      Name   = "${var.env}-vpc"
      Region = var.aws_region
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-igw"
    }
  )
}

resource "aws_subnet" "public" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index % length(data.aws_availability_zones.available.names)]
  map_public_ip_on_launch = false

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-public-subnet-${count.index + 1}"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-route-public-subnets"
    }
  )
}

resource "aws_route_table_association" "public" {
  count          = length(var.public_subnet_cidrs)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count  = length(var.private_subnet_cidrs)
  domain = "vpc"

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-nat-eip-${count.index + 1}"
    }
  )
}

resource "aws_nat_gateway" "main" {
  count         = length(var.private_subnet_cidrs)
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-nat-gw-${count.index + 1}"
    }
  )
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index % length(data.aws_availability_zones.available.names)]

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-private-subnet-${count.index + 1}"
    }
  )
}

resource "aws_route_table" "private" {
  count  = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-route-private-subnets-${count.index + 1}"
    }
  )
}

resource "aws_route_table_association" "private" {
  count          = length(var.private_subnet_cidrs)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "create_eks" {
  description = "Controls whether the EKS cluster and associated resources should be created."
  type        = bool
  default     = false
}

variable "cluster_name" {
  description = "Name of the EKS cluster."
  type        = string
  default     = ""
}

variable "cluster_version" {
  description = "Kubernetes version to use for the EKS cluster."
  type        = string
  default     = null
}

variable "authentication_mode" {
  description = "The authentication mode for the EKS cluster."
  type        = string
  default     = "API_AND_CONFIG_MAP"
}

variable "control_plane_subnet_ids" {
  description = "A list of subnet IDs for the EKS cluster control plane."
  type        = list(string)
  default     = []
}

variable "subnet_ids" {
  description = "A list of subnet IDs where the EKS cluster (and worker nodes) will be located."
  type        = list(string)
  default     = []
}

data "aws_iam_policy_document" "eks_assume_role" {
  count = var.create_eks ? 1 : 0

  statement {
    sid     = "EKSClusterAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_cluster" {
  count = var.create_eks ? 1 : 0

  name               = "eks-cluster"
  assume_role_policy = data.aws_iam_policy_document.eks_assume_role[0].json
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  count = var.create_eks ? 1 : 0

  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster[0].name
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  count = var.create_eks ? 1 : 0

  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.eks_cluster[0].name
}

resource "aws_eks_cluster" "this" {
  count = var.create_eks ? 1 : 0

  name     = var.cluster_name
  version  = var.cluster_version
  role_arn = aws_iam_role.eks_cluster[0].arn

  access_config {
    authentication_mode                         = var.authentication_mode
    bootstrap_cluster_creator_admin_permissions = true
  }

  vpc_config {
    subnet_ids = length(var.control_plane_subnet_ids) > 0 ? var.control_plane_subnet_ids : var.subnet_ids
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller
  ]
}

output "cluster_arn" {
  description = "The Amazon Resource Name (ARN) of the cluster."
  value       = try(aws_eks_cluster.this[0].arn, null)
}

output "cluster_endpoint" {
  description = "The endpoint for the Kubernetes API server."
  value       = try(aws_eks_cluster.this[0].endpoint, null)
}

output "cluster_name" {
  description = "The name of the EKS cluster."
  value       = try(aws_eks_cluster.this[0].name, null)
}

output "cluster_iam_role_arn" {
  description = "IAM role ARN assumed by the EKS cluster."
  value       = try(aws_iam_role.eks_cluster[0].arn, null)
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

locals {
  user_path = "/system/"
  common_tags = {
    Name         = "rwwise.dev Infrastructure Setup"
    Repository   = "https://github.com/zangrum/setup.inf.rwwise.dev"
    AccountId    = data.aws_caller_identity.current.account_id
    CallerUserId = data.aws_caller_identity.current.user_id
  }
}

data "aws_iam_policy_document" "cicd_permissions" {
  statement {
    sid    = "CodeStarConnectionsUserAccess"
    effect = "Allow"
    actions = [
      "codestar-connections:GetConnection",
      "codestar-connections:ListConnections",
      "codestar-connections:ListInstallationTargets",
      "codestar-connections:GetInstallationUrl"
    ]
    resources = [
      "arn:aws:codestar-connections:*:*:connection/*"
    ]
  }

  statement {
    sid    = "CodeStarNotificationsPowerUserAccess"
    effect = "Allow"
    actions = [
      "codestar-notifications:DescribeNotificationRule"
    ]
    resources = ["*"]

    condition {
      test     = "StringLike"
      variable = "codestar-notifications:NotificationsForResource"
      values   = ["arn:aws:codebuild:*"]
    }
  }

  statement {
    sid    = "CodeStarNotificationsListAccess"
    effect = "Allow"
    actions = [
      "codestar-notifications:ListEventTypes",
      "codestar-notifications:ListNotificationRules",
      "codestar-notifications:ListTargets"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CICDReadOnlyAccess"
    effect = "Allow"
    actions = [
      "codebuild:BatchGet*",
      "codebuild:Describe*",
      "codebuild:Get*",
      "codebuild:List*",
      "codecommit:BatchDescribe*",
      "codecommit:BatchGet*",
      "codecommit:Describe*",
      "codecommit:Get*",
      "codecommit:GitPull",
      "codecommit:List*",
      "cloudwatch:Describe*",
      "cloudwatch:Get*",
      "cloudwatch:List*",
      "events:Describe*",
      "events:List*",
      "events:TestEventPattern",
      "logs:Describe*",
      "logs:FilterLogEvents",
      "logs:Get*",
      "logs:List*"
    ]
    resources = ["*"]
  }
}

# Development IAM User, Access Key, and Inline Policy
resource "aws_iam_user" "dev_user" {
  name = "DevUser-rwwise.dev"
  path = locals.user_path
  tags = locals.common_tags
}

resource "aws_iam_access_key" "dev_access_key" {
  user   = aws_iam_user.dev_user.name
  status = "Active"
}

resource "aws_iam_user_policy" "dev_policy" {
  name   = "dev_cicd_user_policy"
  user   = aws_iam_user.dev_user.name
  policy = data.aws_iam_policy_document.cicd_permissions.json
}

# Test IAM User, Access Key, and Inline Policy
resource "aws_iam_user" "test_user" {
  name = "TestUser-rwwise.dev"
  path = locals.user_path
  tags = locals.common_tags
}

resource "aws_iam_access_key" "test_access_key" {
  user   = aws_iam_user.test_user.name
  status = "Active"
}

resource "aws_iam_user_policy" "test_policy" {
  name   = "test_cicd_user_policy"
  user   = aws_iam_user.test_user.name
  policy = data.aws_iam_policy_document.cicd_permissions.json
}

# Production IAM User, Access Key, and Inline Policy
resource "aws_iam_user" "prod_user" {
  name = "ProdUser-rwwise.dev"
  path = locals.user_path
  tags = locals.common_tags
}

resource "aws_iam_access_key" "prod_access_key" {
  user   = aws_iam_user.prod_user.name
  status = "Active"
}

resource "aws_iam_user_policy" "prod_policy" {
  name   = "prod_cicd_user_policy"
  user   = aws_iam_user.prod_user.name
  policy = data.aws_iam_policy_document.cicd_permissions.json
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name" {
  description = "Optional name for the EventBridge module. Falls back to 'default' if null or empty."
  type        = string
  default     = null
}

variable "tags" {
  description = "A map of tags to assign to resources."
  type        = map(string)
  default     = {}
}

variable "bus" {
  description = "Bus configuration map supporting an optional event_source_name."
  type        = map(string)
  default     = {}
  validation {
    condition     = var.bus != null
    error_message = "The bus variable must not be null."
  }
}

variable "rules" {
  description = "List of rule configurations."
  type        = list(any)
  default     = []
  validation {
    condition     = var.rules != null
    error_message = "The rules variable must not be null."
  }
}

variable "targets" {
  description = "List of target configurations."
  type        = list(any)
  default     = []
  validation {
    condition     = var.targets != null
    error_message = "The targets variable must not be null."
  }
}

data "aws_partition" "current" {}

locals {
  bus_name          = var.name != null && trimspace(var.name) != "" ? trimspace(var.name) : "default"
  create_custom_bus = local.bus_name != "default"
  event_bus_name    = local.create_custom_bus ? aws_cloudwatch_event_bus.this[0].name : "default"

  rules_map = {
    for rule in var.rules : rule.name => rule
  }

  targets_map = {
    for target in var.targets :
    lookup(target, "target_id", "${lookup(target, "rule", "")}-${lookup(target, "arn", "")}") => target
  }
}

resource "aws_cloudwatch_event_bus" "this" {
  count             = local.create_custom_bus ? 1 : 0
  name              = local.bus_name
  event_source_name = lookup(var.bus, "event_source_name", null)
  tags              = var.tags
}

resource "aws_iam_role" "invoke" {
  name = "${local.bus_name}-invoke"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "events.${data.aws_partition.current.dns_suffix}"
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "invoke_targets" {
  name = "${local.bus_name}-invoke-targets"
  role = aws_iam_role.invoke.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "InvokeTargetPermissions"
        Effect   = "Allow"
        Action   = [
          "lambda:InvokeFunction",
          "states:StartExecution"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_cloudwatch_event_rule" "this" {
  for_each = local.rules_map

  name                = each.value.name
  description         = lookup(each.value, "description", null)
  event_bus_name      = local.event_bus_name
  event_pattern       = lookup(each.value, "event_pattern", null)
  schedule_expression = lookup(each.value, "schedule_expression", null)
  tags                = var.tags
}

resource "aws_cloudwatch_event_target" "this" {
  for_each = local.targets_map

  rule           = each.value.rule
  event_bus_name = local.event_bus_name
  target_id      = lookup(each.value, "target_id", null)
  arn            = each.value.arn
  role_arn       = can(regex("stateMachine", each.value.arn)) ? aws_iam_role.invoke.arn : lookup(each.value, "role_arn", null)

  depends_on = [
    aws_cloudwatch_event_rule.this
  ]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name" {
  type        = string
  description = "Identifier name used for naming and tagging backup resources"
  default     = "default"
}

variable "kms_key_arn" {
  type        = string
  description = "The server-side encryption key that is used to protect your backups"
  default     = null
}

variable "vault_policy" {
  type        = string
  description = "A valid JSON document that defines the permissions to access the backup vault"
  default     = ""
}

variable "schedule" {
  type        = string
  description = "A CRON expression specifying when AWS Backup initiates a backup job"
  default     = "cron(0 12 * * ? *)"
}

variable "start_window" {
  type        = number
  description = "The amount of time in minutes before beginning a backup"
  default     = 60
}

variable "completion_window" {
  type        = number
  description = "The amount of time in minutes AWS Backup attempts to complete a backup"
  default     = 120
}

variable "cold_storage_after" {
  type        = number
  description = "Specifies the number of days after creation that a recovery point is moved to cold storage"
  default     = 30
}

variable "delete_after" {
  type        = number
  description = "Specifies the number of days after creation that a recovery point is deleted"
  default     = 120
}

variable "copy_actions" {
  type = map(object({
    destination_vault_arn = string
    cold_storage_after    = optional(number)
    delete_after          = optional(number)
  }))
  description = "Map of configuration blocks for dynamic copy actions"
  default     = {}
}

variable "selection_tag_type" {
  type        = string
  description = "An operation, such as STRINGEQUALS, that is applied to key-value pairs"
  default     = "STRINGEQUALS"
}

variable "selection_tag_key" {
  type        = string
  description = "The key in a key-value pair for backup selection"
  default     = "Backup"
}

variable "selection_tag_value" {
  type        = string
  description = "The value in a key-value pair for backup selection"
  default     = "true"
}

variable "sns_topic_arn" {
  type        = string
  description = "The Amazon Resource Name (ARN) that specifies the topic for a backup vault's events"
  default     = ""
}

variable "sns_events" {
  type        = list(string)
  description = "An array of events that indicate the status of jobs to be published to SNS"
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

locals {
  job_tag = "${var.name}-backup"
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup_role" {
  name               = "aws-backup-${var.name}-backup"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
}

resource "aws_iam_role_policy_attachment" "backup_role_policy" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_backup_vault" "vault" {
  name        = "vault-${var.name}-backup"
  kms_key_arn = var.kms_key_arn

  tags = {
    Job = local.job_tag
  }
}

resource "aws_backup_vault_policy" "vault_policy" {
  count             = var.vault_policy != "" ? 1 : 0
  backup_vault_name = aws_backup_vault.vault.name
  policy            = var.vault_policy
}

resource "aws_backup_vault_notifications" "vault_notifications" {
  count               = var.sns_topic_arn != "" ? 1 : 0
  backup_vault_name   = aws_backup_vault.vault.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.sns_events
}

resource "aws_backup_plan" "plan" {
  name = "plan-${var.name}-backup"

  rule {
    rule_name         = "rule-${var.name}-backup"
    target_vault_name = aws_backup_vault.vault.name
    schedule          = var.schedule
    start_window      = var.start_window
    completion_window = var.completion_window

    recovery_point_tags = {
      Job = local.job_tag
    }

    lifecycle {
      cold_storage_after = var.cold_storage_after
      delete_after       = var.delete_after
    }

    dynamic "copy_action" {
      for_each = var.copy_actions
      content {
        destination_vault_arn = copy_action.value.destination_vault_arn

        dynamic "lifecycle" {
          for_each = copy_action.value.cold_storage_after != null || copy_action.value.delete_after != null ? [1] : []
          content {
            cold_storage_after = copy_action.value.cold_storage_after
            delete_after       = copy_action.value.delete_after
          }
        }
      }
    }
  }

  tags = {
    Job = local.job_tag
  }
}

resource "aws_backup_selection" "selection" {
  iam_role_arn = aws_iam_role.backup_role.arn
  name         = "selection-${var.name}-backup"
  plan_id      = aws_backup_plan.plan.id

  condition {}

  selection_tag {
    type  = var.selection_tag_type
    key   = var.selection_tag_key
    value = var.selection_tag_value
  }
}

output "backup_vault_arn" {
  description = "The ARN of the backup vault"
  value       = aws_backup_vault.vault.arn
}

output "backup_vault_name" {
  description = "The name of the backup vault"
  value       = aws_backup_vault.vault.name
}

output "backup_plan_id" {
  description = "The id of the backup plan"
  value       = aws_backup_plan.plan.id
}

output "backup_plan_arn" {
  description = "The ARN of the backup plan"
  value       = aws_backup_plan.plan.arn
}

output "backup_role_arn" {
  description = "The ARN of the IAM role used by AWS Backup"
  value       = aws_iam_role.backup_role.arn
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "create" {
  description = "Whether to create a new Transit Gateway or look up an existing one."
  type        = bool
  default     = true
}

variable "id" {
  description = "The ID of an existing Transit Gateway to look up when create is false."
  type        = string
  default     = null
}

variable "name" {
  description = "Name of the Transit Gateway, used for tagging and lookup filtering."
  type        = string
  default     = null
}

variable "amazon_side_asn" {
  description = "Private Autonomous System Number (ASN) for the Amazon side of a BGP session."
  type        = number
  default     = 65200
}

variable "auto_accept_shared_attachments" {
  description = "Whether attachment requests are automatically accepted."
  type        = string
  default     = "disable"
}

variable "dns_support" {
  description = "Whether DNS support is enabled."
  type        = string
  default     = "enable"
}

variable "vpn_ecmp_support" {
  description = "Whether VPN Equal Cost Multipath Protocol support is enabled."
  type        = string
  default     = "enable"
}

variable "transit_gateway_cidr_blocks" {
  description = "One or more IPv4 or IPv6 CIDR blocks for the transit gateway."
  type        = list(string)
  default     = []
  validation {
    condition = can([
      for cidr in var.transit_gateway_cidr_blocks : cidrhost(cidr, 0)
    ])
    error_message = "All entries in transit_gateway_cidr_blocks must be valid IPv4 or IPv6 CIDR notations."
  }
}

variable "route_tables" {
  description = "Map of route tables to create or look up. Each entry can contain create (bool) and local_tags (map(string))."
  type        = any
  default     = {}
}

variable "shared_principals" {
  description = "Map of principal identifiers (e.g. AWS account IDs, Org ARNs) to share the Transit Gateway with via AWS RAM."
  type        = map(string)
  default     = {}
}

variable "ram_resource_share_name" {
  description = "The name of the resource share. Defaults to var.name or 'tgw-share'."
  type        = string
  default     = null
}

variable "tags" {
  description = "Additional tags to apply to all resources."
  type        = map(string)
  default     = {}
}

locals {
  tgw_name = coalesce(var.name, "tgw")
  tgw_tags = merge(
    var.tags,
    {
      Name = local.tgw_name
    }
  )

  tgw_id = var.create ? aws_ec2_transit_gateway.this[0].id : (
    var.id != null ? data.aws_ec2_transit_gateway.this[0].id : data.aws_ec2_transit_gateway.this[0].id
  )

  tgw_arn = var.create ? aws_ec2_transit_gateway.this[0].arn : data.aws_ec2_transit_gateway.this[0].arn

  tables_to_create = {
    for k, v in var.route_tables : k => v
    if try(v.create, true)
  }

  tables_to_lookup = {
    for k, v in var.route_tables : k => v
    if !try(v.create, true)
  }

  enable_ram_sharing = length(var.shared_principals) > 0
  ram_share_name     = coalesce(var.ram_resource_share_name, var.name, "tgw-share")
}

data "aws_ec2_transit_gateway" "this" {
  count = var.create ? 0 : 1

  id = var.id

  dynamic "filter" {
    for_each = var.id == null && var.name != null ? [1] : []
    content {
      name   = "tag:Name"
      values = [var.name]
    }
  }
}

resource "aws_ec2_transit_gateway" "this" {
  count = var.create ? 1 : 0

  amazon_side_asn                 = var.amazon_side_asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  default_route_table_association = "disable"
  default_route_table_propagation = "disable"
  dns_support                     = var.dns_support
  vpn_ecmp_support                = var.vpn_ecmp_support
  transit_gateway_cidr_blocks     = var.transit_gateway_cidr_blocks

  tags = local.tgw_tags
}

data "aws_ec2_transit_gateway_route_table" "this" {
  for_each = local.tables_to_lookup

  filter {
    name   = "transit-gateway-id"
    values = [local.tgw_id]
  }

  filter {
    name   = "tag:Name"
    values = [each.key]
  }
}

resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = local.tables_to_create

  transit_gateway_id = local.tgw_id

  tags = merge(
    var.tags,
    try(each.value.local_tags, {}),
    {
      Name = coalesce(each.key, local.tgw_name)
    }
  )
}

resource "aws_ram_resource_share" "this" {
  count = local.enable_ram_sharing ? 1 : 0

  name                      = local.ram_share_name
  allow_external_principals = true

  tags = merge(
    var.tags,
    {
      Name = local.ram_share_name
    }
  )
}

resource "aws_ram_resource_association" "this" {
  count = local.enable_ram_sharing ? 1 : 0

  resource_arn       = local.tgw_arn
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

resource "aws_ram_principal_association" "this" {
  for_each = local.enable_ram_sharing ? var.shared_principals : {}

  principal          = each.value
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

output "transit_gateway_id" {
  description = "The ID of the Transit Gateway."
  value       = local.tgw_id
}

output "transit_gateway_arn" {
  description = "The ARN of the Transit Gateway."
  value       = local.tgw_arn
}

output "transit_gateway_route_table_ids" {
  description = "Map of all Transit Gateway route table IDs (both created and looked up)."
  value = merge(
    { for k, v in aws_ec2_transit_gateway_route_table.this : k => v.id },
    { for k, v in data.aws_ec2_transit_gateway_route_table.this : k => v.id }
  )
}

output "ram_resource_share_arn" {
  description = "The ARN of the RAM Resource Share, if created."
  value       = local.enable_ram_sharing ? aws_ram_resource_share.this[0].arn : null
}

output "ram_principal_association_ids" {
  description = "The IDs of the RAM principal associations."
  value       = { for k, v in aws_ram_principal_association.this : k => v.id }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# KMS Key for Backup Vault Encryption
# -----------------------------------------------------------------------------

resource "aws_kms_key" "backup_key" {
  description             = "KMS key used to encrypt AWS Backup vaults across all tiers"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_kms_alias" "backup_key_alias" {
  name          = "alias/backup-key"
  target_key_id = aws_kms_key.backup_key.key_id
}

# -----------------------------------------------------------------------------
# IAM Service Role for AWS Backup
# -----------------------------------------------------------------------------

resource "aws_iam_role" "bronze_backup_role" {
  name = "Bronze_Backup_Role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_policy" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restore_policy" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

# -----------------------------------------------------------------------------
# Bronze Tier
# -----------------------------------------------------------------------------

resource "aws_backup_vault" "bronze" {
  name        = "Bronze_Backup_Vault"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_plan" "bronze" {
  name = "Bronze_Backup"

  rule {
    rule_name         = "Bronze_Backup_Weekly"
    target_vault_name = aws_backup_vault.bronze.name
    schedule          = "cron(0 0 ? * FRI *)"

    lifecycle {
      delete_after = 10
    }
  }
}

resource "aws_backup_selection" "bronze" {
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  name         = "Bronze_Resource_Assignment"
  plan_id      = aws_backup_plan.bronze.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "bronze"
  }
}

# -----------------------------------------------------------------------------
# Silver Tier
# -----------------------------------------------------------------------------

resource "aws_backup_vault" "silver" {
  name        = "Silver_Backup_Vault"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_plan" "silver" {
  name = "Silver_Backup_Plan"

  rule {
    rule_name         = "Silver_Backup_Daily"
    target_vault_name = aws_backup_vault.silver.name
    schedule          = "cron(0 5 ? * * *)"

    lifecycle {
      delete_after = 7
    }
  }
}

resource "aws_backup_selection" "silver" {
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  name         = "Silver_Backup_resource"
  plan_id      = aws_backup_plan.silver.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "silver"
  }
}

# -----------------------------------------------------------------------------
# Gold Tier
# -----------------------------------------------------------------------------

resource "aws_backup_vault" "gold" {
  name        = "Gold_Backup_Vault"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_plan" "gold" {
  name = "Gold_Backup"

  rule {
    rule_name         = "Gold_Daily_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 * * ? *)"

    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Gold_Monthly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 1 1/1 ? *)"

    lifecycle {
      delete_after = 365
    }
  }

  rule {
    rule_name         = "Gold_Yearly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 31 12 ? *)"

    lifecycle {
      delete_after = 2555
    }
  }
}

resource "aws_backup_selection" "gold" {
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  name         = "Gold_Backup_Select"
  plan_id      = aws_backup_plan.gold.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "gold"
  }
}

# -----------------------------------------------------------------------------
# Premium Tier
# -----------------------------------------------------------------------------

resource "aws_backup_vault" "premium" {
  name        = "Premium"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_plan" "premium" {
  name = "Premium"

  rule {
    rule_name         = "Premium_Daily_4Hour_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0/4 ? * * *)"

    lifecycle {
      delete_after = 1
    }
  }

  rule {
    rule_name         = "Premium_Daily_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 * * ? *)"

    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Premium_Monthly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 1 1/1 ? *)"

    lifecycle {
      cold_storage_after = 15
      delete_after       = 365
    }
  }

  rule {
    rule_name         = "Premium_Yearly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 31 12 ? *)"

    lifecycle {
      cold_storage_after = 15
      delete_after       = 2555
    }
  }
}

resource "aws_backup_selection" "premium" {
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  name         = "Premium"
  plan_id      = aws_backup_plan.premium.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "premium"
  }
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region for deployment"
  type        = string
  default     = "us-east-1"
}

variable "role_name" {
  description = "Name of the IAM role for Prisma Cloud integration"
  type        = string
  default     = "PrismaCloudReadWriteRole"
}

variable "read_write" {
  description = "Enable remediation permissions for Prisma Cloud"
  type        = bool
  default     = false
}

resource "random_string" "external_id" {
  length  = 32
  special = false
}

data "aws_iam_policy_document" "prisma_cloud_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::188619942792:root"]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [random_string.external_id.result]
    }
  }
}

resource "aws_iam_role" "prisma_cloud_role" {
  name               = var.role_name
  assume_role_policy = data.aws_iam_policy_document.prisma_cloud_assume_role.json
}

resource "aws_iam_role_policy_attachment" "security_audit" {
  role       = aws_iam_role.prisma_cloud_role.name
  policy_arn = "arn:aws:iam::aws:policy/SecurityAudit"
}

data "aws_iam_policy_document" "prisma_cloud_read_only" {
  statement {
    effect = "Allow"
    actions = [
      "apigateway:GET",
      "cognito-identity:ListTagsForResource",
      "cognito-idp:ListTagsForResource",
      "ecr:DescribeImages",
      "ecr:GetLifecyclePolicy",
      "elasticbeanstalk:ListTagsForResource",
      "elasticfilesystem:DescribeTags",
      "elasticmapreduce:ListSecurityConfigurations",
      "glacier:GetVaultLock",
      "glacier:ListTagsForVault",
      "glue:GetSecurityConfigurations",
      "logs:GetLogEvents",
      "mq:describeBroker",
      "mq:listBrokers",
      "ram:GetResourceShares",
      "secretsmanager:DescribeSecret",
      "sns:listSubscriptions",
      "sqs:SendMessage",
      "ssm:GetParameters",
      "ssm:ListTagsForResource",
      "wafv2:ListResourcesForWebACL",
      "wafv2:ListWebACLs"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "prisma_cloud_read_only" {
  name   = "PrismaCloud-IAM-ReadOnly-Policy"
  role   = aws_iam_role.prisma_cloud_role.id
  policy = data.aws_iam_policy_document.prisma_cloud_read_only.json
}

data "aws_iam_policy_document" "prisma_cloud_remediation" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:ModifyImageAttribute",
      "ec2:RevokeSecurityGroupIngress",
      "iam:UpdateAccountPasswordPolicy",
      "rds:ModifyDBSnapshotAttribute",
      "s3:PutBucketAcl"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "prisma_cloud_remediation" {
  count  = var.read_write ? 1 : 0
  name   = "PrismaCloud-IAM-Remediation-Policy"
  role   = aws_iam_role.prisma_cloud_role.id
  policy = data.aws_iam_policy_document.prisma_cloud_remediation.json
}

output "role_arn" {
  description = "The ARN of the IAM role created for Prisma Cloud integration"
  value       = aws_iam_role.prisma_cloud_role.arn
}

output "external_id" {
  description = "The generated external ID required for the Prisma Cloud integration trust relationship"
  value       = random_string.external_id.result
  sensitive   = true
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  type        = string
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  type        = string
  description = "CIDR block for the private subnet"
  default     = "10.0.2.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "development_be_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "development-be-vpc"
  }
}

resource "aws_subnet" "development_be_public_subnet" {
  vpc_id                  = aws_vpc.development_be_vpc.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "development-be-public-subnet"
  }
}

resource "aws_subnet" "development_be_private_subnet" {
  vpc_id                  = aws_vpc.development_be_vpc.id
  cidr_block              = var.private_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "development-be-private-subnet"
  }
}

resource "aws_internet_gateway" "development_be_ig" {
  vpc_id = aws_vpc.development_be_vpc.id

  tags = {
    Name = "development-be-ig"
  }
}

resource "aws_route_table" "development_be_public_rt" {
  vpc_id = aws_vpc.development_be_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.development_be_ig.id
  }

  tags = {
    Name = "development-be-public-rt"
  }
}

resource "aws_route_table_association" "development_be_public_rt_assoc" {
  subnet_id      = aws_subnet.development_be_public_subnet.id
  route_table_id = aws_route_table.development_be_public_rt.id
}

resource "aws_security_group" "http_access" {
  name        = "http_access"
  description = "Security group for HTTP and SSH access"
  vpc_id      = aws_vpc.development_be_vpc.id

  ingress {
    description = "Allow SSH from within the VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.development_be_vpc.cidr_block]
  }

  ingress {
    description = "Allow HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Restrict outbound traffic to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.development_be_vpc.cidr_block]
  }

  tags = {
    Name = "development-be-sg"
  }
}

output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.development_be_vpc.id
}

output "public_subnet_id" {
  description = "The ID of the public subnet"
  value       = aws_subnet.development_be_public_subnet.id
}

output "private_subnet_id" {
  description = "The ID of the private subnet"
  value       = aws_subnet.development_be_private_subnet.id
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "create" {
  description = "Whether to create the SNS topic and associated resources."
  type        = bool
  default     = true
}

variable "name" {
  description = "The name of the SNS topic. If omitted, Terraform will assign a random name."
  type        = string
  default     = null
}

variable "use_name_prefix" {
  description = "Determines whether name is used as a prefix. If true, name must be 38 characters or less for FIFO topics or 256 characters or less for non-FIFO topics."
  type        = bool
  default     = false
}

variable "fifo_topic" {
  description = "Boolean indicating whether or not to create a FIFO (first-in-first-out) topic."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO topics."
  type        = bool
  default     = false
}

variable "display_name" {
  description = "The display name for the SNS topic."
  type        = string
  default     = null
}

variable "delivery_policy" {
  description = "The SNS delivery policy as a JSON formatted string."
  type        = string
  default     = null
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SNS or a custom CMK."
  type        = string
  default     = null
}

variable "signature_version" {
  description = "The signature version corresponds to the hashing algorithm used while creating the signature of the notifications, message attributes, or messages to be sent."
  type        = number
  default     = null
}

variable "tracing_config" {
  description = "Tracing mode of an Amazon SNS topic. Valid values: PassThrough, Active."
  type        = string
  default     = null
}

variable "feedback_failure_role_arns" {
  description = "Map of IAM role ARNs used for protocol delivery failure feedback."
  type        = map(string)
  default     = {}
}

variable "feedback_success_role_arns" {
  description = "Map of IAM role ARNs used for protocol delivery success feedback."
  type        = map(string)
  default     = {}
}

variable "feedback_success_sample_rates" {
  description = "Map of sample rates for protocol delivery success feedback (0-100)."
  type        = map(number)
  default     = {}
}

variable "create_topic_policy" {
  description = "Determines whether an SNS topic policy is created."
  type        = bool
  default     = true
}

variable "enable_default_topic_policy" {
  description = "Specifies whether to enable the default topic policy statement granting access to the account owner."
  type        = bool
  default     = true
}

variable "source_topic_policy_documents" {
  description = "List of IAM policy documents that are merged into the topic policy."
  type        = list(string)
  default     = []
}

variable "override_topic_policy_documents" {
  description = "List of IAM policy documents that take precedence over the generated topic policy."
  type        = list(string)
  default     = []
}

variable "topic_policy_statements" {
  description = "A map of IAM policy statement definitions to append to the topic policy document."
  type        = any
  default     = {}
}

variable "topic_policy" {
  description = "An externally provided IAM policy document in JSON format. Used when create_topic_policy is false."
  type        = string
  default     = null
}

variable "create_subscription" {
  description = "Whether to create subscriptions defined in var.subscriptions."
  type        = bool
  default     = true
}

variable "subscriptions" {
  description = "A map of subscription definitions to create on the topic."
  type = map(object({
    protocol                        = string
    endpoint                        = string
    confirmation_timeout_in_minutes = optional(number)
    delivery_policy                 = optional(string)
    endpoint_auto_confirms          = optional(bool)
    filter_policy                   = optional(string)
    filter_policy_scope             = optional(string)
    raw_message_delivery            = optional(bool)
    redrive_policy                  = optional(string)
    subscription_role_arn           = optional(string)
  }))
  default = {}
}

variable "data_protection_policy" {
  description = "The data protection policy JSON string to apply to the SNS topic. Only supported for standard (non-FIFO) topics."
  type        = string
  default     = null
}

variable "tags" {
  description = "A map of tags to assign to all resources."
  type        = map(string)
  default     = {}
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  topic_name        = var.use_name_prefix ? null : (var.fifo_topic && var.name != null && !endswith(var.name, ".fifo") ? "${var.name}.fifo" : var.name)
  topic_name_prefix = var.use_name_prefix ? var.name : null
  signature_ver     = var.fifo_topic ? null : var.signature_version
}

resource "aws_sns_topic" "this" {
  count = var.create ? 1 : 0

  name        = local.topic_name
  name_prefix = local.topic_name_prefix

  display_name                = var.display_name
  delivery_policy             = var.delivery_policy
  kms_master_key_id           = var.kms_master_key_id
  signature_version           = local.signature_ver
  tracing_config              = var.tracing_config
  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.fifo_topic ? var.content_based_deduplication : false

  application_failure_feedback_role_arn    = lookup(var.feedback_failure_role_arns, "application", null)
  application_success_feedback_role_arn    = lookup(var.feedback_success_role_arns, "application", null)
  application_success_feedback_sample_rate = lookup(var.feedback_success_sample_rates, "application", null)

  firehose_failure_feedback_role_arn    = lookup(var.feedback_failure_role_arns, "firehose", null)
  firehose_success_feedback_role_arn    = lookup(var.feedback_success_role_arns, "firehose", null)
  firehose_success_feedback_sample_rate = lookup(var.feedback_success_sample_rates, "firehose", null)

  http_failure_feedback_role_arn    = lookup(var.feedback_failure_role_arns, "http", null)
  http_success_feedback_role_arn    = lookup(var.feedback_success_role_arns, "http", null)
  http_success_feedback_sample_rate = lookup(var.feedback_success_sample_rates, "http", null)

  lambda_failure_feedback_role_arn    = lookup(var.feedback_failure_role_arns, "lambda", null)
  lambda_success_feedback_role_arn    = lookup(var.feedback_success_role_arns, "lambda", null)
  lambda_success_feedback_sample_rate = lookup(var.feedback_success_sample_rates, "lambda", null)

  sqs_failure_feedback_role_arn    = lookup(var.feedback_failure_role_arns, "sqs", null)
  sqs_success_feedback_role_arn    = lookup(var.feedback_success_role_arns, "sqs", null)
  sqs_success_feedback_sample_rate = lookup(var.feedback_success_sample_rates, "sqs", null)

  tags = var.tags
}

data "aws_iam_policy_document" "topic_policy" {
  count = var.create && var.create_topic_policy ? 1 : 0

  source_policy_documents   = var.source_topic_policy_documents
  override_policy_documents = var.override_topic_policy_documents

  dynamic "statement" {
    for_each = var.enable_default_topic_policy ? [1] : []

    content {
      sid    = "__default_statement_ID"
      effect = "Allow"

      actions = [
        "sns:GetTopicAttributes",
        "sns:SetTopicAttributes",
        "sns:AddPermission",
        "sns:RemovePermission",
        "sns:DeleteTopic",
        "sns:Subscribe",
        "sns:ListSubscriptionsByTopic",
        "sns:Publish"
      ]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      resources = [aws_sns_topic.this[0].arn]

      condition {
        test     = "StringEquals"
        variable = "aws:SourceOwner"
        values   = [data.aws_caller_identity.current.account_id]
      }
    }
  }

  dynamic "statement" {
    for_each = var.topic_policy_statements

    content {
      sid           = lookup(statement.value, "sid", null)
      effect        = lookup(statement.value, "effect", "Allow")
      actions       = lookup(statement.value, "actions", null)
      not_actions   = lookup(statement.value, "not_actions", null)
      resources     = lookup(statement.value, "resources", [aws_sns_topic.this[0].arn])
      not_resources = lookup(statement.value, "not_resources", null)

      dynamic "principals" {
        for_each = lookup(statement.value, "principals", [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = lookup(statement.value, "not_principals", [])

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = lookup(statement.value, "conditions", [])

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  count = var.create && (var.create_topic_policy || var.topic_policy != null) ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = var.create_topic_policy ? data.aws_iam_policy_document.topic_policy[0].json : var.topic_policy
}

resource "aws_sns_topic_subscription" "this" {
  for_each = var.create && var.create_subscription ? var.subscriptions : {}

  topic_arn                       = aws_sns_topic.this[0].arn
  protocol                        = each.value.protocol
  endpoint                        = each.value.endpoint
  confirmation_timeout_in_minutes = each.value.confirmation_timeout_in_minutes
  delivery_policy                 = each.value.delivery_policy
  endpoint_auto_confirms          = each.value.endpoint_auto_confirms
  filter_policy                   = each.value.filter_policy
  filter_policy_scope             = each.value.filter_policy_scope
  raw_message_delivery            = each.value.raw_message_delivery
  redrive_policy                  = each.value.redrive_policy
  subscription_role_arn           = each.value.subscription_role_arn
}

resource "aws_sns_topic_data_protection_policy" "this" {
  count = var.create && var.data_protection_policy != null && !var.fifo_topic ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = var.data_protection_policy
}

output "topic_arn" {
  description = "ARN of the SNS topic."
  value       = try(aws_sns_topic.this[0].arn, null)
}

output "topic_id" {
  description = "The ID of the SNS topic."
  value       = try(aws_sns_topic.this[0].id, null)
}

output "topic_name" {
  description = "The name of the SNS topic."
  value       = try(aws_sns_topic.this[0].name, null)
}

output "topic_owner" {
  description = "The AWS account ID of the SNS topic owner."
  value       = try(aws_sns_topic.this[0].owner, null)
}

output "topic_beginning_archive_time" {
  description = "The oldest timestamp at which a FIFO topic's messages are preserved."
  value       = try(aws_sns_topic.this[0].beginning_archive_time, null)
}

output "subscriptions" {
  description = "Map of topic subscriptions and their attributes."
  value       = aws_sns_topic_subscription.this
}

output "subscription_arns" {
  description = "Map of subscription keys to their respective ARNs."
  value       = { for k, v in aws_sns_topic_subscription.this : k => v.arn }
}

output "data_protection_policy_id" {
  description = "The ID of the SNS data protection policy."
  value       = try(aws_sns_topic_data_protection_policy.this[0].id, null)
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "bucket_name" {
  description = "Name of the bucket. If omitted or null, defaults to 'corebucket-' followed by a 4-byte random hex string."
  type        = string
  default     = null
}

variable "prefix" {
  description = "When true, appends an additional random suffix to the bucket name."
  type        = bool
  default     = false
}

variable "request_payer" {
  description = "Specifies who pays for the download and request fees. Can be either 'BucketOwner' or 'Requester'."
  type        = string
  default     = "BucketOwner"
}

variable "encryption" {
  description = "Whether to enable SSE-KMS encryption for the bucket."
  type        = bool
  default     = true
}

variable "kms_key" {
  description = "KMS Key ARN for encryption. If empty and encryption is true, a customer-managed KMS key is created."
  type        = string
  default     = ""
}

variable "versioning" {
  description = "Whether to enable S3 bucket versioning."
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Whether MFA delete is enabled for bucket versioning."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Whether all objects should be deleted from the bucket when destroyed."
  type        = bool
  default     = false
}

variable "tags" {
  description = "A mapping of tags to assign to the bucket and managed resources."
  type        = map(string)
  default     = {}
}

variable "policy" {
  description = "A valid JSON bucket policy string to apply to the S3 bucket."
  type        = string
  default     = null
}

variable "acceleration_status" {
  description = "Transfer acceleration status ('Enabled' or 'Suspended')."
  type        = string
  default     = null
}

variable "logging" {
  description = "Map containing target_bucket and optional target_prefix for access logging."
  type = object({
    target_bucket = string
    target_prefix = optional(string, "")
  })
  default = null
}

variable "website" {
  description = "Map containing static website hosting configuration."
  type = object({
    index_document           = optional(string)
    error_document           = optional(string)
    redirect_all_requests_to = optional(string)
    routing_rules            = optional(string)
  })
  default = null
}

variable "cors_rules" {
  description = "List of CORS rule objects."
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle management rules."
  type = list(object({
    id      = string
    enabled = bool
    prefix  = optional(string)
    tags    = optional(map(string))
    abort_incomplete_multipart_upload = optional(object({
      days_after_initiation = number
    }))
    expiration = optional(object({
      date                         = optional(string)
      days                         = optional(number)
      expired_object_delete_marker = optional(bool)
    }))
    transitions = optional(list(object({
      date          = optional(string)
      days          = optional(number)
      storage_class = string
    })), [])
    noncurrent_version_expiration = optional(object({
      noncurrent_days = number
    }))
    noncurrent_version_transitions = optional(list(object({
      noncurrent_days = number
      storage_class   = string
    })), [])
  }))
  default = []
}

variable "object_lock_configuration" {
  description = "Map containing object lock configuration parameters."
  type = object({
    rule = optional(object({
      default_retention = object({
        mode  = string
        days  = optional(number)
        years = optional(number)
      })
    }))
  })
  default = null
}

variable "replication_role" {
  description = "ARN of an existing IAM role to use for replication. If omitted and replication_rules are supplied, an IAM role is generated."
  type        = string
  default     = ""
}

variable "replication_rules" {
  description = "List of replication rules for Cross-Region Replication."
  type = list(object({
    id       = optional(string)
    priority = optional(number)
    status   = string
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    delete_marker_replication = optional(object({
      status = string
    }))
    destination = object({
      bucket             = string
      storage_class      = optional(string)
      replica_kms_key_id = optional(string)
      account            = optional(string)
      metrics = optional(object({
        status  = string
        minutes = optional(number, 15)
      }))
      replication_time = optional(object({
        status  = string
        minutes = optional(number, 15)
      }))
    })
    source_selection_criteria = optional(object({
      sse_kms_encrypted_objects = optional(object({
        status = string
      }))
    }))
  }))
  default = []
}

# -----------------------------------------------------------------------------
# Dynamic Naming
# -----------------------------------------------------------------------------
resource "random_id" "bucket_hex" {
  byte_length = 4
}

resource "random_string" "suffix" {
  count   = var.prefix ? 1 : 0
  length  = 6
  special = false
  upper   = false
}

locals {
  base_bucket_name     = var.bucket_name != null ? var.bucket_name : "corebucket-${random_id.bucket_hex.hex}"
  resolved_bucket_name = var.prefix ? "${local.base_bucket_name}-${random_string.suffix[0].result}" : local.base_bucket_name

  create_kms_key = var.encryption && var.kms_key == ""
  effective_kms_key_arn = local.create_kms_key ? aws_kms_key.s3_kms_key[0].arn : (
    var.kms_key != "" ? var.kms_key : null
  )

  has_replication = length(var.replication_rules) > 0
  has_object_lock = var.object_lock_configuration != null
  # S3 replication and object lock require bucket versioning to be enabled
  effective_versioning_enabled = var.versioning || local.has_replication || local.has_object_lock
}

# -----------------------------------------------------------------------------
# Customer-Managed KMS Key (when encryption is true and kms_key is not supplied)
# -----------------------------------------------------------------------------
resource "aws_kms_key" "s3_kms_key" {
  count                   = local.create_kms_key ? 1 : 0
  description             = "Customer-managed KMS key for S3 bucket ${local.resolved_bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3ServiceUse"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(
    var.tags,
    {
      "Name" = "kms-${local.resolved_bucket_name}"
    }
  )
}

resource "aws_kms_alias" "s3_kms_key_alias" {
  count         = local.create_kms_key ? 1 : 0
  name          = "alias/s3-${local.resolved_bucket_name}"
  target_key_id = aws_kms_key.s3_kms_key[0].key_id
}

# -----------------------------------------------------------------------------
# Primary S3 Bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "main" {
  bucket              = local.resolved_bucket_name
  object_lock_enabled = local.has_object_lock
  force_destroy       = var.force_destroy
  tags                = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Bucket Request Payment
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_request_payment_configuration" "main" {
  bucket = aws_s3_bucket.main.id
  payer  = var.request_payer
}

# -----------------------------------------------------------------------------
# Public Access Block (Always Fully Blocked)
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# Server-Side Encryption
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  count  = var.encryption ? 1 : 0
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.effective_kms_key_arn
    }
    bucket_key_enabled = true
  }
}

# -----------------------------------------------------------------------------
# Bucket Versioning
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status     = local.effective_versioning_enabled ? "Enabled" : "Suspended"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

# -----------------------------------------------------------------------------
# Object Lock Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_object_lock_configuration" "main" {
  count  = local.has_object_lock ? 1 : 0
  bucket = aws_s3_bucket.main.id

  depends_on = [aws_s3_bucket_versioning.main]

  dynamic "rule" {
    for_each = var.object_lock_configuration.rule != null ? [var.object_lock_configuration.rule] : []
    content {
      default_retention {
        mode  = rule.value.default_retention.mode
        days  = rule.value.default_retention.days
        years = rule.value.default_retention.years
      }
    }
  }
}

# -----------------------------------------------------------------------------
# Static Website Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_website_configuration" "main" {
  count  = var.website != null ? 1 : 0
  bucket = aws_s3_bucket.main.id

  dynamic "index_document" {
    for_each = var.website.index_document != null ? [var.website.index_document] : []
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = var.website.error_document != null ? [var.website.error_document] : []
    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = var.website.redirect_all_requests_to != null ? [var.website.redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value
    }
  }

  routing_rules = var.website.routing_rules
}

# -----------------------------------------------------------------------------
# Bucket Access Logging
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_logging" "main" {
  count  = var.logging != null ? 1 : 0
  bucket = aws_s3_bucket.main.id

  target_bucket = var.logging.target_bucket
  target_prefix = var.logging.target_prefix
}

# -----------------------------------------------------------------------------
# CORS Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "main" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.main.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      id              = cors_rule.value.id
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# -----------------------------------------------------------------------------
# Lifecycle Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "main" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.main.id

  depends_on = [aws_s3_bucket_versioning.main]

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = (rule.value.prefix != null || rule.value.tags != null) ? [1] : []
        content {
          dynamic "and" {
            for_each = (rule.value.prefix != null && rule.value.tags != null && length(rule.value.tags) > 0) ? [1] : []
            content {
              prefix = rule.value.prefix
              tags   = rule.value.tags
            }
          }

          prefix = (rule.value.tags == null || length(rule.value.tags) == 0) ? rule.value.prefix : null

          dynamic "tag" {
            for_each = (rule.value.prefix == null && rule.value.tags != null && length(rule.value.tags) == 1) ? rule.value.tags : {}
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          date                         = expiration.value.date
          days                         = expiration.value.days
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions != null ? rule.value.transitions : []
        content {
          date          = transition.value.date
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.noncurrent_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions != null ? rule.value.noncurrent_version_transitions : []
        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }
}

# -----------------------------------------------------------------------------
# Transfer Acceleration Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_accelerate_configuration" "main" {
  count  = var.acceleration_status != null ? 1 : 0
  bucket = aws_s3_bucket.main.id
  status = var.acceleration_status
}

# -----------------------------------------------------------------------------
# Bucket Policy
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_policy" "main" {
  count  = var.policy != null ? 1 : 0
  bucket = aws_s3_bucket.main.id
  policy = var.policy

  depends_on = [aws_s3_bucket_public_access_block.main]
}

# -----------------------------------------------------------------------------
# Replication IAM Role & Policy (Generated when replication_rules exist and no role supplied)
# -----------------------------------------------------------------------------
locals {
  create_replication_role = local.has_replication && var.replication_role == ""
}

resource "aws_iam_role" "replication" {
  count = local.create_replication_role ? 1 : 0
  name  = "CoreS3ReplicationRole_${local.resolved_bucket_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "replication" {
  count = local.create_replication_role ? 1 : 0
  name  = "CoreS3ReplicationPolicy_${local.resolved_bucket_name}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.main.arn
      },
      {
        Sid    = "SourceObjectsPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = "${aws_s3_bucket.main.arn}/*"
      },
      {
        Sid    = "DestinationBucketPermissions"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = [
          for rule in var.replication_rules : "${rule.destination.bucket}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  count      = local.create_replication_role ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

# -----------------------------------------------------------------------------
# Replication Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_replication_configuration" "main" {
  count  = local.has_replication ? 1 : 0
  bucket = aws_s3_bucket.main.id
  role   = var.replication_role != "" ? var.replication_role : aws_iam_role.replication[0].arn

  depends_on = [
    aws_s3_bucket_versioning.main,
    aws_iam_role_policy_attachment.replication
  ]

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id       = rule.value.id
      priority = rule.value.priority
      status   = rule.value.status

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = filter.value.prefix

          dynamic "tag" {
            for_each = filter.value.tags != null ? filter.value.tags : {}
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "delete_marker_replication" {
        for_each = rule.value.delete_marker_replication != null ? [rule.value.delete_marker_replication] : []
        content {
          status = delete_marker_replication.value.status
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = rule.value.destination.storage_class
        account       = rule.value.destination.account

        dynamic "encryption_configuration" {
          for_each = rule.value.destination.replica_kms_key_id != null ? [rule.value.destination.replica_kms_key_id] : []
          content {
            replica_kms_key_id = encryption_configuration.value
          }
        }

        dynamic "metrics" {
          for_each = rule.value.destination.metrics != null ? [rule.value.destination.metrics] : []
          content {
            status = metrics.value.status
            dynamic "event_threshold" {
              for_each = metrics.value.minutes != null ? [metrics.value.minutes] : []
              content {
                minutes = event_threshold.value
              }
            }
          }
        }

        dynamic "replication_time" {
          for_each = rule.value.destination.replication_time != null ? [rule.value.destination.replication_time] : []
          content {
            status = replication_time.value.status
            dynamic "time" {
              for_each = replication_time.value.minutes != null ? [replication_time.value.minutes] : []
              content {
                minutes = time.value
              }
            }
          }
        }
      }

      dynamic "source_selection_criteria" {
        for_each = rule.value.source_selection_criteria != null ? [rule.value.source_selection_criteria] : []
        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = source_selection_criteria.value.sse_kms_encrypted_objects != null ? [source_selection_criteria.value.sse_kms_encrypted_objects] : []
            content {
              status = sse_kms_encrypted_objects.value.status
            }
          }
        }
      }
    }
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "s3_bucket_id" {
  description = "The name of the bucket."
  value       = aws_s3_bucket.main.id
}

output "s3_bucket_arn" {
  description = "The ARN of the bucket."
  value       = aws_s3_bucket.main.arn
}

output "s3_bucket_bucket_domain_name" {
  description = "The bucket domain name."
  value       = aws_s3_bucket.main.bucket_domain_name
}

output "s3_bucket_bucket_regional_domain_name" {
  description = "The bucket region-specific domain name."
  value       = aws_s3_bucket.main.bucket_regional_domain_name
}

output "s3_kms_key_arn" {
  description = "The ARN of the KMS key used to encrypt the bucket."
  value       = local.effective_kms_key_arn
}

output "replication_role_arn" {
  description = "The ARN of the IAM role used for S3 replication."
  value       = local.create_replication_role ? aws_iam_role.replication[0].arn : var.replication_role
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "random_suffix" {
  type        = bool
  default     = true
  description = "Whether to append a random alphanumeric suffix to resource names."
}

variable "random_suffix_length" {
  type        = number
  default     = 4
  description = "Length of the random suffix to generate."
}

variable "bucket_name_prefix" {
  type        = string
  default     = "zedcloud"
  description = "Prefix for the S3 bucket name."
}

variable "iam_user_name_prefix" {
  type        = string
  default     = "zedcloud-s3-user"
  description = "Prefix for the IAM user name."
}

variable "iam_policy_name_prefix" {
  type        = string
  default     = "zedcloud-s3-policy"
  description = "Prefix for the IAM policy name."
}

variable "upload_image" {
  type        = bool
  default     = false
  description = "Whether to upload the image file to the S3 bucket."
}

variable "image_filename" {
  type        = string
  default     = "my-file.qcow2"
  description = "The local image filename to upload."
}

variable "create_folder" {
  type        = bool
  default     = true
  description = "Whether to prefix the uploaded file with a folder path in S3."
}

variable "s3_folder" {
  type        = string
  default     = "my-folder"
  description = "The S3 folder prefix to use if create_folder is true."
}

variable "create_iam_user" {
  type        = bool
  default     = true
  description = "Whether to create the IAM user, access key, and policy attachment."
}

resource "random_string" "suffix" {
  count   = var.random_suffix ? 1 : 0
  length  = var.random_suffix_length
  special = false
  upper   = false
}

locals {
  suffix             = var.random_suffix && length(random_string.suffix) > 0 ? "-${random_string.suffix[0].result}" : ""
  bucket_name        = "${var.bucket_name_prefix}${local.suffix}"
  iam_user_name      = "${var.iam_user_name_prefix}${local.suffix}"
  iam_policy_name    = "${var.iam_policy_name_prefix}${local.suffix}"
  s3_key             = var.create_folder ? "${var.s3_folder}/${var.image_filename}" : var.image_filename
}

resource "aws_kms_key" "s3_key" {
  description             = "KMS CMK for S3 datastore server-side encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = {
    Name = "${local.bucket_name}-kms-key"
  }
}

resource "aws_kms_alias" "s3_key_alias" {
  name          = "alias/${local.bucket_name}-key"
  target_key_id = aws_kms_key.s3_key.key_id
}

resource "aws_s3_bucket" "datastore" {
  bucket        = local.bucket_name
  force_destroy = true

  tags = {
    Name = local.bucket_name
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "datastore_encryption" {
  bucket = aws_s3_bucket.datastore.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "datastore_public_access_block" {
  bucket = aws_s3_bucket.datastore.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_object" "image" {
  count      = var.upload_image ? 1 : 0
  bucket     = aws_s3_bucket.datastore.id
  key        = local.s3_key
  source     = "${path.module}/${var.image_filename}"
  kms_key_id = aws_kms_key.s3_key.arn

  depends_on = [
    aws_s3_bucket_server_side_encryption_configuration.datastore_encryption,
    aws_s3_bucket_public_access_block.datastore_public_access_block
  ]
}

resource "aws_iam_user" "s3_reader" {
  count         = var.create_iam_user ? 1 : 0
  name          = local.iam_user_name
  path          = "/"
  force_destroy = true

  tags = {
    Name = local.iam_user_name
  }
}

resource "aws_iam_access_key" "s3_reader_key" {
  count  = var.create_iam_user ? 1 : 0
  user   = aws_iam_user.s3_reader[0].name
  status = "Active"
}

data "aws_iam_policy_document" "s3_reader_policy_doc" {
  count = var.create_iam_user ? 1 : 0

  statement {
    sid       = "AllowListBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.datastore.arn]
  }

  statement {
    sid       = "AllowGetObject"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.datastore.arn}/*"]
  }

  statement {
    sid       = "AllowKmsDecrypt"
    effect    = "Allow"
    actions   = [
      "kms:Decrypt",
      "kms:GenerateDataKey"
    ]
    resources = [aws_kms_key.s3_key.arn]
  }
}

resource "aws_iam_policy" "s3_reader_policy" {
  count       = var.create_iam_user ? 1 : 0
  name        = local.iam_policy_name
  description = "Scoped read-only IAM policy for image datastore access"
  policy      = data.aws_iam_policy_document.s3_reader_policy_doc[0].json

  tags = {
    Name = local.iam_policy_name
  }
}

resource "aws_iam_user_policy_attachment" "s3_reader_attachment" {
  count      = var.create_iam_user ? 1 : 0
  user       = aws_iam_user.s3_reader[0].name
  policy_arn = aws_iam_policy.s3_reader_policy[0].arn
}

output "s3_bucket_name" {
  value       = aws_s3_bucket.datastore.id
  description = "The name of the created S3 bucket."
}

output "s3_bucket_arn" {
  value       = aws_s3_bucket.datastore.arn
  description = "The ARN of the created S3 bucket."
}

output "kms_key_arn" {
  value       = aws_kms_key.s3_key.arn
  description = "The ARN of the KMS key used for bucket encryption."
}

output "iam_user_name" {
  value       = var.create_iam_user ? aws_iam_user.s3_reader[0].name : null
  description = "The IAM user name if created."
}

output "iam_access_key_id" {
  value       = var.create_iam_user ? aws_iam_access_key.s3_reader_key[0].id : null
  description = "The access key ID for the IAM user."
}

output "iam_access_key_secret" {
  value       = var.create_iam_user ? aws_iam_access_key.s3_reader_key[0].secret : null
  sensitive   = true
  description = "The secret access key for the IAM user."
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "config" {
  type        = string
  description = "Path to the pipeline definition YAML configuration file"
  default     = "pipelines.yaml"
}

variable "raw_config" {
  type        = string
  description = "Optional inline YAML content. Used if file(var.config) is not present on disk."
  default     = <<-EOT
    codestar_connections:
      github-connection:
        provider_type: "GitHub"
      bitbucket-connection:
        provider_type: "Bitbucket"
    pipelines:
      sample-service-pipeline:
        artifact_bucket_suffix: "sample-artifacts"
        cache_bucket_suffix: "sample-cache"
        stages:
          - name: "Source"
            actions:
              - name: "AppCodeCommitSource"
                category: "Source"
                owner: "AWS"
                provider: "CodeCommit"
                version: "1"
                output_artifacts: ["source_output"]
                configuration:
                  RepositoryName: "sample-repo"
                  BranchName: "main"
                  PollForSourceChanges: "false"
          - name: "Approval"
            actions:
              - name: "PreBuildApproval"
                category: "Approval"
                owner: "AWS"
                provider: "Manual"
                version: "1"
                configuration:
                  CustomData: "Please verify and approve the build deployment."
          - name: "Build"
            actions:
              - name: "BuildApp"
                category: "Build"
                owner: "AWS"
                provider: "CodeBuild"
                version: "1"
                input_artifacts: ["source_output"]
                output_artifacts: ["build_output"]
                configuration:
                  ProjectName: "sample-service-build"
        triggers:
          - name: "branch-trigger"
            type: "codecommit_branch"
            repository_name: "sample-repo"
            branch_name: "main"
          - name: "tag-trigger"
            type: "codecommit_tag"
            repository_name: "sample-repo"
            tag_pattern: "v*"
          - name: "nightly-schedule"
            type: "schedule"
            schedule_expression: "cron(0 0 * * ? *)"
  EOT
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  parsed_config = fileexists(var.config) ? yamldecode(file(var.config)) : yamldecode(var.raw_config)

  pipelines            = try(local.parsed_config.pipelines, {})
  codestar_connections = try(local.parsed_config.codestar_connections, {})

  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name

  # Flatten triggers across all pipelines for EventBridge provisioning
  pipeline_triggers = flatten([
    for pipe_key, pipe_val in local.pipelines : [
      for trig_idx, trig_val in try(pipe_val.triggers, []) : {
        key                 = "${pipe_key}-${trig_val.name}"
        pipeline_key        = pipe_key
        name                = trig_val.name
        type                = trig_val.type
        schedule_expression = try(trig_val.schedule_expression, null)
        repository_name     = try(trig_val.repository_name, null)
        branch_name         = try(trig_val.branch_name, null)
        tag_pattern         = try(trig_val.tag_pattern, null)
        custom_pattern      = try(trig_val.custom_pattern, null)
      }
    ]
  ])

  triggers_map = { for t in local.pipeline_triggers : t.key => t }
}

# KMS Customer Managed Key dedicated to pipeline artifact encryption
resource "aws_kms_key" "pipeline_key" {
  description             = "KMS Key for CodePipeline artifact encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootIAMAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCodePipelineAndServices"
        Effect = "Allow"
        Principal = {
          Service = [
            "codepipeline.amazonaws.com",
            "codebuild.amazonaws.com",
            "events.amazonaws.com"
          ]
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "pipeline_key_alias" {
  name          = "alias/terraforest-codepipeline-artifacts"
  target_key_id = aws_kms_key.pipeline_key.key_id
}

# S3 Artifact Buckets per Pipeline
resource "aws_s3_bucket" "artifacts" {
  for_each = local.pipelines

  bucket = "${lower(each.key)}-artifacts-${local.account_id}-${local.region}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  for_each = aws_s3_bucket.artifacts

  bucket = each.value.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  for_each = aws_s3_bucket.artifacts

  bucket = each.value.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  for_each = aws_s3_bucket.artifacts

  bucket = each.value.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.pipeline_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# S3 Build Cache Buckets per Pipeline
resource "aws_s3_bucket" "cache" {
  for_each = local.pipelines

  bucket = "${lower(each.key)}-cache-${local.account_id}-${local.region}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "cache" {
  for_each = aws_s3_bucket.cache

  bucket = each.value.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "cache" {
  for_each = aws_s3_bucket.cache

  bucket = each.value.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cache" {
  for_each = aws_s3_bucket.cache

  bucket = each.value.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.pipeline_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# CodeStar Connections for Bitbucket, GitHub, GitHub Enterprise Server
resource "aws_codestarconnections_connection" "connections" {
  for_each = local.codestar_connections

  name          = each.key
  provider_type = each.value.provider_type
}

# Optional Default CodePipeline Execution IAM Role under path "/terraforest/"
resource "aws_iam_role" "codepipeline_default" {
  name = "terraforest-codepipeline-default-role"
  path = "/terraforest/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codepipeline.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "codepipeline_default" {
  name = "terraforest-codepipeline-default-policy"
  role = aws_iam_role.codepipeline_default.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeCommitAccess"
        Effect = "Allow"
        Action = [
          "codecommit:GetBranch",
          "codecommit:GetCommit",
          "codecommit:UploadArchive",
          "codecommit:GetUploadArchiveStatus",
          "codecommit:CancelUploadArchive"
        ]
        Resource = "arn:aws:codecommit:${local.region}:${local.account_id}:*"
      },
      {
        Sid    = "S3ArtifactBucketsAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:GetBucketVersioning",
          "s3:PutObject",
          "s3:PutObjectAcl"
        ]
        Resource = flatten([
          for bucket in aws_s3_bucket.artifacts : [
            bucket.arn,
            "${bucket.arn}/*"
          ]
        ])
      },
      {
        Sid    = "CodeBuildAccess"
        Effect = "Allow"
        Action = [
          "codebuild:BatchGetBuilds",
          "codebuild:StartBuild"
        ]
        Resource = "arn:aws:codebuild:${local.region}:${local.account_id}:project/*"
      },
      {
        Sid    = "ECRMetadataAccess"
        Effect = "Allow"
        Action = [
          "ecr:DescribeImages",
          "ecr:DescribeRepositories",
          "ecr:GetAuthorizationToken",
          "ecr:BatchGetImage"
        ]
        Resource = "*"
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = [
          "kms:DescribeKey",
          "kms:GenerateDataKey*",
          "kms:Encrypt",
          "kms:ReEncrypt*",
          "kms:Decrypt"
        ]
        Resource = aws_kms_key.pipeline_key.arn
      },
      {
        Sid    = "LambdaAccess"
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction"
        ]
        Resource = "arn:aws:lambda:${local.region}:${local.account_id}:function:*"
      },
      {
        Sid    = "CodeStarUseAccess"
        Effect = "Allow"
        Action = [
          "codestar-connections:UseConnection"
        ]
        Resource = [for conn in aws_codestarconnections_connection.connections : conn.arn]
      }
    ]
  })
}

# Dynamic CodePipeline Resources
resource "aws_codepipeline" "pipelines" {
  for_each = local.pipelines

  name     = each.key
  role_arn = aws_iam_role.codepipeline_default.arn

  artifact_store {
    location = aws_s3_bucket.artifacts[each.key].bucket
    type     = "S3"

    encryption_key {
      id   = aws_kms_key.pipeline_key.arn
      type = "KMS"
    }
  }

  dynamic "stage" {
    for_each = try(each.value.stages, [])
    content {
      name = stage.value.name

      dynamic "action" {
        for_each = try(stage.value.actions, [])
        content {
          name             = action.value.name
          category         = action.value.category
          owner            = action.value.owner
          provider         = action.value.provider
          version          = action.value.version
          run_order        = try(action.value.run_order, 1)
          input_artifacts  = try(action.value.input_artifacts, [])
          output_artifacts = try(action.value.output_artifacts, [])
          configuration    = try(action.value.configuration, {})
        }
      }
    }
  }
}

# EventBridge Trigger IAM Roles prefixed with "terrabits-"
resource "aws_iam_role" "eventbridge_triggers" {
  for_each = local.pipelines

  name = "terrabits-${each.key}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Least-Privilege IAM Policy for EventBridge restricted solely to target pipeline ARN
resource "aws_iam_role_policy" "eventbridge_triggers" {
  for_each = local.pipelines

  name = "terrabits-${each.key}-trigger-policy"
  role = aws_iam_role.eventbridge_triggers[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "StartCodePipelineExecution"
        Effect   = "Allow"
        Action   = "codepipeline:StartPipelineExecution"
        Resource = aws_codepipeline.pipelines[each.key].arn
      }
    ]
  })
}

# EventBridge Event Rules
resource "aws_cloudwatch_event_rule" "rules" {
  for_each = local.triggers_map

  name        = "terrabits-${each.value.pipeline_key}-${each.value.name}"
  description = "Trigger rule for pipeline ${each.value.pipeline_key}"

  schedule_expression = each.value.type == "schedule" ? each.value.schedule_expression : null

  event_pattern = each.value.type == "codecommit_branch" ? jsonencode({
    source      = ["aws.codecommit"]
    detail-type = ["CodeCommit Repository State Change"]
    resources   = ["arn:aws:codecommit:${local.region}:${local.account_id}:${each.value.repository_name}"]
    detail = {
      event         = ["referenceCreated", "referenceUpdated"]
      referenceType = ["branch"]
      referenceName = [each.value.branch_name]
    }
    }) : each.value.type == "codecommit_tag" ? jsonencode({
      source      = ["aws.codecommit"]
      detail-type = ["CodeCommit Repository State Change"]
      resources   = ["arn:aws:codecommit:${local.region}:${local.account_id}:${each.value.repository_name}"]
      detail = {
        event         = ["referenceCreated"]
        referenceType = ["tag"]
        referenceName = [each.value.tag_pattern]
      }
      }) : each.value.type == "custom" ? jsonencode(each.value.custom_pattern) : null
}

# EventBridge Targets
resource "aws_cloudwatch_event_target" "targets" {
  for_each = local.triggers_map

  rule     = aws_cloudwatch_event_rule.rules[each.key].name
  arn      = aws_codepipeline.pipelines[each.value.pipeline_key].arn
  role_arn = aws_iam_role.eventbridge_triggers[each.value.pipeline_key].arn
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "namespace" {
  type        = string
  default     = "eg"
  description = "Namespace, which could be your organization name or abbreviation, e.g. 'eg' or 'cp'"
}

variable "environment" {
  type        = string
  default     = "ue1"
  description = "Environment, e.g. 'prod', 'staging', 'dev', 'pre-prod', 'UAT'"
}

variable "stage" {
  type        = string
  default     = "prod"
  description = "Stage, e.g. 'prod', 'staging', 'dev', or 'test'"
}

variable "name" {
  type        = string
  default     = "patch-manager"
  description = "Solution name, e.g. 'patch-manager' or 'app'"
}

variable "attributes" {
  type        = list(string)
  default     = []
  description = "Additional attributes (e.g. `1`)"
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Additional tags (e.g. `map('BusinessUnit','XYZ')`"
}

variable "scan_schedule" {
  type        = string
  default     = "cron(0 0 18 ? * WED *)"
  description = "Cron schedule expression for the scan maintenance window"
}

variable "install_schedule" {
  type        = string
  default     = "cron(0 0 21 ? * WED *)"
  description = "Cron schedule expression for the install maintenance window"
}

variable "duration" {
  type        = number
  default     = 3
  description = "The duration of the maintenance window in hours"
}

variable "cutoff" {
  type        = number
  default     = 1
  description = "The number of hours before the end of the maintenance window that Systems Manager stops scheduling new tasks"
}

variable "max_concurrency" {
  type        = string
  default     = "20"
  description = "The maximum number of targets allowed to run this task in parallel"
}

variable "max_errors" {
  type        = string
  default     = "50"
  description = "The maximum number of errors allowed before this task stops being scheduled"
}

variable "scan_patch_group" {
  type        = string
  default     = "TOSCAN"
  description = "Patch Group tag value targeted by the scan maintenance window"
}

variable "install_patch_group" {
  type        = string
  default     = "TOPATCH"
  description = "Patch Group tag value targeted by the install maintenance window"
}

variable "reboot_option" {
  type        = string
  default     = "RebootIfNeeded"
  description = "Reboot option for the install task (RebootIfNeeded, NoReboot)"
}

variable "s3_log_prefix" {
  type        = string
  default     = "scanning"
  description = "S3 bucket prefix for storing Systems Manager Run Command output logs"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  label_parts = compact([
    var.namespace,
    var.environment,
    var.stage,
    var.name,
    join("-", var.attributes)
  ])
  id = lower(join("-", local.label_parts))

  default_tags = merge(
    var.tags,
    {
      "Namespace"   = var.namespace
      "Environment" = var.environment
      "Stage"       = var.stage
      "Name"        = local.id
    }
  )

  scan_id    = "${local.id}-scan"
  install_id = "${local.id}-install"
}

resource "aws_s3_bucket" "patch_log_bucket" {
  bucket        = "${local.id}-logs-${data.aws_caller_identity.current.account_id}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }

  tags = local.default_tags
}

resource "aws_s3_bucket_versioning" "patch_log_bucket" {
  bucket = aws_s3_bucket.patch_log_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "patch_log_bucket" {
  bucket = aws_s3_bucket.patch_log_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "patch_log_bucket" {
  bucket = aws_s3_bucket.patch_log_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "patch_log_bucket" {
  bucket = aws_s3_bucket.patch_log_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowAccountReadWrite"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.patch_log_bucket.arn,
          "${aws_s3_bucket.patch_log_bucket.arn}/*"
        ]
      },
      {
        Sid       = "AllowSSMServicePutObject"
        Effect    = "Allow"
        Principal = {
          Service = "ssm.amazonaws.com"
        }
        Action = "s3:PutObject"
        Resource = "${aws_s3_bucket.patch_log_bucket.arn}/*"
      }
    ]
  })
}

resource "aws_iam_role" "ssm_maintenance_window" {
  name = "${local.id}-mw-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ssm.amazonaws.com"
        }
      }
    ]
  })

  tags = local.default_tags
}

resource "aws_iam_role_policy_attachment" "ssm_mw_service_role" {
  role       = aws_iam_role.ssm_maintenance_window.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonSSMMaintenanceWindowRole"
}

resource "aws_iam_policy" "ssm_mw_s3_logging" {
  name        = "${local.id}-s3-logging-policy"
  description = "Grant SSM Maintenance Window tasks access to write logs to S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3LogBucketAccess"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetDocument*",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.patch_log_bucket.arn,
          "${aws_s3_bucket.patch_log_bucket.arn}/*"
        ]
      }
    ]
  })

  tags = local.default_tags
}

resource "aws_iam_role_policy_attachment" "ssm_mw_s3_logging" {
  role       = aws_iam_role.ssm_maintenance_window.name
  policy_arn = aws_iam_policy.ssm_mw_s3_logging.arn
}

resource "aws_ssm_patch_baseline" "amazon_linux_2" {
  name             = "${local.id}-al2-baseline"
  description      = "Amazon Linux 2 patch baseline with auto-approval for Security, Bugfix, and Recommended patches"
  operating_system = "AMAZON_LINUX_2"

  approved_patches_compliance_level = "HIGH"
  approved_patches_enable_non_security = true

  approval_rule {
    approve_after_days = 7
    compliance_level   = "HIGH"
    enable_non_security = true

    patch_filter {
      key    = "PRODUCT"
      values = ["AmazonLinux2"]
    }

    patch_filter {
      key    = "CLASSIFICATION"
      values = ["Security", "Bugfix", "Recommended"]
    }

    patch_filter {
      key    = "SEVERITY"
      values = ["Critical", "Important", "Medium"]
    }
  }

  tags = local.default_tags
}

resource "aws_ssm_patch_group" "scan_patch_group" {
  baseline_id = aws_ssm_patch_baseline.amazon_linux_2.id
  patch_group = var.scan_patch_group
}

resource "aws_ssm_patch_group" "install_patch_group" {
  baseline_id = aws_ssm_patch_baseline.amazon_linux_2.id
  patch_group = var.install_patch_group
}

resource "aws_ssm_maintenance_window" "scan" {
  name                       = local.scan_id
  schedule                   = var.scan_schedule
  duration                   = var.duration
  cutoff                     = var.cutoff
  allow_unassociated_targets = false

  tags = merge(local.default_tags, { "Name" = local.scan_id })
}

resource "aws_ssm_maintenance_window_target" "scan" {
  window_id     = aws_ssm_maintenance_window.scan.id
  name          = "${local.scan_id}-target"
  description   = "Target instances tagged with Patch Group=${var.scan_patch_group}"
  resource_type = "INSTANCE"

  targets {
    key    = "tag:Patch Group"
    values = [var.scan_patch_group]
  }
}

resource "aws_ssm_maintenance_window_task" "scan" {
  window_id        = aws_ssm_maintenance_window.scan.id
  name             = "${local.scan_id}-task"
  description      = "Run AWS-RunPatchBaseline Scan operation"
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  priority         = 1
  service_role_arn = aws_iam_role.ssm_maintenance_window.arn
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.scan.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      output_s3_bucket     = aws_s3_bucket.patch_log_bucket.id
      output_s3_key_prefix = var.s3_log_prefix

      parameter {
        name   = "Operation"
        values = ["Scan"]
      }

      parameter {
        name   = "RebootOption"
        values = ["NoReboot"]
      }
    }
  }
}

resource "aws_ssm_maintenance_window" "install" {
  name                       = local.install_id
  schedule                   = var.install_schedule
  duration                   = var.duration
  cutoff                     = var.cutoff
  allow_unassociated_targets = false

  tags = merge(local.default_tags, { "Name" = local.install_id })
}

resource "aws_ssm_maintenance_window_target" "install" {
  window_id     = aws_ssm_maintenance_window.install.id
  name          = "${local.install_id}-target"
  description   = "Target instances tagged with Patch Group=${var.install_patch_group}"
  resource_type = "INSTANCE"

  targets {
    key    = "tag:Patch Group"
    values = [var.install_patch_group]
  }
}

resource "aws_ssm_maintenance_window_task" "install" {
  window_id        = aws_ssm_maintenance_window.install.id
  name             = "${local.install_id}-task"
  description      = "Run AWS-RunPatchBaseline Install operation"
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  priority         = 1
  service_role_arn = aws_iam_role.ssm_maintenance_window.arn
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.install.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      output_s3_bucket     = aws_s3_bucket.patch_log_bucket.id
      output_s3_key_prefix = "install"

      parameter {
        name   = "Operation"
        values = ["Install"]
      }

      parameter {
        name   = "RebootOption"
        values = [var.reboot_option]
      }
    }
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "alarm_email_recipients" {
  description = "List of email addresses to receive sensitive management activity alerts"
  type        = list(string)
  default     = ["security-alerts@example.com"]
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------
locals {
  account_id       = data.aws_caller_identity.current.account_id
  partition        = data.aws_partition.current.partition
  region           = data.aws_region.current.name
  metric_namespace = "management_activities"
  log_group_name   = "cloudtrail_to_cloudwatch_logs"
  bucket_name      = "cloudtrail-monitor-management-event-logs-${local.account_id}"

  metric_alarms = {
    security_group_changes = {
      metric_name = "SecurityGroupChanges"
      filter_pattern = "{ ($.eventName = AuthorizeSecurityGroupIngress) || ($.eventName = AuthorizeSecurityGroupEgress) || ($.eventName = RevokeSecurityGroupIngress) || ($.eventName = RevokeSecurityGroupEgress) || ($.eventName = CreateSecurityGroup) || ($.eventName = DeleteSecurityGroup) }"
      description    = "Alarm fired when AWS EC2 security group changes occur."
    }
    iam_user_changes = {
      metric_name = "IAMUserChanges"
      filter_pattern = "{ ($.eventName = CreateUser) || ($.eventName = DeleteUser) }"
      description    = "Alarm fired when an IAM user is created or deleted."
    }
    failed_console_logins = {
      metric_name = "FailedConsoleLogins"
      filter_pattern = "{ ($.eventName = ConsoleLogin) && ($.errorMessage = \"Failed authentication\") }"
      description    = "Alarm fired when a console login attempt fails."
    }
    iam_attached_policy_changes = {
      metric_name = "IAMGroupRoleUserPolicyChanges"
      filter_pattern = "{ ($.eventName = AttachUserPolicy) || ($.eventName = DetachUserPolicy) || ($.eventName = AttachGroupPolicy) || ($.eventName = DetachGroupPolicy) || ($.eventName = AttachRolePolicy) || ($.eventName = DetachRolePolicy) || ($.eventName = PutUserPolicy) || ($.eventName = DeleteUserPolicy) || ($.eventName = PutGroupPolicy) || ($.eventName = DeleteGroupPolicy) || ($.eventName = PutRolePolicy) || ($.eventName = DeleteRolePolicy) }"
      description    = "Alarm fired when policies attached to IAM groups, roles, or users are modified."
    }
    iam_policy_changes = {
      metric_name = "IAMPolicyChanges"
      filter_pattern = "{ ($.eventName = CreatePolicy) || ($.eventName = DeletePolicy) || ($.eventName = CreatePolicyVersion) || ($.eventName = DeletePolicyVersion) || ($.eventName = SetDefaultPolicyVersion) }"
      description    = "Alarm fired when IAM managed policies or policy versions are created, modified, or deleted."
    }
    user_added_to_group = {
      metric_name = "UserAddedToGroup"
      filter_pattern = "{ ($.eventName = AddUserToGroup) }"
      description    = "Alarm fired when an IAM user is added to an IAM group."
    }
    iam_role_changes = {
      metric_name = "IAMRoleChanges"
      filter_pattern = "{ ($.eventName = CreateRole) || ($.eventName = DeleteRole) }"
      description    = "Alarm fired when an IAM role is created or deleted."
    }
  }
}

# -----------------------------------------------------------------------------
# KMS: CloudTrail, S3, and CloudWatch Logs
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "cloudtrail_kms_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowCloudTrailEncryptLogs"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/monitor_account_activities"]
    }
  }

  statement {
    sid    = "AllowCloudWatchLogsEncryption"
    effect = "Allow"
    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:${local.log_group_name}"]
    }
  }

  statement {
    sid    = "AllowS3AndCloudTrailDecrypt"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:ReEncryptFrom"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/monitor_account_activities"]
    }
  }
}

resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key for CloudTrail trail, S3 bucket, and CloudWatch log group encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.cloudtrail_kms_policy.json
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/cloudtrail-monitor-key"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

# -----------------------------------------------------------------------------
# S3: CloudTrail Logs Bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = local.bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cloudtrail.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "cloudtrail_s3_policy" {
  statement {
    sid     = "EnforceTLSRequestsOnly"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.cloudtrail_logs.arn,
      "${aws_s3_bucket.cloudtrail_logs.arn}/*"
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid       = "AWSCloudTrailAclCheck"
    effect    = "Allow"
    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail_logs.arn]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/monitor_account_activities"]
    }
  }

  statement {
    sid       = "AWSCloudTrailWrite"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail_logs.arn}/AWSLogs/${local.account_id}/*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/monitor_account_activities"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket     = aws_s3_bucket.cloudtrail_logs.id
  policy     = data.aws_iam_policy_document.cloudtrail_s3_policy.json
  depends_on = [aws_s3_bucket_public_access_block.cloudtrail_logs]
}

# -----------------------------------------------------------------------------
# CloudWatch Logs Group & IAM Role for CloudTrail
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = local.log_group_name
  retention_in_days = 365
  kms_key_id        = aws_kms_key.cloudtrail.arn
}

data "aws_iam_policy_document" "cloudtrail_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "cloudtrail_to_cloudwatch" {
  name               = "cloudtrail-to-cloudwatch-logs-role"
  assume_role_policy = data.aws_iam_policy_document.cloudtrail_assume_role.json
}

data "aws_iam_policy_document" "cloudtrail_to_cloudwatch_policy" {
  statement {
    sid    = "CloudTrailPutLogEvents"
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = [
      "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
    ]
  }
}

resource "aws_iam_role_policy" "cloudtrail_to_cloudwatch" {
  name   = "cloudtrail-log-delivery-policy"
  role   = aws_iam_role.cloudtrail_to_cloudwatch.id
  policy = data.aws_iam_policy_document.cloudtrail_to_cloudwatch_policy.json
}

# -----------------------------------------------------------------------------
# CloudTrail Trail
# -----------------------------------------------------------------------------
resource "aws_cloudtrail" "monitor_account_activities" {
  name                          = "monitor_account_activities"
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_to_cloudwatch.arn

  advanced_event_selector {
    name = "LogManagementEventsExcludingKmsAndRdsData"

    field_selector {
      field  = "readOnly"
      equals = ["false", "true"]
    }

    field_selector {
      field  = "managementEvent"
      equals = ["true"]
    }

    field_selector {
      field      = "eventSource"
      not_equals = [
        "kms.amazonaws.com",
        "rdsdata.amazonaws.com"
      ]
    }
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail_logs,
    aws_iam_role_policy.cloudtrail_to_cloudwatch
  ]
}

# -----------------------------------------------------------------------------
# KMS: SNS Topic Encryption
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "sns_kms_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowCloudWatchAlarmsToPublish"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "sns" {
  description             = "Customer managed KMS key for sensitive management activity alerts SNS topic"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.sns_kms_policy.json
}

resource "aws_kms_alias" "sns" {
  name          = "alias/sns-management-updates-key"
  target_key_id = aws_kms_key.sns.key_id
}

# -----------------------------------------------------------------------------
# SNS Topic & Subscriptions
# -----------------------------------------------------------------------------
resource "aws_sns_topic" "management_updates" {
  name              = "management-updates"
  kms_master_key_id = aws_kms_key.sns.id
}

data "aws_iam_policy_document" "sns_topic_policy" {
  statement {
    sid     = "EnforceTLSRequestsOnly"
    effect  = "Deny"
    actions = ["sns:Publish"]
    resources = [
      aws_sns_topic.management_updates.arn
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "AllowCloudWatchAlarmsToPublishToSNS"
    effect = "Allow"
    actions = [
      "sns:Publish"
    ]
    resources = [
      aws_sns_topic.management_updates.arn
    ]

    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:cloudwatch:${local.region}:${local.account_id}:alarm:*"]
    }
  }
}

resource "aws_sns_topic_policy" "management_updates" {
  arn    = aws_sns_topic.management_updates.arn
  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

resource "aws_sns_topic_subscription" "email_recipients" {
  for_each  = toset(var.alarm_email_recipients)
  topic_arn = aws_sns_topic.management_updates.arn
  protocol  = "email"
  endpoint  = each.value
}

# -----------------------------------------------------------------------------
# CloudWatch Metric Filters and Alarms
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_log_metric_filter" "management_activities" {
  for_each       = local.metric_alarms
  name           = each.key
  pattern        = each.value.filter_pattern
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name

  metric_transformation {
    name          = each.value.metric_name
    namespace     = local.metric_namespace
    value         = "1"
    default_value = "0"
  }
}

resource "aws_cloudwatch_metric_alarm" "management_activities" {
  for_each            = local.metric_alarms
  alarm_name          = "${each.key}-alarm"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = each.value.metric_name
  namespace           = local.metric_namespace
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_description   = each.value.description
  alarm_actions       = [aws_sns_topic.management_updates.arn]
  treat_missing_data  = "notBreaching"

  depends_on = [
    aws_cloudwatch_log_metric_filter.management_activities
  ]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# Input Variables
# ------------------------------------------------------------------------------

variable "rule_name_prefix" {
  type        = string
  description = "Optional prefix to prepend to AWS Config resource names."
  default     = ""
}

variable "days_to_expiration" {
  type        = number
  description = "The number of days before certificate expiration to trigger a non-compliant status."
  default     = 14
}

# ------------------------------------------------------------------------------
# Local Values
# ------------------------------------------------------------------------------

locals {
  name_prefix = var.rule_name_prefix != "" ? "${var.rule_name_prefix}-" : ""
  rule_name   = "${local.name_prefix}acm-certificate-expiration-check"
  bucket_name = "${local.name_prefix}config-delivery-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
}

# ------------------------------------------------------------------------------
# S3 Bucket for AWS Config Delivery
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "config" {
  bucket        = local.bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = local.bucket_name
  }
}

resource "aws_s3_bucket_public_access_block" "config" {
  bucket = aws_s3_bucket.config.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "config" {
  bucket = aws_s3_bucket.config.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config" {
  bucket = aws_s3_bucket.config.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_policy" "config" {
  bucket = aws_s3_bucket.config.id
  policy = data.aws_iam_policy_document.config_s3_policy.json
}

data "aws_iam_policy_document" "config_s3_policy" {
  statement {
    sid    = "AWSConfigBucketPermissionsCheck"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.config.arn]
  }

  statement {
    sid    = "AWSConfigBucketExistenceCheck"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.config.arn]
  }

  statement {
    sid    = "AWSConfigBucketDelivery"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.config.arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/Config/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

# ------------------------------------------------------------------------------
# IAM Role for AWS Config
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "config_assume_role" {
  statement {
    sid     = "AWSConfigAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "config" {
  name               = "${local.name_prefix}aws-config-role"
  assume_role_policy = data.aws_iam_policy_document.config_assume_role.json

  tags = {
    Name = "${local.name_prefix}aws-config-role"
  }
}

resource "aws_iam_role_policy_attachment" "config_role" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWS_ConfigRole"
}

# ------------------------------------------------------------------------------
# AWS Config Recorder & Delivery Channel
# ------------------------------------------------------------------------------

resource "aws_config_configuration_recorder" "main" {
  name     = "${local.name_prefix}recorder"
  role_arn = aws_iam_role.config.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "main" {
  name           = "${local.name_prefix}delivery-channel"
  s3_bucket_name = aws_s3_bucket.config.id

  depends_on = [
    aws_s3_bucket_policy.config,
    aws_config_configuration_recorder.main
  ]
}

resource "aws_config_configuration_recorder_status" "main" {
  name       = aws_config_configuration_recorder.main.name
  is_enabled = true

  depends_on = [aws_config_delivery_channel.main]
}

# ------------------------------------------------------------------------------
# AWS Config Managed Rule: ACM Certificate Expiration Check
# ------------------------------------------------------------------------------

resource "aws_config_config_rule" "acm_certificate_expiration_check" {
  name        = local.rule_name
  description = "Checks whether ACM certificates in the account are close to expiring."

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  scope {
    compliance_resource_types = ["AWS::ACM::Certificate"]
  }

  input_parameters = jsonencode({
    daysToExpiration = var.days_to_expiration
  })

  depends_on = [aws_config_configuration_recorder_status.main]

  tags = {
    Name = local.rule_name
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

resource "aws_cognito_user_pool" "pool" {
  name                     = "fiap-hackathon-cognito-pool"
  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]
  mfa_configuration        = "OFF"

  password_policy {
    minimum_length                   = 8
    require_lowercase                = false
    require_numbers                  = false
    require_symbols                  = false
    require_uppercase                = false
    temporary_password_validity_days = 7
  }

  schema {
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    name                     = "name"
    required                 = true

    string_attribute_constraints {
      min_length = "1"
      max_length = "2048"
    }
  }
}

resource "aws_cognito_user_pool_client" "client" {
  name            = "cognito-pool-client"
  user_pool_id    = aws_cognito_user_pool.pool.id
  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_PASSWORD_AUTH"
  ]
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
