}

locals {
  tenant_id = "221ca1d3-b3f2-4346-8abc-88f802495c7d"
  client_id = "c8b9cf86-e2b4-4428-b356-14313412a4d1"
  issuer    = "https://sts.windows.net/221ca1d3-b3f2-4346-8abc-88f802495c7d/"
  aud_key   = "sts.windows.net/221ca1d3-b3f2-4346-8abc-88f802495c7d/:aud"
