terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Variables and Data Sources
# -----------------------------------------------------------------------------
variable "environment" {
  type        = string
  description = "Deployment environment name for remote state resources."
  default     = "dev"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id           = data.aws_caller_identity.current.account_id
  partition            = data.aws_partition.current.partition
  frontend_bucket_name = "s3-frontend-nft-maker-v2-${local.account_id}"
  state_bucket_name    = "near-frontend-${var.environment}-terraform-state-${local.account_id}"
}

# -----------------------------------------------------------------------------
# Frontend KMS Key and Alias
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_frontend_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid       = "AllowCloudFrontServicePrincipalAccess"
    effect    = "Allow"
    actions   = ["kms:Decrypt", "kms:GenerateDataKey*", "kms:DescribeKey"]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "frontend" {
  description             = "Dedicated KMS key for frontend S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_frontend_policy.json

  tags = {
    Name        = "kms-frontend-nft-maker-v2"
    Environment = var.environment
  }
}

resource "aws_kms_alias" "frontend" {
  name          = "alias/frontend-nft-maker-v2"
  target_key_id = aws_kms_key.frontend.key_id
}

# -----------------------------------------------------------------------------
# Frontend S3 Bucket & Configurations
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "frontend" {
  bucket = local.frontend_bucket_name

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name        = local.frontend_bucket_name
    Environment = var.environment
  }
}

resource "aws_s3_bucket_public_access_block" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.frontend.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_website_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  index_document {
    suffix = "index.html"
  }

  error_document {
    key = "index.html"
  }
}

resource "aws_s3_bucket_cors_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT", "POST", "DELETE"]
    allowed_origins = ["*"]
    expose_headers  = []
    max_age_seconds = 3000
  }
}

# -----------------------------------------------------------------------------
# CloudFront Origin Access Identity and S3 Bucket Policy
# -----------------------------------------------------------------------------
resource "aws_cloudfront_origin_access_identity" "frontend" {
  comment = "Origin Access Identity for ${local.frontend_bucket_name}"
}

data "aws_iam_policy_document" "frontend_bucket_policy" {
  statement {
    sid       = "AllowCloudFrontOAIReadAndList"
    effect    = "Allow"
    actions   = ["s3:GetObject", "s3:ListBucket"]
    resources = [
      aws_s3_bucket.frontend.arn,
      "${aws_s3_bucket.frontend.arn}/*"
    ]

    principals {
      type        = "AWS"
      identifiers = [aws_cloudfront_origin_access_identity.frontend.iam_arn]
    }
  }
}

resource "aws_s3_bucket_policy" "frontend" {
  bucket     = aws_s3_bucket.frontend.id
  policy     = data.aws_iam_policy_document.frontend_bucket_policy.json
  depends_on = [aws_s3_bucket_public_access_block.frontend]
}

# -----------------------------------------------------------------------------
# CloudFront-scoped WAFv2 Web ACL
# -----------------------------------------------------------------------------
resource "aws_wafv2_web_acl" "frontend" {
  name        = "frontend-waf-web-acl"
  description = "CloudFront WAF protecting static frontend distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 10

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "frontend-waf-common-rules"
      sampled_requests_enabled   = true
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "frontend-waf-web-acl-metrics"
    sampled_requests_enabled   = true
  }

  tags = {
    Name        = "frontend-waf-web-acl"
    Environment = var.environment
  }
}

# -----------------------------------------------------------------------------
# CloudFront Distribution
# -----------------------------------------------------------------------------
resource "aws_cloudfront_distribution" "frontend" {
  enabled             = true
  is_ipv6_enabled     = true
  comment             = "CloudFront distribution for ${local.frontend_bucket_name}"
  default_root_object = "index.html"
  price_class         = "PriceClass_200"
  web_acl_id          = aws_wafv2_web_acl.frontend.arn

  origin {
    domain_name = aws_s3_bucket.frontend.bucket_regional_domain_name
    origin_id   = "S3-${aws_s3_bucket.frontend.id}"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.frontend.cloudfront_access_identity_path
    }
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3-${aws_s3_bucket.frontend.id}"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
    compress               = true
  }

  ordered_cache_behavior {
    path_pattern     = "/content/immutable/*"
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3-${aws_s3_bucket.frontend.id}"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 86400
    default_ttl            = 2592000
    max_ttl                = 31536000
    compress               = true
  }

  ordered_cache_behavior {
    path_pattern     = "/content/*"
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3-${aws_s3_bucket.frontend.id}"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 3600
    default_ttl            = 86400
    max_ttl                = 604800
    compress               = true
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  tags = {
    Name        = "frontend-cloudfront-distribution"
    Environment = var.environment
  }
}

# -----------------------------------------------------------------------------
# Terraform Remote State Backend: KMS Key and Alias
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_state_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }
}

resource "aws_kms_key" "state" {
  description             = "Dedicated KMS key for remote state backend S3 bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_state_policy.json

  tags = {
    Name        = "kms-remote-state"
    Environment = var.environment
  }
}

resource "aws_kms_alias" "state" {
  name          = "alias/near-frontend-${var.environment}-terraform-state"
  target_key_id = aws_kms_key.state.key_id
}

# -----------------------------------------------------------------------------
# Terraform Remote State Backend: S3 Bucket & Configurations
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "state" {
  bucket = local.state_bucket_name

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name        = local.state_bucket_name
    Environment = var.environment
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

# -----------------------------------------------------------------------------
# Terraform Remote State Backend: DynamoDB Table
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "state_locks" {
  name           = "near-frontend-terraform-state"
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name        = "near-frontend-terraform-state"
    Environment = var.environment
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "enable_database_subnets" {
  type        = bool
  default     = false
  description = "Controls whether to create isolated database subnets and RDS subnet group."
}

variable "enable_elasticache_subnets" {
  type        = bool
  default     = false
  description = "Controls whether to create isolated ElastiCache subnets and subnet group."
}

variable "enable_internal_subnets" {
  type        = bool
  default     = false
  description = "Controls whether to create isolated internal non-routable subnets."
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# Local Values
# -----------------------------------------------------------------------------
locals {
  name_prefix  = "stackx-network"
  cluster_name = "stackx"

  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  # Primary network CIDR assignments
  public_ipv4_cidrs  = ["10.1.192.0/22", "10.1.196.0/22", "10.1.200.0/22"]
  private_ipv4_cidrs = ["10.1.0.0/18", "10.1.64.0/18", "10.1.128.0/18"]

  # Optional network tier CIDR assignments (within 10.1.208.0/20, 10.1.224.0/20, 10.1.240.0/20)
  database_ipv4_cidrs    = ["10.1.208.0/24", "10.1.209.0/24", "10.1.210.0/24"]
  elasticache_ipv4_cidrs = ["10.1.212.0/24", "10.1.213.0/24", "10.1.214.0/24"]
  internal_ipv4_cidrs    = ["10.1.216.0/22", "10.1.220.0/22", "10.1.224.0/22"]

  # IPv6 subnet index offsets (from /56 assigned to VPC using /64 subnets)
  # Public: 0..2, Private: 16..18, Database: 32..34, ElastiCache: 48..50, Internal: 64..66
  public_ipv6_indices      = [0, 1, 2]
  private_ipv6_indices     = [16, 17, 18]
  database_ipv6_indices    = [32, 33, 34]
  elasticache_ipv6_indices = [48, 49, 50]
  internal_ipv6_indices    = [64, 65, 66]

  common_tags = {
    Environment = "production"
    ManagedBy   = "terraform"
    Project     = "stackx"
  }
}

# -----------------------------------------------------------------------------
# VPC and Gateways
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block                       = "10.1.0.0/16"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = merge(
    local.common_tags,
    {
      Name                                        = "${local.name_prefix}-vpc"
      "kubernetes.io/cluster/${local.cluster_name}" = "shared"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-igw"
    }
  )
}

resource "aws_egress_only_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-eigw"
    }
  )
}

# -----------------------------------------------------------------------------
# Public Subnets and Route Table
# -----------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = 3

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.public_ipv4_cidrs[count.index]
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, local.public_ipv6_indices[count.index])
  availability_zone               = local.azs[count.index]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = false

  tags = merge(
    local.common_tags,
    {
      Name                                        = "${local.name_prefix}-public-${local.azs[count.index]}"
      "kubernetes.io/role/elb"                    = "1"
      "kubernetes.io/cluster/${local.cluster_name}" = "shared"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-public-rt"
    }
  )
}

resource "aws_route" "public_ipv4_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6_internet" {
  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Elastic IPs and NAT Gateways (One per AZ)
# -----------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count = 3

  domain = "vpc"

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-eip-${local.azs[count.index]}"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count = 3

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-nat-${local.azs[count.index]}"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

# -----------------------------------------------------------------------------
# Private Subnets and Route Tables
# -----------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count = 3

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.private_ipv4_cidrs[count.index]
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, local.private_ipv6_indices[count.index])
  availability_zone               = local.azs[count.index]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = false

  tags = merge(
    local.common_tags,
    {
      Name                                        = "${local.name_prefix}-private-${local.azs[count.index]}"
      "kubernetes.io/role/internal-elb"           = "1"
      "kubernetes.io/cluster/${local.cluster_name}" = "shared"
      "karpenter.sh/discovery"                    = local.cluster_name
    }
  )
}

resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-private-rt-${local.azs[count.index]}"
    }
  )
}

resource "aws_route" "private_ipv4_nat" {
  count = 3

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

resource "aws_route" "private_ipv6_egress" {
  count = 3

  route_table_id              = aws_route_table.private[count.index].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.main.id
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# -----------------------------------------------------------------------------
# Gateway VPC Endpoint for S3
# -----------------------------------------------------------------------------
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-s3-endpoint"
    }
  )
}

# -----------------------------------------------------------------------------
# Optional Tier: Database Subnets & DB Subnet Group
# -----------------------------------------------------------------------------
resource "aws_subnet" "database" {
  count = var.enable_database_subnets ? 3 : 0

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.database_ipv4_cidrs[count.index]
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, local.database_ipv6_indices[count.index])
  availability_zone               = local.azs[count.index]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-database-${local.azs[count.index]}"
    }
  )
}

resource "aws_route_table" "database" {
  count = var.enable_database_subnets ? 3 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-database-rt-${local.azs[count.index]}"
    }
  )
}

resource "aws_route_table_association" "database" {
  count = var.enable_database_subnets ? 3 : 0

  subnet_id      = aws_subnet.database[count.index].id
  route_table_id = aws_route_table.database[count.index].id
}

resource "aws_db_subnet_group" "main" {
  count = var.enable_database_subnets ? 1 : 0

  name        = "${local.name_prefix}-db-subnet-group"
  description = "Database subnet group for ${local.name_prefix}"
  subnet_ids  = aws_subnet.database[*].id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-db-subnet-group"
    }
  )
}

# -----------------------------------------------------------------------------
# Optional Tier: ElastiCache Subnets & Subnet Group
# -----------------------------------------------------------------------------
resource "aws_subnet" "elasticache" {
  count = var.enable_elasticache_subnets ? 3 : 0

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.elasticache_ipv4_cidrs[count.index]
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, local.elasticache_ipv6_indices[count.index])
  availability_zone               = local.azs[count.index]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-elasticache-${local.azs[count.index]}"
    }
  )
}

resource "aws_route_table" "elasticache" {
  count = var.enable_elasticache_subnets ? 3 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-elasticache-rt-${local.azs[count.index]}"
    }
  )
}

resource "aws_route_table_association" "elasticache" {
  count = var.enable_elasticache_subnets ? 3 : 0

  subnet_id      = aws_subnet.elasticache[count.index].id
  route_table_id = aws_route_table.elasticache[count.index].id
}

resource "aws_elasticache_subnet_group" "main" {
  count = var.enable_elasticache_subnets ? 1 : 0

  name        = "${local.name_prefix}-cache-subnet-group"
  description = "ElastiCache subnet group for ${local.name_prefix}"
  subnet_ids  = aws_subnet.elasticache[*].id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-cache-subnet-group"
    }
  )
}

# -----------------------------------------------------------------------------
# Optional Tier: Internal Subnets (Completely Isolated)
# -----------------------------------------------------------------------------
resource "aws_subnet" "internal" {
  count = var.enable_internal_subnets ? 3 : 0

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.internal_ipv4_cidrs[count.index]
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, local.internal_ipv6_indices[count.index])
  availability_zone               = local.azs[count.index]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-internal-${local.azs[count.index]}"
    }
  )
}

resource "aws_route_table" "internal" {
  count = var.enable_internal_subnets ? 3 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-internal-rt-${local.azs[count.index]}"
    }
  )
}

resource "aws_route_table_association" "internal" {
  count = var.enable_internal_subnets ? 3 : 0

  subnet_id      = aws_subnet.internal[count.index].id
  route_table_id = aws_route_table.internal[count.index].id
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  value       = aws_vpc.main.id
  description = "ID of the dual-stack VPC."
}

output "vpc_ipv6_cidr_block" {
  value       = aws_vpc.main.ipv6_cidr_block
  description = "The Amazon-assigned IPv6 CIDR block associated with the VPC."
}

output "public_subnet_ids" {
  value       = aws_subnet.public[*].id
  description = "List of IDs of the public subnets."
}

output "private_subnet_ids" {
  value       = aws_subnet.private[*].id
  description = "List of IDs of the private subnets."
}

output "nat_gateway_ids" {
  value       = aws_nat_gateway.main[*].id
  description = "List of IDs of the NAT Gateways."
}

output "nat_gateway_public_ips" {
  value       = aws_eip.nat[*].public_ip
  description = "List of Elastic IP addresses assigned to NAT Gateways."
}

output "s3_endpoint_id" {
  value       = aws_vpc_endpoint.s3.id
  description = "ID of the S3 Gateway VPC Endpoint."
}

output "database_subnet_ids" {
  value       = aws_subnet.database[*].id
  description = "List of IDs of the database subnets (empty if tier is disabled)."
}

output "db_subnet_group_name" {
  value       = try(aws_db_subnet_group.main[0].name, null)
  description = "Name of the RDS DB Subnet Group (null if tier is disabled)."
}

output "elasticache_subnet_ids" {
  value       = aws_subnet.elasticache[*].id
  description = "List of IDs of the ElastiCache subnets (empty if tier is disabled)."
}

output "elasticache_subnet_group_name" {
  value       = try(aws_elasticache_subnet_group.main[0].name, null)
  description = "Name of the ElastiCache Subnet Group (null if tier is disabled)."
}

output "internal_subnet_ids" {
  value       = aws_subnet.internal[*].id
  description = "List of IDs of the internal subnets (empty if tier is disabled)."
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name

  bucket_names = {
    artefacts = "benchmark-glue-artefacts-${local.account_id}"
    staging   = "benchmark-datalake-staging-${local.account_id}"
    bronze    = "benchmark-datalake-bronze-${local.account_id}"
    silver    = "benchmark-datalake-silver-${local.account_id}"
    gold      = "benchmark-datalake-gold-${local.account_id}"
    logs      = "benchmark-datalake-logs-${local.account_id}"
  }
}

# -----------------------------------------------------------------------------
# KMS Customer Managed Key
# -----------------------------------------------------------------------------

resource "aws_kms_key" "data_lake" {
  description             = "Customer-managed KMS key for weather data lake encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "data-lake-kms-key-policy"
    Statement = [
      {
        Sid    = "EnableRootManagement"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3AndGlueAndAthenaAccess"
        Effect = "Allow"
        Principal = {
          Service = [
            "s3.amazonaws.com",
            "glue.amazonaws.com",
            "athena.amazonaws.com"
          ]
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:Encrypt",
          "kms:GenerateDataKey*",
          "kms:ReEncrypt*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "data_lake" {
  name          = "alias/benchmark-datalake-key"
  target_key_id = aws_kms_key.data_lake.key_id
}

# -----------------------------------------------------------------------------
# S3 Buckets & Configurations
# -----------------------------------------------------------------------------

# Artefacts Bucket
resource "aws_s3_bucket" "artefacts" {
  bucket = local.bucket_names.artefacts

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artefacts" {
  bucket = aws_s3_bucket.artefacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artefacts" {
  bucket = aws_s3_bucket.artefacts.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.data_lake.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "artefacts" {
  bucket = aws_s3_bucket.artefacts.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Staging Bucket
resource "aws_s3_bucket" "staging" {
  bucket = local.bucket_names.staging

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "staging" {
  bucket = aws_s3_bucket.staging.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "staging" {
  bucket = aws_s3_bucket.staging.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.data_lake.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# Bronze Bucket
resource "aws_s3_bucket" "bronze" {
  bucket = local.bucket_names.bronze

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "bronze" {
  bucket = aws_s3_bucket.bronze.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "bronze" {
  bucket = aws_s3_bucket.bronze.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.data_lake.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "bronze" {
  bucket = aws_s3_bucket.bronze.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Silver Bucket
resource "aws_s3_bucket" "silver" {
  bucket = local.bucket_names.silver

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "silver" {
  bucket = aws_s3_bucket.silver.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "silver" {
  bucket = aws_s3_bucket.silver.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.data_lake.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "silver" {
  bucket = aws_s3_bucket.silver.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Gold Bucket
resource "aws_s3_bucket" "gold" {
  bucket = local.bucket_names.gold

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "gold" {
  bucket = aws_s3_bucket.gold.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "gold" {
  bucket = aws_s3_bucket.gold.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.data_lake.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "gold" {
  bucket = aws_s3_bucket.gold.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Logs Bucket
resource "aws_s3_bucket" "logs" {
  bucket = local.bucket_names.logs

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.data_lake.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# -----------------------------------------------------------------------------
# Upload Glue Scripts and Dependencies
# -----------------------------------------------------------------------------

resource "aws_s3_object" "glue_script_extrai" {
  bucket     = aws_s3_bucket.artefacts.id
  key        = "scripts/extraiDados.py"
  source     = "${path.module}/glueClima/extraiDados.py"
  kms_key_id = aws_kms_key.data_lake.arn
}

resource "aws_s3_object" "glue_script_transforma" {
  bucket     = aws_s3_bucket.artefacts.id
  key        = "scripts/transformaDados.py"
  source     = "${path.module}/glueClima/transformaDados.py"
  kms_key_id = aws_kms_key.data_lake.arn
}

resource "aws_s3_object" "glue_lib_zip" {
  bucket     = aws_s3_bucket.artefacts.id
  key        = "libs/lib.zip"
  source     = "${path.module}/glueClima/lib.zip"
  kms_key_id = aws_kms_key.data_lake.arn
}

# -----------------------------------------------------------------------------
# Athena / Glue Catalog Database
# -----------------------------------------------------------------------------

resource "aws_glue_catalog_database" "silver" {
  name         = "silver"
  description  = "Athena/Glue database backed by silver layer S3 bucket"
  location_uri = "s3://${aws_s3_bucket.silver.id}/"
}

# -----------------------------------------------------------------------------
# IAM Role and Policy for AWS Glue
# -----------------------------------------------------------------------------

resource "aws_iam_role" "glue_role" {
  name = "benchmark-glue-data-lake-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "glue.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "glue_policy" {
  name        = "benchmark-glue-data-lake-policy"
  description = "Permissions for Glue jobs covering S3, CloudWatch Logs, KMS, Secrets Manager, and Catalog"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3DataLakeBucketAccess"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = [
          aws_s3_bucket.artefacts.arn,
          aws_s3_bucket.staging.arn,
          aws_s3_bucket.bronze.arn,
          aws_s3_bucket.silver.arn,
          aws_s3_bucket.gold.arn,
          aws_s3_bucket.logs.arn
        ]
      },
      {
        Sid    = "S3DataLakeObjectAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = [
          "${aws_s3_bucket.artefacts.arn}/*",
          "${aws_s3_bucket.staging.arn}/*",
          "${aws_s3_bucket.bronze.arn}/*",
          "${aws_s3_bucket.silver.arn}/*",
          "${aws_s3_bucket.gold.arn}/*",
          "${aws_s3_bucket.logs.arn}/*"
        ]
      },
      {
        Sid    = "CloudWatchLogsAccess"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          "arn:aws:logs:${local.region}:${local.account_id}:log-group:/aws-glue/*"
        ]
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:Encrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = [
          aws_kms_key.data_lake.arn
        ]
      },
      {
        Sid    = "SecretsManagerAccess"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = [
          "arn:aws:secretsmanager:${local.region}:${local.account_id}:secret:benchmark/*"
        ]
      },
      {
        Sid    = "GlueCatalogAccess"
        Effect = "Allow"
        Action = [
          "glue:GetDatabase",
          "glue:GetDatabases",
          "glue:GetTable",
          "glue:GetTables",
          "glue:GetPartition",
          "glue:GetPartitions",
          "glue:CreateTable",
          "glue:UpdateTable",
          "glue:DeleteTable",
          "glue:BatchCreatePartition",
          "glue:BatchDeletePartition"
        ]
        Resource = [
          "arn:aws:glue:${local.region}:${local.account_id}:catalog",
          "arn:aws:glue:${local.region}:${local.account_id}:database/silver",
          "arn:aws:glue:${local.region}:${local.account_id}:database/default",
          "arn:aws:glue:${local.region}:${local.account_id}:table/silver/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "glue_attach" {
  role       = aws_iam_role.glue_role.name
  policy_arn = aws_iam_policy.glue_policy.arn
}

# -----------------------------------------------------------------------------
# AWS Glue Jobs (Glue 4.0)
# -----------------------------------------------------------------------------

resource "aws_glue_job" "extrai_dados" {
  name              = "glue-job-extrai-dados"
  role_arn          = aws_iam_role.glue_role.arn
  glue_version      = "4.0"
  worker_type       = "G.1X"
  number_of_workers = 20
  max_retries       = 0
  timeout           = 2880

  execution_property {
    max_concurrent_runs = 2
  }

  command {
    name            = "glueetl"
    script_location = "s3://${aws_s3_bucket.artefacts.id}/scripts/extraiDados.py"
    python_version  = "3"
  }

  default_arguments = {
    "--TempDir"                          = "s3://${aws_s3_bucket.logs.id}/temporary/"
    "--job-bookmark-option"              = "job-bookmark-disable"
    "--enable-metrics"                   = "true"
    "--enable-continuous-cloudwatch-log" = "true"
  }
}

resource "aws_glue_job" "transforma_dados" {
  name              = "glue-job-transforma-dados"
  role_arn          = aws_iam_role.glue_role.arn
  glue_version      = "4.0"
  worker_type       = "G.1X"
  number_of_workers = 20
  max_retries       = 0
  timeout           = 2880

  execution_property {
    max_concurrent_runs = 2
  }

  command {
    name            = "glueetl"
    script_location = "s3://${aws_s3_bucket.artefacts.id}/scripts/transformaDados.py"
    python_version  = "3"
  }

  default_arguments = {
    "--TempDir"                          = "s3://${aws_s3_bucket.logs.id}/temporary/"
    "--job-bookmark-option"              = "job-bookmark-disable"
    "--enable-metrics"                   = "true"
    "--enable-continuous-cloudwatch-log" = "true"
    "--datalake-formats"                 = "iceberg"
    "--extra-py-files"                   = "s3://${aws_s3_bucket.artefacts.id}/libs/lib.zip"
  }
}

# -----------------------------------------------------------------------------
# Step Functions Orchestration
# -----------------------------------------------------------------------------

resource "aws_iam_role" "step_functions" {
  name = "benchmark-sfn-pipeline-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "states.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "step_functions_glue" {
  name        = "benchmark-sfn-glue-policy"
  description = "Allows Step Functions state machine to run and monitor extraction and transformation Glue jobs"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ManageGlueJobs"
        Effect = "Allow"
        Action = [
          "glue:StartJobRun",
          "glue:GetJobRun",
          "glue:GetJobRuns",
          "glue:BatchStopJobRun"
        ]
        Resource = [
          aws_glue_job.extrai_dados.arn,
          aws_glue_job.transforma_dados.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "step_functions_attach" {
  role       = aws_iam_role.step_functions.name
  policy_arn = aws_iam_policy.step_functions_glue.arn
}

resource "aws_sfn_state_machine" "weather_pipeline" {
  name     = "weather-data-pipeline-state-machine"
  role_arn = aws_iam_role.step_functions.arn

  definition = jsonencode({
    Comment = "Orchestrate Weather Data Extraction and Transformation Glue Jobs"
    StartAt = "RunExtractionJob"
    States = {
      RunExtractionJob = {
        Type     = "Task"
        Resource = "arn:aws:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.extrai_dados.name
          Arguments = {
            "--city"           = "Sao Paulo"
            "--staging_bucket" = "s3://${aws_s3_bucket.staging.id}/"
            "--api_key"        = "PLACEHOLDER_API_KEY"
          }
        }
        Next = "RunTransformationJob"
      }
      RunTransformationJob = {
        Type     = "Task"
        Resource = "arn:aws:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.transforma_dados.name
          Arguments = {
            "--staging_bucket" = "s3://${aws_s3_bucket.staging.id}/"
            "--bronze_bucket"  = "s3://${aws_s3_bucket.bronze.id}/"
            "--silver_bucket"  = "s3://${aws_s3_bucket.silver.id}/"
            "--translation_key" = "PLACEHOLDER_TRANSLATION_KEY"
          }
        }
        End = true
      }
    }
  })
}

# -----------------------------------------------------------------------------
# EventBridge Hourly Scheduler
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eventbridge" {
  name = "benchmark-eventbridge-sfn-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "eventbridge_sfn" {
  name        = "benchmark-eventbridge-sfn-policy"
  description = "Allows EventBridge rule to start execution of the weather data pipeline state machine"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "StartPipelineExecution"
        Effect = "Allow"
        Action = [
          "states:StartExecution"
        ]
        Resource = [
          aws_sfn_state_machine.weather_pipeline.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eventbridge_attach" {
  role       = aws_iam_role.eventbridge.name
  policy_arn = aws_iam_policy.eventbridge_sfn.arn
}

resource "aws_cloudwatch_event_rule" "hourly_pipeline" {
  name                = "benchmark-weather-pipeline-hourly-rule"
  description         = "Triggers the weather data pipeline state machine on an hourly schedule"
  schedule_expression = "rate(1 hour)"
}

resource "aws_cloudwatch_event_target" "trigger_sfn" {
  rule      = aws_cloudwatch_event_rule.hourly_pipeline.name
  target_id = "TriggerWeatherPipelineStateMachine"
  arn       = aws_sfn_state_machine.weather_pipeline.arn
  role_arn  = aws_iam_role.eventbridge.arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "github_owner" {
  type        = string
  description = "GitHub repository owner/organization."
  default     = "example-owner"
}

variable "github_repo" {
  type        = string
  description = "GitHub repository name."
  default     = "example-repo"
}

variable "github_branch" {
  type        = string
  description = "GitHub repository branch to track."
  default     = "master"
}

variable "codestar_connection_arn" {
  type        = string
  description = "Optional AWS CodeStar Connections ARN. If provided, CodePipeline uses CodeStarSourceConnection instead of GitHub OAuth."
  default     = ""
}

variable "enable_pipeline_notifications" {
  type        = bool
  description = "Whether to enable SNS pipeline status notifications."
  default     = false
}

variable "enable_artifact_bucket_logging" {
  type        = bool
  description = "Whether to enable access logging for the pipeline artifact bucket."
  default     = false
}

variable "invalidate_cloudfront_cache" {
  type        = bool
  description = "Whether the build process should trigger a CloudFront cache invalidation."
  default     = true
}

# -----------------------------------------------------------------------------
# Local Values
# -----------------------------------------------------------------------------
locals {
  account_id           = data.aws_caller_identity.current.account_id
  region               = data.aws_region.current.name
  target_bucket_name   = "benchmark-cicd-target-${local.account_id}"
  artifact_bucket_name = "benchmark-cicd-artifacts-${local.account_id}"
  logging_bucket_name  = "benchmark-cicd-logs-${local.account_id}"
  use_codestar         = var.codestar_connection_arn != ""
}

# -----------------------------------------------------------------------------
# Customer Managed KMS Key & Key Policy
# -----------------------------------------------------------------------------
resource "aws_kms_key" "cicd" {
  description             = "KMS Key for CI/CD pipeline, S3 buckets, and SSM parameters"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCodeBuildAndCodePipelineServices"
        Effect = "Allow"
        Principal = {
          AWS = [
            aws_iam_role.codebuild_role.arn,
            aws_iam_role.codepipeline_role.arn
          ]
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "cicd" {
  name          = "alias/benchmark-cicd-key"
  target_key_id = aws_kms_key.cicd.key_id
}

# -----------------------------------------------------------------------------
# S3 Buckets: Target Website & Artifact Buckets
# -----------------------------------------------------------------------------
# Target Website Bucket
resource "aws_s3_bucket" "target" {
  bucket = local.target_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "target" {
  bucket = aws_s3_bucket.target.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "target" {
  bucket = aws_s3_bucket.target.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cicd.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "target" {
  bucket = aws_s3_bucket.target.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Pipeline Artifact Bucket
resource "aws_s3_bucket" "artifact" {
  bucket = local.artifact_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "artifact" {
  bucket = aws_s3_bucket.artifact.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact" {
  bucket = aws_s3_bucket.artifact.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cicd.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifact" {
  bucket = aws_s3_bucket.artifact.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "artifact_tls_deny" {
  bucket = aws_s3_bucket.artifact.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnforceTLSRequestsOnly"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.artifact.arn,
          "${aws_s3_bucket.artifact.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# Optional Access Logging Bucket for Artifacts
resource "aws_s3_bucket" "logging" {
  count  = var.enable_artifact_bucket_logging ? 1 : 0
  bucket = local.logging_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "logging" {
  count  = var.enable_artifact_bucket_logging ? 1 : 0
  bucket = aws_s3_bucket.logging[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count  = var.enable_artifact_bucket_logging ? 1 : 0
  bucket = aws_s3_bucket.logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cicd.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count  = var.enable_artifact_bucket_logging ? 1 : 0
  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "artifact" {
  count  = var.enable_artifact_bucket_logging ? 1 : 0
  bucket = aws_s3_bucket.artifact.id

  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = "artifact-logs/"
}

# -----------------------------------------------------------------------------
# CloudFront Distribution & Origin Access Control (OAC)
# -----------------------------------------------------------------------------
resource "aws_cloudfront_origin_access_control" "oac" {
  name                              = "benchmark-cicd-oac"
  description                       = "OAC for static website target S3 bucket"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_cloudfront_distribution" "site" {
  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = "index.html"
  comment             = "Static website distribution for CI/CD"

  origin {
    domain_name              = aws_s3_bucket.target.bucket_regional_domain_name
    origin_id                = "S3-${aws_s3_bucket.target.id}"
    origin_access_control_id = aws_cloudfront_origin_access_control.oac.id
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3-${aws_s3_bucket.target.id}"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

resource "aws_s3_bucket_policy" "target_oac_policy" {
  bucket = aws_s3_bucket.target.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudFrontOACReadOnly"
        Effect    = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.target.arn}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.site.arn
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# SSM SecureString Parameters (GitHub OAuth Token & Webhook Secret)
# -----------------------------------------------------------------------------
resource "aws_ssm_parameter" "github_token" {
  name        = "/benchmark-cicd/github/token"
  description = "GitHub OAuth Personal Access Token placeholder"
  type        = "SecureString"
  value       = "PLACEHOLDER_TOKEN"
  key_id      = aws_kms_key.cicd.arn

  lifecycle {
    ignore_changes = [value]
  }
}

resource "aws_ssm_parameter" "github_webhook_secret" {
  name        = "/benchmark-cicd/github/webhook-secret"
  description = "GitHub Webhook HMAC Secret placeholder"
  type        = "SecureString"
  value       = "PLACEHOLDER_SECRET"
  key_id      = aws_kms_key.cicd.arn

  lifecycle {
    ignore_changes = [value]
  }
}

# -----------------------------------------------------------------------------
# CloudWatch Logs & IAM Role for CodeBuild
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "codebuild" {
  name              = "/aws/codebuild/benchmark-cicd-build"
  retention_in_days = 30
}

resource "aws_iam_role" "codebuild_role" {
  name = "benchmark-cicd-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "codebuild_policy" {
  name = "benchmark-cicd-codebuild-policy"
  role = aws_iam_role.codebuild_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogsAccess"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.codebuild.arn}:*"
      },
      {
        Sid    = "TargetAndArtifactS3Access"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:DeleteObject"
        ]
        Resource = [
          aws_s3_bucket.target.arn,
          "${aws_s3_bucket.target.arn}/*",
          aws_s3_bucket.artifact.arn,
          "${aws_s3_bucket.artifact.arn}/*"
        ]
      },
      {
        Sid    = "KmsKeyAccess"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.cicd.arn
      },
      {
        Sid    = "CloudFrontInvalidationAccess"
        Effect = "Allow"
        Action = [
          "cloudfront:CreateInvalidation",
          "cloudfront:GetInvalidation",
          "cloudfront:ListInvalidations"
        ]
        Resource = aws_cloudfront_distribution.site.arn
      },
      {
        Sid    = "SSMParametersAccess"
        Effect = "Allow"
        Action = [
          "ssm:GetParameters",
          "ssm:GetParameter"
        ]
        Resource = [
          aws_ssm_parameter.github_token.arn,
          aws_ssm_parameter.github_webhook_secret.arn
        ]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# AWS CodeBuild Project
# -----------------------------------------------------------------------------
resource "aws_codebuild_project" "build" {
  name          = "benchmark-cicd-build"
  description   = "Builds static site and uploads to target S3 bucket"
  build_timeout = 5
  service_role  = aws_iam_role.codebuild_role.arn

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:5.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "TARGET_BUCKET"
      value = aws_s3_bucket.target.id
    }

    environment_variable {
      name  = "CLOUDFRONT_DISTRIBUTION_ID"
      value = aws_cloudfront_distribution.site.id
    }

    environment_variable {
      name  = "INVALIDATE_CACHE"
      value = tostring(var.invalidate_cloudfront_cache)
    }
  }

  logs_config {
    cloudwatch_logs {
      group_name  = aws_cloudwatch_log_group.codebuild.name
      status      = "ENABLED"
      stream_name = "build-log"
    }
    s3_logs {
      status = "DISABLED"
    }
  }

  source {
    type = "CODEPIPELINE"
  }
}

# -----------------------------------------------------------------------------
# IAM Role for AWS CodePipeline
# -----------------------------------------------------------------------------
resource "aws_iam_role" "codepipeline_role" {
  name = "benchmark-cicd-codepipeline-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codepipeline.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "codepipeline_policy" {
  name = "benchmark-cicd-codepipeline-policy"
  role = aws_iam_role.codepipeline_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ArtifactBucketAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:GetBucketVersioning",
          "s3:PutObject",
          "s3:PutObjectAcl"
        ]
        Resource = [
          aws_s3_bucket.artifact.arn,
          "${aws_s3_bucket.artifact.arn}/*"
        ]
      },
      {
        Sid    = "CodeBuildAccess"
        Effect = "Allow"
        Action = [
          "codebuild:BatchGetBuilds",
          "codebuild:StartBuild"
        ]
        Resource = aws_codebuild_project.build.arn
      },
      {
        Sid    = "KmsAccess"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.cicd.arn
      },
      {
        Sid    = "CodeStarConnectionAccess"
        Effect = "Allow"
        Action = [
          "codestar-connections:UseConnection"
        ]
        Resource = var.codestar_connection_arn != "" ? var.codestar_connection_arn : "arn:aws:codestar-connections:${local.region}:${local.account_id}:connection/*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Optional SNS Topic & CodeStar Notifications
# -----------------------------------------------------------------------------
resource "aws_sns_topic" "pipeline_notifications" {
  count             = var.enable_pipeline_notifications ? 1 : 0
  name              = "benchmark-cicd-pipeline-notifications"
  kms_master_key_id = aws_kms_key.cicd.id
}

resource "aws_sns_topic_policy" "pipeline_notifications" {
  count  = var.enable_pipeline_notifications ? 1 : 0
  arn    = aws_sns_topic.pipeline_notifications[0].arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCodeStarNotificationsPublish"
        Effect = "Allow"
        Principal = {
          Service = "codestar-notifications.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.pipeline_notifications[0].arn
      }
    ]
  })
}

resource "aws_codestarnotifications_notification_rule" "pipeline" {
  count       = var.enable_pipeline_notifications ? 1 : 0
  name        = "benchmark-cicd-pipeline-rule"
  detail_type = "FULL"
  event_type_ids = [
    "codepipeline-pipeline-pipeline-execution-failed",
    "codepipeline-pipeline-pipeline-execution-succeeded",
    "codepipeline-pipeline-pipeline-execution-started"
  ]
  resource = aws_codepipeline.pipeline.arn

  target {
    address = aws_sns_topic.pipeline_notifications[0].arn
    type    = "SNS"
  }
}

# -----------------------------------------------------------------------------
# AWS CodePipeline
# -----------------------------------------------------------------------------
resource "aws_codepipeline" "pipeline" {
  name     = "benchmark-cicd-pipeline"
  role_arn = aws_iam_role.codepipeline_role.arn

  artifact_store {
    location = aws_s3_bucket.artifact.id
    type     = "S3"

    encryption_key {
      id   = aws_kms_key.cicd.arn
      type = "KMS"
    }
  }

  stage {
    name = "Source"

    dynamic "action" {
      for_each = local.use_codestar ? [1] : []
      content {
        name             = "Source"
        category         = "Source"
        owner            = "AWS"
        provider         = "CodeStarSourceConnection"
        version          = "1"
        output_artifacts = ["source_output"]

        configuration = {
          ConnectionArn    = var.codestar_connection_arn
          FullRepositoryId = "${var.github_owner}/${var.github_repo}"
          BranchName       = var.github_branch
        }
      }
    }

    dynamic "action" {
      for_each = local.use_codestar ? [] : [1]
      content {
        name             = "Source"
        category         = "Source"
        owner            = "ThirdParty"
        provider         = "GitHub"
        version          = "1"
        output_artifacts = ["source_output"]

        configuration = {
          Owner      = var.github_owner
          Repo       = var.github_repo
          Branch     = var.github_branch
          OAuthToken = aws_ssm_parameter.github_token.value
        }
      }
    }
  }

  stage {
    name = "Build"

    action {
      name             = "Build"
      category         = "Build"
      owner            = "AWS"
      provider         = "CodeBuild"
      version          = "1"
      input_artifacts  = ["source_output"]
      output_artifacts = ["build_output"]

      configuration = {
        ProjectName = aws_codebuild_project.build.name
      }
    }
  }
}

# -----------------------------------------------------------------------------
# GitHub Webhook (used when CodeStar connection is not configured)
# -----------------------------------------------------------------------------
resource "aws_codepipeline_webhook" "github_webhook" {
  count           = local.use_codestar ? 0 : 1
  name            = "benchmark-cicd-github-webhook"
  authentication  = "GITHUB_HMAC"
  target_action   = "Source"
  target_pipeline = aws_codepipeline.pipeline.name

  authentication_configuration {
    secret_token = aws_ssm_parameter.github_webhook_secret.value
  }

  filter {
    json_path    = "$.ref"
    match_equals = "refs/heads/${var.github_branch}"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "create_vpc" {
  description = "Controls if VPC and all associated resources should be created"
  type        = bool
  default     = true
}

variable "vpc_name" {
  description = "Name tag for the VPC and prefix for dependent resources"
  type        = string
  default     = "main"
}

variable "cidr_block" {
  description = "The IPv4 CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_tenancy" {
  description = "A tenancy option for instances launched into the VPC"
  type        = string
  default     = "default"
}

variable "enable_dns_support" {
  description = "Should be true to enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "Should be true to enable DNS hostnames in the VPC"
  type        = bool
  default     = false
}

variable "single_nat_gateway" {
  description = "Should be true if you want to provision a single shared NAT Gateway across all private networks"
  type        = bool
  default     = true
}

variable "subnet_definitions" {
  description = "List of subnet group definitions. Defaults to empty, resulting in no subnets or dependent resources."
  type = list(object({
    name                     = string
    class                    = string # "public", "private", or "intra"
    subnets                  = list(string)
    create_db_subnet_group   = optional(bool, false)
    create_elasticache_group = optional(bool, false)
  }))
  default = []
}

variable "tags" {
  description = "Additional tags for all resources"
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  create_vpc = var.create_vpc

  # Flatten subnet definitions across AZs
  flattened_subnets = local.create_vpc ? merge([
    for def in var.subnet_definitions : {
      for idx, cidr in def.subnets :
      "${def.name}-${data.aws_availability_zones.available.names[idx % length(data.aws_availability_zones.available.names)]}" => {
        name                     = def.name
        class                    = lower(def.class)
        cidr_block               = cidr
        availability_zone        = data.aws_availability_zones.available.names[idx % length(data.aws_availability_zones.available.names)]
        create_db_subnet_group   = coalesce(def.create_db_subnet_group, false)
        create_elasticache_group = coalesce(def.create_elasticache_group, false)
      }
    }
  ]...) : {}

  public_subnets = {
    for k, v in local.flattened_subnets : k => v if v.class == "public"
  }

  private_subnets = {
    for k, v in local.flattened_subnets : k => v if v.class == "private"
  }

  intra_subnets = {
    for k, v in local.flattened_subnets : k => v if v.class == "intra"
  }

  has_public_subnets  = length(local.public_subnets) > 0
  has_private_subnets = length(local.private_subnets) > 0

  # Determine NAT gateway placement
  # Single NAT placed in the first public subnet AZ, or multi NAT placed in each unique public AZ
  public_azs = distinct([for s in local.public_subnets : s.availability_zone])

  nat_gateway_azs = (local.create_vpc && local.has_public_subnets && local.has_private_subnets) ? (
    var.single_nat_gateway ? slice(local.public_azs, 0, 1) : local.public_azs
  ) : []

  # Find the first public subnet key for each NAT AZ
  nat_subnet_map = {
    for az in local.nat_gateway_azs : az => [
      for k, v in local.public_subnets : k if v.availability_zone == az
    ][0]
  }

  # Unique AZs for private route tables
  private_azs = distinct([for s in local.private_subnets : s.availability_zone])

  # Subnets designated for DB Subnet Group
  db_subnets = {
    for k, v in local.flattened_subnets : k => v if v.create_db_subnet_group
  }

  # Subnets designated for ElastiCache Subnet Group
  elasticache_subnets = {
    for k, v in local.flattened_subnets : k => v if v.create_elasticache_group
  }
}

resource "aws_vpc" "main" {
  count = local.create_vpc ? 1 : 0

  cidr_block                       = var.cidr_block
  instance_tenancy                 = var.instance_tenancy
  enable_dns_support               = var.enable_dns_support
  enable_dns_hostnames             = var.enable_dns_hostnames
  assign_generated_ipv6_cidr_block = false

  tags = merge(
    var.tags,
    {
      Name = var.vpc_name
    }
  )
}

resource "aws_subnet" "subnets" {
  for_each = local.flattened_subnets

  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = each.value.cidr_block
  availability_zone       = each.value.availability_zone
  map_public_ip_on_launch = each.value.class == "public"

  tags = merge(
    var.tags,
    {
      Name  = "${var.vpc_name}-${each.key}"
      Class = each.value.class
    }
  )
}

resource "aws_internet_gateway" "main" {
  count = (local.create_vpc && local.has_public_subnets) ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-igw"
    }
  )
}

resource "aws_eip" "nat" {
  for_each = toset(local.nat_gateway_azs)

  domain = "vpc"

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-nat-${each.value}"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  for_each = toset(local.nat_gateway_azs)

  allocation_id = aws_eip.nat[each.value].id
  subnet_id     = aws_subnet.subnets[local.nat_subnet_map[each.value]].id

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-nat-${each.value}"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  count = (local.create_vpc && local.has_public_subnets) ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-public"
    }
  )
}

resource "aws_route_table_association" "public" {
  for_each = local.public_subnets

  subnet_id      = aws_subnet.subnets[each.key].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table" "private" {
  for_each = local.has_private_subnets ? (
    var.single_nat_gateway ? toset(["single"]) : toset(local.private_azs)
  ) : toset([])

  vpc_id = aws_vpc.main[0].id

  dynamic "route" {
    for_each = length(local.nat_gateway_azs) > 0 ? [1] : []
    content {
      cidr_block     = "0.0.0.0/0"
      nat_gateway_id = var.single_nat_gateway ? aws_nat_gateway.main[local.nat_gateway_azs[0]].id : aws_nat_gateway.main[each.value].id
    }
  }

  tags = merge(
    var.tags,
    {
      Name = var.single_nat_gateway ? "${var.vpc_name}-private" : "${var.vpc_name}-private-${each.value}"
    }
  )
}

resource "aws_route_table_association" "private" {
  for_each = local.private_subnets

  subnet_id = aws_subnet.subnets[each.key].id
  route_table_id = var.single_nat_gateway ? (
    aws_route_table.private["single"].id
    ) : (
    aws_route_table.private[each.value.availability_zone].id
  )
}

resource "aws_route_table" "intra" {
  count = (local.create_vpc && length(local.intra_subnets) > 0) ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-intra"
    }
  )
}

resource "aws_route_table_association" "intra" {
  for_each = local.intra_subnets

  subnet_id      = aws_subnet.subnets[each.key].id
  route_table_id = aws_route_table.intra[0].id
}

resource "aws_db_subnet_group" "main" {
  count = (local.create_vpc && length(local.db_subnets) > 0) ? 1 : 0

  name        = "${var.vpc_name}-db-subnet-group"
  description = "Database subnet group for ${var.vpc_name}"
  subnet_ids  = [for k in keys(local.db_subnets) : aws_subnet.subnets[k].id]

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-db-subnet-group"
    }
  )
}

resource "aws_elasticache_subnet_group" "main" {
  count = (local.create_vpc && length(local.elasticache_subnets) > 0) ? 1 : 0

  name        = "${var.vpc_name}-elasticache-subnet-group"
  description = "ElastiCache subnet group for ${var.vpc_name}"
  subnet_ids  = [for k in keys(local.elasticache_subnets) : aws_subnet.subnets[k].id]

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-elasticache-subnet-group"
    }
  )
}

output "vpc_id" {
  description = "The ID of the VPC"
  value       = try(aws_vpc.main[0].id, null)
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC"
  value       = try(aws_vpc.main[0].cidr_block, null)
}

output "subnet_ids" {
  description = "Map of all subnet IDs keyed by subnet name-az"
  value       = { for k, v in aws_subnet.subnets : k => v.id }
}

output "public_subnet_ids" {
  description = "List of public subnet IDs"
  value       = [for k in keys(local.public_subnets) : aws_subnet.subnets[k].id]
}

output "private_subnet_ids" {
  description = "List of private subnet IDs"
  value       = [for k in keys(local.private_subnets) : aws_subnet.subnets[k].id]
}

output "intra_subnet_ids" {
  description = "List of intra subnet IDs"
  value       = [for k in keys(local.intra_subnets) : aws_subnet.subnets[k].id]
}

output "nat_gateway_ids" {
  description = "List of NAT Gateway IDs"
  value       = [for nat in aws_nat_gateway.main : nat.id]
}

output "internet_gateway_id" {
  description = "The ID of the Internet Gateway"
  value       = try(aws_internet_gateway.main[0].id, null)
}

output "db_subnet_group_name" {
  description = "The name of the DB subnet group"
  value       = try(aws_db_subnet_group.main[0].name, null)
}

output "elasticache_subnet_group_name" {
  description = "The name of the ElastiCache subnet group"
  value       = try(aws_elasticache_subnet_group.main[0].name, null)
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ec2_ssm_association" {
  name               = "ec2-ssm-association"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

resource "aws_iam_role_policy_attachment" "ssm_managed_instance_core" {
  role       = aws_iam_role.ec2_ssm_association.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2_s3_ssm_association" {
  name = "ec2-s3-ssm-association"
  role = aws_iam_role.ec2_ssm_association.name
}
